[Prop CM LT of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For all sufficiently small $r > 0$,
  we have the following.
  For any $x_0 \in M$ and $\eta \in (0, \infty)$, it holds that
  \begin{equation}
    \frac{1}{\mu(B(x_0,r))}
    \int_{B(x_0,r)}
    \hat{P}_{\diag(x)}\!
    \left(
      \Pi_{r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x, 2r)) < \eta r^{d^{\mathrm{min}}_\mathrm{w}d_{\mathrm{ct}}}
    \right)
    \mu(dx)
    \leq \tilde{c} \eta.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:one-dimensional-characterization of arXiv:2607.25616, 'Stealthy point processes and lattice induction'] Let $(X,\mu)$ be an ergodic probability-preserving Borel
$\mathbb R$-space. Then the following are equivalent:
\begin{enumerate}
\item
$(X,\mu)$ is lattice-induced;

\item
$(X,\mu)$ admits a generating stealthy Delone cross-section.
\end{enumerate}

[Thm Trigonometric Coloumb gas integral formula of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] If we choose 
$\sigma_j=a=\sqrt{\frac{2}{\kappa}}, \quad \lambda_j=\frac{a^2}{2}-ab=\frac{6-\kappa}{2\kappa}, \quad 1 \leq j \leq n$
then we have

\begin{equation}
\begin{aligned}
& \left[\frac{\kappa}{2}\partial^{2}_{j}+\sum_{k \neq j}\left(\cot \left(\frac{z_k-z_j}{2}\right) \partial_k-\frac{(6-\kappa)/2\kappa}{2 \sin ^2\left(\frac{z_k-z_j}{2}\right)}\right)\right] \Phi\left(z_1, z_2, \ldots, z_{n+m+2}\right)\\
&=\sum_{k=n+1}^{n+m} \partial_k\left(\cot\left(\frac{z_k-z_j}{2}\right)\Phi\left(z_1, z_2, \ldots, z_{n+m+2}\right)\right)-\left[\frac{1}{2 \kappa}\left(n-2 p+\frac{\kappa}{2} q\right)^2-\frac{1}{2 \kappa}\right]\Phi\left(z_1, z_2, \ldots, z_{n+m+2}\right)
\end{aligned}
\end{equation}

for all $j \in\{1,2, \ldots, n\}$. The number of screening charges $\sigma_k= 2a$ is given by $p$, and the number of screening charges $\sigma_k= 2(a+b)$ is given by $q$, with $m=p+q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 132 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $x \in [0, a]$. Recalling $A = A_x$ from \eqref{af0}, we have 
	\begin{flalign*}
		\xi_x' = -\displaystyle\frac{\mathfrak{q}^{x+2\xi_x-2\gamma_x} (\log \mathfrak{q})^2}{A (\mathfrak{q}^{x+\xi_x-\gamma_x}-1)^2}.
	\end{flalign*}

A Bousfield localization functor $L: \mathcal{T} \to \mathcal{T}$ on a tensor-triangulated category is called smashing if the canonical map $X \otimes L(\mathbb{I}) \to L(X)$ is an isomorphism for every object $X \in \mathcal{T}$. Equivalently, $L$ preserves arbitrary coproducts.
L is a Bousfield localization functor
\mathbb{I} is the unit object of \mathcal{T}

[Lemma lem_loc of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under (main_assm of the paper), for any small constant $\tau>0$, the following local laws hold uniformly in $z=E+\mathrm{i}\eta $ with $|z|\le \tau^{-1}$ and $ \eta \ge N^{-1+\tau}$. 
\begin{itemize}
    \item  \textnormal{\textbf{Anisotropic local law:}} For any deterministic unit vectors $\mathbf{u}, \mathbf{v}\in \mathbb{C}^{DN}$, we have
\begin{equation}
 \left(G(z)-M(z)\right)_{\mathbf{u}\mathbf{v}}\prec \sqrt{\frac{\im m(z)}{N\eta}}+\frac{1}{N\eta}.
\end{equation}

\item  \textnormal{\textbf{Averaged local law:}} For any deterministic matrix $B \in \mathbb{C}^{DN\times DN}$ with $\|B\|\le 1$, we have 
\begin{equation}
 \left\langle \left(G-M\right) B\right\rangle \prec \frac{1}{ N\eta } .
\end{equation}

\end{itemize}
As a consequence of (equation eq:aver_local of the paper) when $B=I$, we have the rigidity of eigenvalues:
\begin{equation}
\lvert \lambda_k-\gamma_k \rvert \prec N^{-2/3}\mathfrak{r}\left({k}\right)^{-1/3},\quad \forall 1\le k\le DN. 
\end{equation}
In addition, all the above estimates remain valid even if we do not assume identical distributions for the diagonal and off-diagonal entries of $H$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:part-fun of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ be such that $\mu\gg1/\sqrt{n}$. Then the partition function $Z_n$ as defined in~(equation eq:part fun of the paper) behaves according to the following regimes.
    \begin{itemize}
        \item[$\mathbf{(1)}$] If $1/\sqrt{n}\ll\mu\ll n^{1/4}$, we have
        \begin{align*}
            Z_n=\big(1+o(1)\big)4^ne^\mu(e^\mu-1)\frac{\pi^{5/6}}{2^{1/3}3^{1/2}}\frac{\mu^{1/3}}{n^{5/6}}\exp\left(-3\left(\frac{\pi^2\mu^2n}{4}\right)^{1/3}\right)\,.
        \end{align*}
        \item[$\mathbf{(2)}$] If $(\log^{3/2}n)/\sqrt{n}\ll\mu\ll n$, we have
        \begin{align*}
            Z_n=\big(1+o(1)\big)4^ne^{\mu}(e^\mu-1)\frac{\mu}{2n}e^{-n\lambda_{\mu/n}(t_{\mu/n})}\sum_{m\in\mathbb Z}\exp\left(-\left(\frac{3}{2}+o(1)\right)\left(\frac{\mu^4}{2\pi^2n}\right)^{1/3}(m-t_{\mu/n})^2\right)\,.
        \end{align*}
        \item[$\mathbf{(3)}$] If $n^{1/4}\ll\mu$, we have
        \begin{align*}
            Z_n=\big(1+o(1)\big)4^ne^{2\mu}\sum_{m=\max\{\lfloor t_{\mu/n}\rfloor,3\}}^{\lceil t_{\mu/n}\rceil}\frac{\tan^2\left(\frac{\pi}{m}\right)}{m}e^{-n\lambda_{\mu/n}(m)}\,.
        \end{align*}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:cox of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $(\lambda^k)_{k \in \mathbb{N}^*}$ be a sequence of measurable processes, satisfying $c \leq \lambda^k \leq C$ $(\mathbb{P} \otimes dt)$-a.e., $\forall\, k \in \mathbb{N}^*$, for some constants $0 < c < C$. Suppose that $\Omega$ supports a sequence of i.i.d.\ $\operatorname{Exp}(1)$ random variables $(E_k)_{k \in \mathbb{N}^*}$ and a sequence of i.i.d.\ non-vanishing integrable random variables $(J_k)_{k \in \mathbb{N}^*}$ such that $\mathcal{F}_\infty$, $(E_k)_{k \in \mathbb{N}^*}$ and $(J_k)_{k \in \mathbb{N}^*}$ are independent. Let $\tau_0 \coloneqq 0$. For $k \in \mathbb{N}^*$, inductively define the random time
	\begin{equation*}
		\tau_k \coloneqq \inf\biggl\{t > \tau_{k-1}: \int_{\tau_{k-1}}^t \lambda^k_s \,ds \geq E_k\biggr\},
	\end{equation*}
	and define the filtration $\mathbb{A}^k = (\mathcal{A}^k_t)_{t \geq 0}$ by $\mathcal{A}^k_t \coloneqq \sigma(J_k \bm{1}_{\{\tau_k \leq s\}}; s \leq t)$. Let $\mathbb{G}^0 \coloneqq \mathbb{F}$, $\mathbb{G}^k \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^k \mathbb{A}^i)$ for $k \in \mathbb{N}^*$ and $\mathbb{G} \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^\infty \mathbb{A}^i)$. Suppose that each $\lambda^k$ is progressively measurable with respect to $\mathbb{G}^{k-1}$. Then, the pure jump process $X_t \coloneqq \sum_{k=1}^\infty J_k \bm{1}_{\{\tau_k \leq t\}}$, $t \geq 0$, is well-defined and the process
	\begin{equation*}
		M_t \coloneqq X_t - \mathbb{E}[J_1] \int_0^t \sum_{k=1}^\infty \bm{1}_{\{\tau_{k-1} < s \leq \tau_k\}} \lambda^k_s \,ds,\quad t \geq 0,
	\end{equation*}
	is a $\mathbb{G}$-martingale.

[Lemma 7 of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Let \( G_n = \operatorname{diag}(\sigma_1, \dots, \sigma_n) =\begin{pmatrix}
G_k & 0 \\
0 & \widetilde{G_k}
\end{pmatrix}\), where \( \sigma_i  \) is decreasing. Let $A \in \R ^{m\times n}$, $A_{ij}\stackrel{i.i.d}{\sim} \mathcal{N}(0,1)$. Then the following expectation identities hold:
\begin{align}
   \mathrm  E_A \left\| G_k P_{M_k^T} - G_k \right\|_F^2 + \| \widetilde{G_k }\|_F^2 =  \big\| G_n\big\|_F^2- \mathrm E_{A_k}\big\langle G_k^2,P_{M_k^T} \big\rangle.

\end{align}
\begin{align}
 \mathrm  E_{A} \left\| G_k (M_k)^\dagger M_k \right\|_F^2 =\mathrm E_{A_k} \left\| G_k (M_k)^\dagger \right\|_F^2 \sum_{i=k+1}^{n} \sigma_i^2.

\end{align}

