[Corollary cor:sw of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] For any $\alpha \subseteq K_{n, m}$, we have 
    \begin{align*}
        \underset{ \mathbf{X}_{\text{L}} ,  \mathbf{X}_{\text{R}} }{\mathbb{E}}{\big[ \textsc{Sw}(\alpha) \big] } \le \left( \frac{C|\alpha|^{3/2} \log(d)^{1/2}}{\sqrt{d}} \right)^{|\alpha|/2}.
    \end{align*}

[Lemma lem:LBJ-Sk-invariance of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] For $k = 1, 2$ and all $x, y \in \mathcal{V}^m$,
\begin{equation}
B_{\mathcal{S}_k u}
(\mathcal{S}_k x, \mathcal{S}_k y)
= B_u(x, y).
\end{equation}

[Lemma of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Consider any $r_1, \ldots, r_k \in \alpha \times \alpha$ such that ${\textsc{Supp}}(r_1, \ldots, r_k) = \alpha$. Then, for any $\beta \subsetneq \alpha$ and all $\mathbf{t}$, we have 
    \begin{align*}
         \Phi_{\beta}^{(r_1, \ldots, r_k)}(\mathbf{t}) = 0.
    \end{align*}

[Proposition prop:der-mart-multi-bis2 of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] There exists $t_{\textnormal{max}}\le -1$ and a constant $c > 0$ such that 
  \begin{equation}

    u(t, x) \geq c x\mathrm{e}^{-x}
  \end{equation}
  for all $t \leq t_{\textnormal{max}}$ and $x\in [4 \log \left |t \right|, \left |t \right|/8]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem l:104.4 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $W$ be a standard Gaussian, $Y, Y'$ be random variables taking values in some measurable space $\mathcal Y$ and independent of $W$, and 
$F: \mathcal Y \times \mathbb{R} \to \mathbb{R}$ a bounded measurable function. Then 
\begin{equation}
 \mathbb{E} F(Y,W+z) = \mathbb{E} F(Y',W+z) \,,\,\, \forall z \in \mathbb{R} \quad \Longrightarrow \quad \mathbb{E} F(Y,0) = \mathbb{E} F(Y',0) \,.
\end{equation}

