[Thm 9 of arXiv:2604.26499, 'Spectrum of Random Matrices with Exploding Moments'] \cite[Theorem 9]{weaver1985centrosymmetric}
 \begin{enumerate}[label=(\alph*)]

     \item  If $M=\left(\begin{array}{ll}A & B \\ C & D\end{array}\right)$ is an $N \times N$ centrosymmetric matrix with $N=2s$ and $A, B, C$, and $D \text{ are } s\times$ s matrices, then $M$ is orthogonally similar to
     \begin{align*}
         Q^T M Q=\left(\begin{array}{cc}
    A+J C & 0 \\
    0 & A-J C
\end{array}\right),
     \end{align*}
     where 
     \begin{align*}
         Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{ll}\mathbb{I} & -J \\ J & \mathbb{I}\end{array}\right).
     \end{align*}

     \item If $M=\left(\begin{array}{lll}A & x & B \\ y & q & yJ \\ C & Jx & D\end{array}\right)$ is an $N \times N$ centrosymmetric matrix with $N=2s+1$, and $A, B, C, D$  are  $s \times s$ matrices, $x$ is $s \times 1$ matrix, $y$ is $1 \times s$ matrix, and $q$ is a scalar, then $M$ is orthogonally similar to
     \begin{align*}
         Q^{T} M Q=\left(\begin{array}{ccc}
			A+J C & \sqrt{2} x & 0 \\
			\sqrt{2} y & q & 0 \\
			0 & 0 & A-J C
		\end{array}\right),
     \end{align*}
		where
  \begin{align*}
      Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{lll} \mathbb{I} & 0 & -J \\ 0 & \sqrt{2} & 0\\ J & 0 & \mathbb{I}\end{array}\right).
  \end{align*}
 \end{enumerate}
 Here $\mathbb{I}$ is the identity matrix and $J$ is the counter-identity matrix. In both cases $Q^TQ=\mathbb{I}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition {\cite{MR773445}} of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] A characteristic function $f$ is said to be \textit{geometrically infinitely divisible} if for every $p\in(0,1)$ there exists a characteristic function $g_p$ such that
    \begin{align}
        f(\xi)=\frac{p\,g_p(\xi)}{1-(1-p)g_p(\xi)}.
    \end{align}

[Proposition 22 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] For every $j\ge j_0$ there exist continuous representations
\[
 \tau_j:G_{\{p\}}\longrightarrow\GG(\Z/p^j\Z)
\]
and
\[
 \varrho_{j+R}:G_{\{p\}}
 \longrightarrow\GG(\Z/p^{j+R}\Z)
\]
such that
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\varrho_{j+R}\pmod{p^j}=\tau_j$;
\item $\tau_{j+1}\pmod{p^j}=\tau_j$;
\item $\varrho_{j+R}\pmod{p^R}=\rho_R$;
\item $\tau_{j_0}=\rho_{2A}^*\pmod{p^{j_0}}$.
\end{enumerate}

