[Proposition 7 of arXiv:2608.27093, 'Soliton Solutions to the Curvature Flow on the 2-dimensional De Sitter Space and Applicati'] Given a solution $(\alpha(s), \tau(s), \eta(s))$ of the system \eqref{c4e1} on some interval $I$  with fixed $a>0$,  and initial conditions $(\alpha(0),\tau(0),\eta(0))$ satisfying \eqref{e_i2}, there exists a smooth  spacelike curve or timelike curve  $X: I \rightarrow \mathbb{S}_{1}^{2}$, parametrized by arc length $s$,   such that its tangent and normal unit vetor fields $T$ and $N$  satisfy
	\begin{equation}
		\alpha(s)=\langle X(s),e\rangle,\hspace{.5 cm}\tau(s)=\langle T(s),e\rangle \hspace{.5 cm} \text{\rm e} \hspace{.5 cm} \eta(s)=\langle N(s),e\rangle, 
	\end{equation} 
	where $e=(-1,0,0)$  (respectively $e=(-1,1,0)$ and $e=(0,0,1)$).

[Lemma eq:I_n asymp of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] Assume $\alpha$, $\nu$, and $(j_n)_{n\in{\mathbb N}}$ satisfy the assumptions in Theorem (thm:1 of the paper). Then for every $t\in(1-\epsilon,1+\epsilon)$, 
 we have
\begin{equation}
I_{n,j_n}(t)\sim \alpha \Gamma(j_n)\nu\pp{\frac n{j_n}}t^\alpha.
\end{equation}
In particular, 
\begin{equation}
{\mathbb E} \wt C_{j_n}(nt) =\frac{I_{n,j_n}(t)}{\Gamma(j_n+1)} \sim \alpha t^\alpha \frac1{j_n}\nu\pp{\frac n{j_n}} = t^\alpha\sigma_{n,j_n}^2.
\end{equation}
Moreover, we have local uniform convergence in $t$ in the following sense:
\begin{align}
\lim_{n\to\infty}\sup_{t\in[1-\epsilon',1+\epsilon']}\abs{\frac{I_{n,j_n}(t)}{\alpha\Gamma(j_n)\nu(n/j_n) t^\alpha} - 1} = 0, \nonumber\\
\lim_{n\to\infty}\sup_{t\in[1-\epsilon',1+\epsilon']}\abs{\frac{{\mathbb E}\wt C_{j_n}(nt)}{\sigma_{n,j_n}^2 t^\alpha} - 1} = 0, 
\end{align}
for all $\epsilon'\in(0,\epsilon)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2604.07207, 'Mixing times of step-reinforced random walks'] For any $\alpha \in (0,1)$, any $n\geq k\geq 1$ and $\varepsilon>0$, one has
\begin{equation}

     \PP\left(  \left|\frac{N_k(n)}{n}  - \theta_k\right| \geq  \varepsilon\right) \leq C_1e^{-C_2 n}, 
  \end{equation}
where $C_1=C_1(\alpha,\varepsilon,k)$ and $C_2=C_2(\alpha,\varepsilon,k)$ are positive constants. Moreover, for any $\alpha \in [0,1)$ and $n\geq 1$, one has
    \begin{equation}

       \PP\left(I(n) \leq  \frac{(1-\alpha)n}{8}\right) \leq 5e^{-\frac{3(1-\alpha)n}{280}}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 68 (Real tree coded by a function, {\cite[Section 3) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {abraham2013note}}]
  Let $f:[0,\infty)\to [0,\infty)$ be a compactly supported continuous function and set 
  \[ \sigma_f=\sup\{t>0:f(t)>0\}<\infty.\]
  Define a  semi-metric $\bar{d}^f$ on $[0,\sigma_f]$ by setting
  \begin{align*}
    \bar{d}^f(s,t):=f(t)+f(s)-2\inf_{u\in [s,t]}f(u),\qquad 0\le s\le t\le\sigma_f.
  \end{align*}
  We define a real tree coded by $f$ by 
  \begin{align*}
    T^f:=[0,\sigma_f]/\sim,
  \end{align*}
  where $s\sim t$ if and only if $\bar{d}^f(s,t)=0$.

[Lemma 1 of arXiv:2604.05910, '\textbf{Well-posedness and Hurst parameter estimation for fluid equations driven by fracti'] \begin{itemize}
      \item Let $s>\frac{d}{2}$. Then $H^{s}(\T^d)$ is an algebra, meaning that if $f\in H^s(\T^d)$ and $g\in H^s(\T^d)$ the product $fg\in H^s(\T^d)$ and
\begin{equation*}
\Vert fg\Vert _{H^{s}}\lesssim \Vert f\Vert _{H^{s}}\Vert g\Vert _{H^{s}}.
\end{equation*}
\item Let $s,r,t>0$ such that $s+r>t+\frac{d}{2}$. If $f\in H^s(\T^d)$, $g\in H^r(\T^d)$, then $fg\in H^t(\T^d)$ and 
\begin{align}
    \| fg\|_{H^t} \lesssim \|f\|_{H^s} \|g\|_{H^r}.
\end{align}
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

