[Definition def: srbmgeneral of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Let $S$ be the convex polyhedron in (equation eq:def_polyhedron of the paper). Given a Borel probability measure $\nu$ on 
	$S$, an SRBM associated with the data $(S, \theta, \Gamma,R,\nu)$ is an $\{\mathcal{F}_t\}$-adapted, $d$-dimensional process $W$ defined on some filtered probability space $(\Omega, \mathcal{F}, \mathcal{F}_t, P)$ such that 
	\begin{enumerate}
		\item $W= X+RY$, $P$-a.s.,
		\item $P$-a.s., $W$ has continuous paths and $W(t) \in S$ for all $t \geq0,$
		\item under $P,$
		\begin{itemize}
			\item $X$ is a $d$-dimensional Brownian motion with drift vector $\theta,$ covariance matrix $\Gamma,$ and $X(0)$ has distribution $\nu,$
			\item $\{X(t)-X(0)-\theta t, \mathcal{F}_t, t\geq 0\}$ is a martingale,
		\end{itemize}
		\item $Y$ is an $\mathcal{F}_t$-adapted, $d$-dimensional process such that $P$-a.s., for $i=1,...,m,$
		\begin{itemize}
			\item $Y_i(0)=0,$
			\item $Y_i$ is continuous and non-decreasing,
			\item  $\int_0^{t} \mathbf{1}_{ F_i } (W(s)) dY_i(s)=Y_i(t)$ for all $t \ge 0$. 
		\end{itemize}
	\end{enumerate}

[Definition 4.5 of arXiv:2507.06186, '2507.06186'] For any $\ka,\eps,t>0$, we let $\mc K_{\ka,\eps}(t)$ denote the integral operator on $L^2(D)$ with kernel
\begin{align}

\mc K_{\ka,\eps}(t;x,y)=p_t(x-y)\mbf E_B\left[\mbf 1_{\{\tau_D(B^{x,y}_t)>t\}}\exp\left(-\ka\int_0^t\xi_\eps\big(B^{x,y}_t(r)\big)\d r\right)\right],\qquad x,y\in D,
\end{align}
where we assume that $B^{x,y}_t$ and $\xi_\eps$ are independent, and we use $\mbf E_B$ to
denote the (conditional) expectation with respect to the randomness in $B$ only.

[Prop 16 of arXiv:2608.26642, '2608.26642'] The process $(\varphi^\mu(X_t)\Gamma_t^\mu)_{t\ge 0}$ is a martingale. Moreover, we have
\begin{align}
   \lim_{q\to 0+}r_q(0)\P_x\Big[F_t\cdot \Gamma_{\bm{e}_q}^\mu\Big]=\P_x\Big[F_t\cdot \varphi^\mu(X_t)\Gamma_t^\mu\Big]
 \end{align}
 for any bounded $\F_t$-measurable functional $F_t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

