			\newuLmulevelset & \eqdef \{ (t,u,x^2,x^3) \in \R \times \R \times \T^2 \ | \ \newuL \upmu(t,u,x^2,x^3) = 0\} \cap \{ |u| \le \interestingu\},  \\
