[Corollary 53 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Put \(\theta:=1-H\).  Then
\begin{equation}
  z(u)=\EE_{Q^1}e^{-u^HV^1},

\end{equation}
and, on \((0,\infty)\),
\begin{equation}
  \pi_H(\mathrm du)=c_H^{\mathrm{mix}}z(u)u^{\theta-1}\,\mathrm du,
  \qquad
  (c_H^{\mathrm{mix}})^{-1}
  =\int_0^\infty z(u)u^{\theta-1}\,\mathrm du.

\end{equation}
Moreover, for every \(c>0\),
\begin{equation}
  \frac{\mathcal Z(ca)}{\mathcal Z(a)}
  \longrightarrow c^{-\theta}.

\end{equation}

