[Lemma 164 of arXiv:2601.16377, '2601.16377'] Consider a uniformly random tilings of $A\times B\times C$ hexagon with $D\times D$ hole (the bottom point of the hole is at fixed distance $\mathfrak{t}$ from the left side of the hexagon and at fixed distance $\mathfrak{h}$ from the bottom side).
 Using the notations \eqref{eq_N_hexagon_hole} and \eqref{eq_L_hexagon}, the $N$ horizontal lozenges on the vertical section at distance $\mathfrak{t}$ from the left border with coordinates $1\leq \ell_1<\ell_2<\dots<\ell_N\leq L$ have probability distribution
\begin{equation}

 \amsmathbb P_N(\ell_1,\ldots,\ell_N)=\frac{1}{\mathscr{Z}_N}\cdot \prod_{1 \leq i<j \leq N} (\ell_j-\ell_i)^2 \cdot \prod_{i=1}^N w(\ell_i),
\end{equation}
\begin{equation}

w(\ell)=
\left\{\begin{array}{lll}
  (\ell)_{C-\mathfrak{t}}\cdot(A+\mathfrak{t}+1-\ell)_{B-\mathfrak{t}}\cdot(\mathfrak{h}+1-\ell)_D^2&& \textnormal{if}\,\,0<\mathfrak{t}\leq \min(B,C),\\
  (\ell)_{C-\mathfrak{t}}\cdot(A+B+1-\ell)_{\mathfrak{t}-B}\cdot(\mathfrak{h}+1-\ell)_D^2 && \textnormal{if}\,\,B\leq \mathfrak{t}\leq C,\\
  (\ell)_{\mathfrak{t}-C}\cdot(A+C+1-\ell)_{B-\mathfrak{t}}\cdot(\mathfrak{h}+1-\ell)_D^2&& \textnormal{if}\,\,C\leq \mathfrak{t}\leq B,\\
  (\ell)_{\mathfrak{t}-C}\cdot(A+B+C+1-\mathfrak{t}-\ell)_{\mathfrak{t}-B}\cdot(\mathfrak{h}+1-\ell)_D^2 && \textnormal{if}\,\,\max(B,C)\leq \mathfrak{t}<B+C,
 \end{array}\right.
\end{equation}
where $(a)_n$ is the Pochhammer symbol and $\mathscr{Z}_N$ is a normalizing
constant.

[Definition def:Yn of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] The process $\mathcal Y_n$ is a subprocess of $\mathcal T_n$, and satisfies the following. 
\begin{itemize}
    \item The root of $\mathcal Y_n$ is $\varphi$, the root of $\mathcal T_n$. The set of children of $\varphi$ in $\mathcal Y_n$ is the set of all vertices in generation $l$, i.e., $Z_{l}$ of $\mathcal T_n$. Thus, letting $Z'_1$ denote the first generation of $\mathcal Y_n$, we have $Z'_1=Z_l$. 
    \item In general, inductively, for any $p$, the $p$-th generation $Z'_p$ of $\mathcal Y_n$ is the set $Z_{pl}$, with the parent in $\mathcal Y_n$ of each vertex $v \in Z'_p$, is the ancestor $u$ of $v$ in $Z_{(p-1)l}$ in $\mathcal T_n$. Note that $u \in Z'_{p-1}$.
\end{itemize}

