body:
[Definition 47 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $q \in (0,1)$, $c \in (1, q^{-1})$, and set
\begin{equation}
\begin{split}
&p_2 = \frac{q}{c-q}, \hspace{2mm} \sigmap = \sqrt{p_2(1+p_2)} = \frac{q^{1/2}c^{1/2}}{c-q}, \hspace{2mm} \bar{\kappa} = \frac{(c-q)^2}{(1-qc)^2} - 1 > 0.
\end{split}
\end{equation}
For $\kappa \in [0, \bar{\kappa})$ we also define
\begin{equation}
z_c(\kappa) = \frac{q + \sqrt{1+ \kappa}}{1 + q \sqrt{1+ \kappa}}, \hspace{2mm} h_1(\kappa) = \frac{2q\sqrt{1+\kappa}+ 2q^2 + q^2\kappa}{1-q^2} , \hspace{2mm} h_2(\kappa) = \kappa p_2 + \frac{q (c^2 - 2qc + 1)}{(c-q)(1-qc)}.
\end{equation}
Notice that by our parameter range, we have $q < 1 \leq z_c(\kappa) < c < q^{-1}$.

We also define for $z \in \mathbb{C} \setminus \{0, q , q^{-1}\}$ the functions
\begin{equation}
\begin{split}
& \SFb(z;\kappa) = (1+\kappa) \log(1 - q/z) - \log(1-qz) - h_1(\kappa)\log(z), \\ 
&\SFt(z;\kappa) = (1+\kappa)\log(1 - q/z) - \log(1-qz) - h_2(\kappa) \log(z),\\
&\bar{\SFb}(z;\kappa) = \SFb(z;\kappa) - \SFb(\zc(\kappa);\kappa), \hspace{2mm} \bar{\SFt}(z; \kappa) = \SFt(z;\kappa) - \SFt(c;\kappa), \\
&\GFt(z) = \log(1-q/z)- p_2 \log(z), \hspace{2mm} \bar{G}_2(z) = \GFt(z) - \GFt(c).
\end{split}
\end{equation}

[Lemma lem5-4 of arXiv:2606.28631, '\Large \bf On the maximal displacement of subcritical branching random walks with stretche'] Assume {\bf(H2)} and $b\in (0,1)$. 
	\begin{itemize}
		\item[(i)] For all $k\delta\geq K_0, I=[(k-1)\delta, k\delta)$ and $x>K_0$, 
		\begin{align}
			\frac{e^{\lambda x^b}}{\ell(x)x^a } T_{42} \lesssim_\beta  \frac{e^{\lambda (k\delta)^b}}{\ell(k\delta) (k\delta)^a}.
		\end{align}
		\item[(ii)] For each $I=[p,q)$, we have 
		\begin{align}
			\lim_{x\to+\infty}\frac{e^{\lambda x^b}}{\ell(x)x^a } T_{42}  =0. 
		\end{align}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor pers-det-trees of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ is a generalised preferential attachment tree, with deterministic values $(f(j))_{j \in \mathbb{N}_{0}}$. Then
\begin{enumerate}
\item If $\sum_{j=0}^{\infty} \frac{1}{f(j)^2} = \infty$, then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ almost surely does not have a persistent hub.
\item  If $\sum_{j=0}^{\infty} \frac{1}{f(j)^2} < \infty$ and for some $\lambda > 0$, 
\begin{equation} 
\sum_{i=0}^{\infty} \prod_{j=0}^{i}\frac{f(j)}{f(j) + \lambda} < \infty,
\end{equation} 
then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ has a unique persistent hub almost surely. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:second of arXiv:2604.23791, 'Finite-sample Borel--Cantelli inequalities under mixing conditions'] Under the hypotheses of Theorem~(thm:phi of the paper) with $L\ge2$,
\begin{equation}
  \mathbb{P}\Bigl(\,\bigcup_{k=1}^{N}A_{k}\,\Bigr)
  \;\ge\; 1-\exp\!\Bigl(-\tfrac12\bigl(S_{N}-T_{L-1}
  -\kappa_{N,L}\,\varphi(L+1)\bigr)_{+}\Bigr),
  \qquad \kappa_{N,L}:=\bigl\lceil\tfrac{N}{L}\bigr\rceil+1.
\end{equation}

[Prop eq of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an ergodic upper probability. Then the following two statements are equivalent:
	\begin{longlist}
		\item $\lim_{n\to\infty}\int\frac{1}{n}\sum_{i=0}^{n-1}1_B\cdot( 1_C\circ T^i)dV=V(B)V(C)$ for any $B,C\in\mathcal{F}$;
		\medskip
		\item $V$ is a probability.
	\end{longlist}

[Proposition prop:estimation ruin probability for the collective model of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume that $X(1)$ and $Y(1)$ have  finite first moments, and assume:
\begin{itemize}
    \item[{\rm (1)}] {the Cram\'er condition (equation cram of the paper) applies;} 
\item[{\rm (2)}] 
$\min(f_{\min}\mathbb{E}[X(1)]+(1-f_{\min})\mathbb{E}[Y(1)],f_{\max}\mathbb{E}[X(1)]+(1-f_{\max})\mathbb{E}[Y(1)])>0.$
\end{itemize}
Then, for any $u>0$, 
\begin{equation}
p(u)\leqslant {\mathrm e}^{-\alpha_0 u},
\end{equation}
where $\alpha_0=\min{{\left\{\widetilde\alpha,\overline\alpha\right\}}}$, with $\widetilde\alpha:=\sup\BRA{\alpha>0: C_\alpha(f_{\min})<0\text{ and }C_\alpha(f_{\max})<0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 4 of arXiv:2606.11774, 'Martingale Solutions to a Stochastic Keller-Segel System with nonlocal Source and Super-li'] (Local strong  solution and uniqueness) Fix a  probability space ${\mathfrak{A}}:= ({\Omega} ,{\mathcal{F}}$, $ \{{\mathcal{F}}_{t}\} _{t\ge 0},  {\mathbb{P}}  )$ with a complete, right-continuous filtration and let $W(t)$ be a $Q$-Wiener process on ${\mathfrak{A}}$.  Let $u_0\in L^2(\Omega,\mathcal{F}_0;L^2(\mathcal{O}))$ and $u_0\ge 0\,a.e.$ in $\mathcal O$. A local strong solution to (\ref{equ2}) is  $u_n^N(\cdot \wedge{\tau_n^N})$, where $\tau_n^N$ is a stopping time  and $u_n^N:\Omega\times[0,\infty)\to H_n$ is an  $H_n$-valued  $\{\mathcal{F}_t\}_{t\ge 0}$-predictable process satisfying 
	\[
	u_n^N(\cdot\wedge\tau_n^N)\in C([0,\infty);H_n)~\mathbb{P}\text{-a.s.},
	\]
	and for all $t\ge0$,
	\begin{align*}
		u_n^N(t\wedge\tau_n^N )=&u_n(0)+\int_0^{t\wedge\tau_n^N}\Pi_n\big[\Delta u_n^N-  \nabla  \cdot (u_n^N \nabla c_n^N) +(u_n^N)^\alpha(1-\int_\mathcal{O}(u_n^{N})^{\beta}dx)\big]~dt' \\&+\int_0^{t\wedge\tau_n^N}\Pi_n\sigma (u_n^N)~dW(t')\quad\mathbb{P}\text{-a.s.}
	\end{align*} 
	The local solution is pathwise unique, if any two local solution $u_n^{N_1}(\cdot \wedge{\tau_n^{N_1}})$ and $u_n^{N_2}(\cdot \wedge{\tau_n^{N_2}})$ satisfy that $u_n^{N_1}(0)=u_n^{N_2}(0)$~$\mathbb{P}$-a.s. can imply $u_n^{N_1}(t)=u_n^{N_2}(t)$~$\mathbb{P}$-a.s. on $t\in[0,\tau_n^{N_1}\wedge\tau_n^{N_2})$.

[Lemma 11 of arXiv:2608.23462, '2608.23462'] Let $\beta >0$ and $p \geq 2$. Suppose that Assumptions~\ref{assu:regularity} and~\ref{assu:epsilon} are satisfied and that the fast variable $(Y_t)_{t \ge 0}$ with initial condition $y \in \R^{d_2}$ is $p$-dissipative with constant $\beta$. Then, there exists $C_{\beta,p}^{(1)}, C_{\beta,p}^{(2)} > 0$ such that for all $t\geq 0$
    \begin{align*}
    \| Y_t\|_{L^p} \leq ( e^{-p(\beta  /2) \chi(t)}|y|^p + C_{\beta,p}^{(1)} )^{1/p} \leq e^{-(\beta  /2) \chi(t)}|y| + C_{\beta,p}^{(2)}.
    \end{align*}

