[Proposition propo-stab- of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] (Stability and uniqueness)
      Let $f_1$ and $f_2$ be two solutions to  (equation fom-limit-1 of the paper) with initial data $f_0^1\in H_0$ and $f_0^2\in H_0$ respectively. Then, we have
      \begin{align*}
          \Vert f_1(t)-f_2(t)\Vert_{H_0}^2+2\int_0^t\int_{\mathbb{T}^2}\int_D\bigl(\widetilde{\mathbf{M}}_0 (\dfrac{1}{\beta}+\dfrac{k_T}{2}\vert r\vert^2)\vert \nabla_r(\dfrac{f_1-f_2}{\widetilde{\mathbf{M}}_0})\vert^2 drdxds \leq   \Vert f_0^1-f_0^2\Vert_{H_0}^2.
      \end{align*}
      In particular, the solution to (equation fom-limit-1 of the paper) is unique. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] For any $B \in \widehat{\Bcal}(S)$ with $\pbb(\nu(B) = 0) < 1$, let $W_B$ and $W'_B$ be two local graphons for $\xi$ on $B$. Then there exist $\lambda\vert_{[0,1]}$-preserving transformations $T, T' : [0,1] \to [0,1]$ such that
    \begin{equation} 
        W_B \circ (T \otimes T) = W'_B \circ (T' \otimes T') \quad \lambda^{\otimes 2}\text{-a.e.\ }
    \end{equation}

[Proposition 59 of arXiv:2607.18104, '2607.18104'] Let $C>0$, $\theta \in \R$, $N\in \N$ and $\mathfrak{a}\in (0,1)$. Let $\rho \in [\mathfrak{a},1-\mathfrak{a}]$ and consider ASEPs $(\eta_t)_{t \geq 0}$ and $(\bar{\eta}^{\per}_t)_{t \geq 0}$ evolving according to the extended $(\rho,\theta,1,N)$-reference frame basic coupling. Consider (random) data $\eta^{N} \in \{0,1\}^{N}$ with 
\begin{equation}
 \textup{Ber}_{\rho+CN^{-1/2}}^{N} \succeq \P( \eta^{N} \in \, \cdot \, ) \succeq  \textup{Ber}_{\rho-CN^{-1/2}}^{N} ,  
\end{equation} where $\textup{Ber}_{\rho}^{N}$ denotes the Bernoulli-$\rho$-product measure on $\{0,1\}^{N}$. Define initial data $\eta_0\in \{0,1\}^{\mathbb{Z}}$
\begin{equation}
\eta_0(x):=\eta^N(x- \lfloor \theta N \rfloor )
\end{equation} for all $x \in \lbr \theta N+1, (1+\theta)N \rbr$. For all
$x \notin \lbr \theta N+1, (1+\theta)N\rbr$, let $\eta_0(x)$ be occupied independently with probability $\rho$. For initial data $\tilde{\eta}_0$, assume that \eqref{eq:AgreeLocally} holds, but extend the configuration outside of $\lbr \theta N+1, (1+\theta)N \rbr$ periodically. Then there exist some $\tilde{c},\tilde{C}>0$, depending only on $\mathfrak{a}$, $q$ and $C$, and not $\theta,N,\rho$, such that the extended colored ASEP  $(\xi_t)_{t \geq 0}$ from Definition~\ref{def:ExtendedCouplingASEP} and  
\begin{equation*}
    \mathcal{A}^{\theta}_{\delta,N} := \left\{ \xi_t(x) \in \{\zero,\one \}  \, \forall (x,t) \in \mathcal{I}^{\rho}_{\delta,N}\Big(\frac{1}{8}+\theta,\frac{7}{8}+\theta\Big)  \right\}
\end{equation*} satisfy for all $\delta>0$ 
\begin{equation}
\liminf_{N \rightarrow \infty}\Pex\big( \mathcal{A}^{\theta}_{\delta,N} \big)   \geq 1- \tilde{C} \exp(-\tilde{c} \delta^{-1} ) . 
\end{equation} 
Furthermore,  \eqref{eq:GoodControlASEP} continues to hold when $(\xi_t)_{t\geq 0}$ is defined the as a full-space extended colored ASEP with reference frame $\mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$ for two full-space ASEPs, i.e., we obtain $(\xi_t)_{t\geq 0}$ as in Definition~\ref{def:ExtendedCouplingASEP} with respect to two ASEPs on the integers, which evolve under the (extended) basic coupling along edges in $\mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:convergence of the roots of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume:
\begin{enumerate}
\item[{\em (1)}] {the Cram\'er condition (equation cram of the paper) applies};
\item[{\em (2)}] for $\alpha\geqslant 0$, the limit $\ell_\alpha := \lim_{t\to \infty} k_\alpha(t)/t$ exists almost surely;
\item[{\em (3)}] there is a unique $\alpha_*\in(0,\overline{\alpha})$ such that $\ell_{\alpha_*}=0$.
\end{enumerate}
Let $\alpha(t)=\sup{{\left\{\alpha\geqslant 0: k_\alpha(t)=0\right\}}}$ denote the largest root of $\alpha\mapsto k_\alpha(t)$. Then
\[
\lim_{t\to \infty} \alpha(t) = \alpha_* \quad \text{almost surely.}\]
In addition, we have $\alpha_0\leqslant \alpha_*$, where $\alpha_0$ is the rough decay rate introduced in Proposition~(prop:estimation ruin probability for the collective model of the paper).

[Lemma 2 (Schatten ideal, interpolation, and tensor regrouping) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Let $U,V,U',V'$ be Hilbert spaces.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
 \item If $T\in\cL(U,V)\cap\Sch_2(U,V)$ and $2\le r<\infty$, then
 \begin{equation}
  \norm{T}_{\Sch_r}
  \le \norm{T}_{\rm op}^{1-2/r}\norm{T}_{\Sch_2}^{2/r}.
 \end{equation}
 \item If $A\in\cL(V,V')$, $B\in\cL(U',U)$, and $T\in\Sch_r(U,V)$, then
 \begin{equation}
  \norm{ATB}_{\Sch_r(U',V')}
  \le \norm{A}_{\rm op}\norm{T}_{\Sch_r(U,V)}\norm{B}_{\rm op}.
 \end{equation}
 \item The canonical regroupings of Hilbert tensor products, for instance
 $((\cA\otimes_2\cB)\otimes_2\cC)\simeq\cA\otimes_2\cB\otimes_2\cC$, are unitary.  Consequently Hilbert--Schmidt norms are unchanged by a mere reorientation of tensor legs.  Multiplication by unimodular factors on any frequency leg is also unitary and hence preserves every Schatten norm.
\end{enumerate}

[Lemma lem:aftercancellation of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Define $\ell \coloneqq  \lceil |\alpha| / 2 \rceil$
    For every $\beta \subseteq \alpha$ and any $\mathbf{t}$, we have
    \begin{align*}
        \sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}  \hspace{.1cm}\varphi_{\beta}(\mathbf{t}) = e^{-\frac{\widehat{\sigma}^2}{2} \|\mathbf{t}\|^2 } \left( \widehat{\Lambda}_\alpha(  \mathbf{X}_{\text{R}} , \mathbf{t}) + \widehat{R}_\alpha( \mathbf{X}_{\text{R}} , \mathbf{t}) \right).
    \end{align*}
    with \begin{align*}
        \widehat{\Lambda}_\alpha(  \mathbf{X}_{\text{R}} , \mathbf{t})  \coloneqq  \frac{(-1)^\ell}{2^\ell \ell!}  \sum_{ \substack{ r_1, \ldots r_k \in \alpha \times \alpha \\ {\textsc{Supp}}(r_1, \ldots, r_k ) = \alpha }} \Phi_{\alpha}^{(r_1, \ldots, r_k)}(\mathbf{t}) \text{ and } \widehat{R}_\alpha( \mathbf{X}_{\text{R}} , \mathbf{t}) \coloneqq\sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}\sum_{k=\ell + 1}^\infty \frac{(-1)^k}{2^k k!} (\mathbf{t}^\top \! (\boldsymbol{\Sigma}_\beta - \widehat{\sigma}^2\mathbf{I}) \ \mathbf{t})^k
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

