                                                & \text{3-3;}                                                                                                 \\[1em]
      \frac{\beta ^{\frac{-4\gamma+\beta (d-3)+2}{4-2\beta}}}{\sqrt{2-\beta}} x^{\frac{d/2+1-(\beta+\gamma)}{2-\beta}}                                        \\
      \quad \times \exp\left( -(2-\beta) \beta^{\beta / (2-\beta)} x^{1/(2-\beta)} \right) \left(1+O\left(x^{-1/(2-\beta)}\right)\right),
                                                & \text{4;}                                                                                                   \\[1em]
      C_{5,1}\: x^{\frac{d/2+1-(\beta+\gamma)}{\alpha-\beta}} \cos\left(C_{5,2} - C_{5,3}\cos\left(\theta_{\alpha,\beta}\right)\: x^{1/(\alpha-\beta)}\right) \\
      \quad \times \exp\left(- C_{5,3}\sin\left(\theta_{\alpha,\beta}\right)\: x^{1/(\alpha-\beta)}\right) \left(1+O\left(x^{-1/(\alpha-\beta)}\right)\right),
                                                & \text{5;}                                                                                                   \\[1em]
    \end{dcases}
  \end{align*}
  where the constants are given below
  \begin{gather}
    h_{1,1} = \frac{\Gamma\left((d+\alpha)/2\right) \Gamma\left(1+\alpha/2\right)}{\pi\: \Gamma(2\beta+\gamma)} \sin\left(\pi\alpha /2\right), \\
    C_3     = (\alpha -2)\: 2^{(\alpha+2)/(\alpha-2)} \alpha^{-\alpha/(\alpha -2)}, \nonumber
