[Lemma 9 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] There exist absolute constants $\delta_0,c>0$ such that the following holds for every $\delta \leq \delta_0$.
	Consider $x_0,y \in \cD(\delta)$ with $\Vert x-y \Vert \leq (4/5) r_\delta$ such that $x_0$ and $y$ lie on different sides of some barrier $B_i$ with $i\in\{1,\ldots,k \}$.
	Then,
	\begin{align}
		\bbP(X_{ r_\delta^2} \in \cZ(\delta,y) \mid X_0 = x_0) \geq c  r_\delta \lambda_{\min}.
	\end{align}

[Lemma \cite{BravDaiMiya2023} Lemma 2.6 of arXiv:2411.00930, '\bf \Large Asymptotic Product-form Steady-state for Multiclass Queueing Networks: A Reentr'] \begin{equation*}
        \lim_{r\to0}\phi^{(r)}(\theta)-\phi_k^{(r)}(\theta)=0,\quad k\in\{2,3,5\}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2608.26490, 'Bayesian methods and Markov chain Monte Carlo algorithms for curve reconstruction and poin'] At the limit $K\to\infty$, the variates generated according to \cref{eq:B_B} converge in distribution to the variates generated according to \cref{eq:poiss}. 
\begin{proof}
According to the binomial statistics of \cref{eq:B_B}, the probability mass function of $B$ is
\begin{align*}
p\left(B\right)
&= \frac{\gamma^B}{B!}\frac{K(K-1)\cdots (K-B+1)}{K^B}
\left(1-\frac{\gamma}{K}\right)^K
\left(1-\frac{\gamma}{K} \right)^{-B}.
\end{align*}
Due to the limits
\begin{align*}
\lim_{K\to\infty}\frac{K(K-1)\cdots(K-B+1)}{K^B} &=1, 
&
\lim_{K\to\infty}\left(1-\frac{\gamma}{K} \right)^K&=e^{-\gamma}, 
&
\lim_{K\to\infty}\left(1-\frac{\gamma}{K}\right)^{-B}&=1,
\end{align*}
we readily obtain the limiting probability mass
\begin{align*}
\lim_{K\to \infty} p(B)
= \frac{\gamma^B}{B!} e^{-\gamma},
\end{align*}
which is in agreement with the Poisson statistics of \cref{eq:poiss}. 
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition sobo_def of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Suppose $M$ is a Cartan-Hadamard manifold satisfying $\sec_M\leq-K_1<0$. For $\alpha>0$, we define the Sobolev space $\mathcal{W}^{-\alpha}(M)$ as the completion of $ C_c^\infty(M)$ with respect to the inner product
\begin{align}
\left\langle  f ,g \right\rangle_{\mathcal{W}^{-\alpha}(M)}=\int_M \int_M f(x) g(y) G_{2\alpha}(x,y) dx dy= \int_{M} \left[(-\Delta)^{-\alpha} f\right](x)\left[ (-\Delta)^{-\alpha} g\right](x) dx,
\end{align}
where the kernel $G_{2\alpha}$ is the family in Definition (kernel for frac Laplacian of the paper).

[Lemma trunc of arXiv:2603.26307, '\LARGE The incompressible Navier--Stokes--Fourier system with thermal noise'] Consider a normed vector space $\mathscr{X}$ and let $R>0$. Then the mapping 
	\begin{equation}
		\Xi^R_\mathscr{X}\colon \mathscr{X}\to \mathscr{X},
		x \,\mapsto \, \frac{Rx}{\max\{R, \|x\|_\mathscr{X}\}}
	\end{equation}
	satisfies 
	\begin{align}&

		\|
		\Xi^R_\mathscr{X}(x)\|_{\mathscr{X}} \,\le\, R,\\&
		\| \Xi^R_\mathscr{X}(x)- \Xi^R_\mathscr{X}(y)\|_\mathscr{X}\,\le\, 2 \|x-y\|_{\mathscr{X}},
	\end{align}
	for all $x,y\in\mathscr{X}$.

