    \begin{align*}
        \|\pi_\infty^- (\sigma(V) \in \cdot) - \pi_\infty^-(\sigma(V) \in \cdot \mid \sigma(U)\equiv -1)\|_{{\textsc{tv}}}\le |U| e^{ - \beta d(U,V)}\,.
    \end{align*}

[Lemma 8 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let $f,g \in L^2([0,T];H^1(\T^d)^d)$ with $f$ that is divergence-free. Let $p>d$ and $\gamma\in (\frac{d}{p},1)$. Then there exists $C>0$ such that for any $t\in [0,T]$,
\begin{equation*}
\int_{0}^{t} \Big\Vert e^{\left(  t-s\right) \Delta} P \big[ (f_{s} \cdot \nabla)g_s\big] \Big\Vert _{\gamma,p} \dd s \leq C \int_{0}^{t}  \frac{1}{(t-s)^{\frac{1+\gamma}{2}}} \left\Vert f_{s} \otimes g_{s} \right\Vert _{L^p_{x}}  \dd s .
\end{equation*}

