[Theorem multivariate case of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $L\ge 1,n\ge 1$ and $g_n=([n]\times [L],E(g_n))$ be a grid graph. Assume that $w_{G_{g_n}}\to w$, where $w$ is an $\mathcal{M}_L$-decorated graphon. Let $a\in \mathcal{A}$ be a normalized random variable and let $(a_k^{(r)})_{k\in [n],r\in [L]}$ be $g_n$-independent and identically distributed random variable with common law $a$. Let
    \begin{align*}
        S_n^{(r)}=\frac{1}{\sqrt{n}}\sum_{k\in [n]}a_k^{(r)}.
    \end{align*}
    Then, $(S_n^{(r)})_{r\in [L]}$ converges in distribution to a family $(s_r)_{r\in [L]}$ whose joint distribution $\nu_{w}$ depends only on $w$. Moreover, for any $p\ge 1$ and $l\in [L]^p$, we have
    \begin{align*}
        \tau(s_{l_1}\cdots s_{l_p})=\sum_{\substack{\pi \in P_2(p)\\\pi\le \ker (l)}}\rho(F_{f_\pi}^l,w)=:\nu_w(l).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2607.11608, '2607.11608'] Let $1 \le p\le \infty$ and $s\in \R$, we define the harmonic Sobolev space $\mathcal{W}^{s,p}(\R)$ (respectively $\mathcal{W}_{\text{rad}}^{s,p}(\R^d)$ if $d\ge 2$) the space of functions (respectively radial functions) induced by the 
 norm
\begin{align*}
\|u\|_{\mathcal{W}^{s,p}(\R^d)}:=\|\mathcal{L}^{\frac{s}{2}}u\|_{L^{p}(\R^d)}.
\end{align*}
If $p=2$ we set $\mathcal{H}^s:=\mathcal{W}^{s,2}$, and for  $u$ of the form $u=\sum_{n\ge 0} c_n h_n$ we have 
\begin{align}
\|u\|^2_{\mathcal{H}^s(\R^d)}:=\|\mathcal{L}^{\frac{s}{2}}u\|^2_{L^{2}(\R^d)}=\sum_{n\ge 0} \nu^{2s}_n |c_n|^{2}. 
\end{align}

[Lem 16 of arXiv:2609.03777, '2609.03777'] Let $\mu_1,\mu_2$ be lattice points that satisfy $\mu_1\ordN\mu_2$ and $\mu_1\succ\mu_2$. For $N,j\in\ZZ_{>0}$, we have
\begin{align}
G^{(N;\mu_1,\mu_2)}_{2j}(\tau)-G^{(\infty;\mu_1,\mu_2)}_{2j}(\tau)=\summ{\lambda\in\latzero}\chi_N(\lambda)(f_j(\mu_1,\lambda)-f_j(\mu_2,\lambda))\,,
\end{align}
and the series in the right-hand side absolutely converges for any $j\geq1$.

