[Corollary BEln-cor-3 of arXiv:2411.13788, '\bf Gradient bounds and Liouville property for a class of hypoelliptic diffusion via coupl'] Let $f\in C^2\left(\mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}\right)$ be a  positive, globally Lipschitz  and bounded function.  Then for any fixed $t\ge0$, $x=(x^{(1)},\cdots,x^{(r+1)})\in \mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}$,  we have
\begin{equation}
2P_tf(x)\Gamma(\ln P_tf)(x)\le P_t\left(f\left\langle E(-t)AE^*(-t)\nabla \ln f,\nabla \ln f\right\rangle\right)(x).
\end{equation}
and
\begin{equation}
P_tf(x)\left\langle E(t)AE^*(t)\nabla P_tf(x),\nabla P_tf(x)\right\rangle\le 2P_t\left(f\Gamma(\ln f)\right)(x).
\end{equation}

