[Lemma lem:centear of arXiv:2606.02472, 'Correlated uniform attachment trees'] If $T$ is a $(K,\delta,c_1)$-good tree on $\{0,\ldots, n\}$ with centrality sets denoted by $A_r$, $r=1,\ldots, n$, then
\be{
\babs{ A_{\ceil{(c_1+\delta) K}} \cap \bclc{0,\ldots, K-1 }
}\geq \bclr{c_1 (1-e^{-1/c_1})-\delta}K.
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:dense_discrete_measures of arXiv:2411.07113, '\begin{LARGE}On differentiability and mass distributions of topologically typical multivar'] The following assertions hold:
\begin{itemize}
\item[(i)] The family of discrete $d$-Williamson measures with full support is dense in $(\mathcal{P}_{\mathcal{W}_d},\tau_w)$.
\item[(ii)] The family of singular $d$-Williamson measures with full support is dense in $(\mathcal{P}_{\mathcal{W}_d},\tau_w)$.
\item[(iii)] The family of absolutely continuous $d$-Williamson measures with full support is dense in $(\mathcal{P}_{\mathcal{W}_d},\tau_w)$.
\end{itemize}

[Lem 7 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] The operator $L_0\equiv L_{0,\ell}$ is given by
\begin{align*}
L_{0,\ell} = \frac12 \sum_{x=-\ell+1}^{\ell-1}
\Big( \big( \partial_{\eta(x)} - \partial_{\eta(x-1)} \big)^2
- \big( V'(\eta(x)) - V'(\eta(x-1)) \big)\big( \partial_{\eta(x)} - \partial_{\eta(x-1)} \big)  \Big).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2608.24731, 'Optimal Alternating Regret for Online Learning and Games\thanks{Authors are alphabetically'] \label[lemma]{lem:one-step}
Assume $\eta \le \frac{1}{8}$ and $\beta = \eta/4$. Then for any $t \ge 1$, we have
\begin{equation*}
\log \left( \sum_{i=1}^d p_{t,i}
\exp\!\left(
\eta\bigl((\boldsymbol{\xi}_t+\boldsymbol{\xi}_{t+1})^\top \boldsymbol{x}_t
-\xi_{t,i}-\xi_{t+1,i}\bigr)
+\beta(\xi_{t,i}^2-\xi_{t+1,i}^2)
\right)  \right) 
\leq 0.
\end{equation*}

[Ppn 188 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] The following estimates hold for $N$ large enough. We have
	\beq
	\E Q^{\RomI}(1) \le L^{O(1)} \delta\,.
	\eeq
In the Ising case, we also have
	\beq
	\sum_{\sigma\in\{\RomII,\RomIII\}}
	\E \sup\bigg\{ |\tilde{Q}^{\sigma,\Ising}(t)|
	: 0\le t\le 1\bigg\}
	\le
	\frac{L^{O(1)} \BUCKETS}{N}\,,
	\eeq
where we recall $\BUCKETS$ from \eqref{e:buckets.scB}. The errors $E^{\sigma,\tau}$ satisfy 
	\beq
	\sum_{\sigma,\tau\in\{\RomII,\RomIII,\Ising\}}
	\E \bigg[ \sup\bigg\{ |E^{\sigma,\tau}(t)|
	: 0\le t\le 1\bigg\}\bigg]
	\le
	L^{O(1)} 
		\bigg\{\frac{\eta}{\delta^{1/2}} 
		+ \frac{\BUCKETS}{N}
	\bigg\}
	\,.
	\eeq
Finally, the error $\tilde{E}^{\RomIII}$ satisfies
	\beq
	\E
	\sup\bigg\{
	|\tilde{E}^{\RomIII}(t)| : 0\le t\le 1\bigg\}
	\le
	L^{O(1)} 
	\bigg\{
	\frac{1}{N\delta}
	+ \frac{\BUCKETS}{N}
	\bigg\}^{1/2}
	\eeq
The ``$\frozen$'' variant of this proposition also holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:second_moment_Uk of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] For any $\hat{\beta} \in [0,z_a)$, there exists $C_{\hat \beta}>0$ such that
    \begin{equation}
    \limsup_{N\to\infty} \sup_{1 \le k\leq M}{\mathbb E}\left[ U_{k,M,N}^2\right] \leq  \frac{C_{\hat \beta}}{M}\,,
\end{equation}
and
\begin{equation}

    \lim_{M \to \infty} \, \lim_{N \to \infty} \sum_{k=1}^M \mathbb{E} \big[ U_{k,M,N}^2\big] = \lambda^2 \coloneqq \log \tilde J_\alpha (\hat \beta )^{-1}\,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma GLTNNRS-A of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Let ${\mathbb{B}_{\frac{1}{2}}}\left( {\mathrm{Id}} \right)$ be the metric ball consisting of symmetric $2 \times 2$ matrices, where $\mathrm{Id}$ is the identity matrix. Then, there exist finite set $\Lambda  \subset {\mathbb{Z}^2}$ and smooth function ${\gamma _\xi }:\ {\mathbb{B}_{\frac{1}{2}}}\left( {\mathrm{Id}} \right) \longrightarrow \mathbb{R}$ for each $\xi \in \Lambda$ such that
\begin{equation*}
R = \sum\limits_{\xi  \in \Lambda } {\gamma _\xi ^2\left( R \right)\xi  \otimes \xi },\ \ \forall \, R \in {\mathbb{B}_{\frac{1}{2}}}\left( {\mathrm{Id}} \right) .
\end{equation*}
Furthermore, there exist smooth $1$-periodic functions ${g_{\xi ,e,n}} {\left( t \right)}:\ \mathbb{R} \longrightarrow \mathbb{R}$ such that
\begin{equation*}
\int_0^1 {g_{\xi ,\iota ,n}^2\left( t \right)} \ \mathrm{d}t = 1,\ \ \forall \,  \left( {\xi ,\iota,n} \right) \in \Lambda  \times \left\{ {e,o} \right\} \times \left\{ {1,2, \cdots ,\Gamma } \right\},
\end{equation*}
and
\begin{equation*}
\mathrm{supp}_t \ {g_{{\xi _1},{\iota_1},{n_1}}} \cap \mathrm{supp}_t \ {g_{{\xi _2},{\iota_2},{n_2}}} = \emptyset , \ \ \mbox{as}\ \left( {{\xi _1},{\iota_1},{n_1}} \right) \ne \left( {{\xi _2},{\iota_2},{n_2}} \right) \in \Lambda  \times \left\{ {e,o} \right\} \times \left\{ {1,2, \cdots ,\Gamma } \right\} ,
\end{equation*}
where the step size $\Gamma$ is specified in Appendix C. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 232 (The main estimates for difficult top-order spacetime error integrals requiring integration by parts in $\newL$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $N = \Ntop$, 
and let $\tanderY^N \in \mathfrak{Y}^{(N)}$ be of the form $\tanderY^N = \Yvf{A} \tanderY^{N-1}$ for some $A = 2,3$, where $\tanderY^{N-1} \in \mathfrak{Y}^{(N-1)}$. 
Then the following estimate holds for 
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$:
	\begin{align}
		\begin{split} 
			& \left| \sum_{i=1}^3 \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} 
			 (\Lunit \tanderY^N v^i)
			(\muX v^i) \tanderY^N \mytr_{\gtorus}\upchi
			\weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction
			\, \voldiamond\right| \\
			&  \le  \boxed{\frac{2}{3}} \totalfluxcontrolvelocity_N(\ubar,u) + \boxed{\frac{3}{4}(1.01)}\totalfluxcontrolpartialmodifiedchi(\ubar,u)  +  \boxed{2.07} \weakspacetimeangularvelocitycontrol_N(\ubar,u) \\
			& \ \ + \Errortoparg{N}(\ubar,u).
		\end{split}
	\end{align}
where $\Errortoparg{N}(\timefunction,u)$ satisfies \eqref{E:ERRORTOPORDERWAVEESTIMATES}.

