body:
[Defn Double divisor of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Suppose $\Omega$ is a simply connected domain $(\Omega \subsetneq \mathbb{C})$.

A double divisor $\left(\boldsymbol{\sigma^{+}}, \boldsymbol{\sigma^{-}}\right)$ is a pair of divisor in  $\overline{\Omega}$

 \begin{equation}
  \boldsymbol{\sigma}^{+}=\sum \sigma_j^{+} \cdot z_j, \boldsymbol{\sigma}^{-}=\sum \sigma_j^{-} \cdot z_j.
 \end{equation}

We introduce an equivalence relation for double divisors:

\begin{equation}
    \left(\boldsymbol{\sigma_{1}^{+}}, \boldsymbol{\sigma_{1}^{-}}\right) \sim \left(\boldsymbol{\sigma_{2}^{+}}, \boldsymbol{\sigma_{2}^{-}}\right)
\end{equation}
 if and only if
 \begin{equation}
    \boldsymbol{\sigma_{1}^{+}}+ \boldsymbol{\sigma_{1}^{-}} = \boldsymbol{\sigma_{2}^{+}}+ \boldsymbol{\sigma_{2}^{-}} \quad on \ \partial \Omega.
\end{equation}
Thus, we may choose a representative $\boldsymbol{\sigma}^{-}$ from each equivalence class  that is supported in $\Omega$, i.e., $\sigma_j^{-}=0$ if $z_j \in \partial \Omega$ .

[Conj 4 of arXiv:2506.15159, 'Conditional central limit theorems for exponential random graphs'] Let $H$ be a fixed 
 graph containing $t$ triangles and $s$ two stars. Under the same conditions as in \cref{thm:twostar}, with $F_n$ denoting the number of copies of $H$ in $G_n$, we have
\be{
\frac{F_n- \mu_F}{\sigma_F}\to N(0,1)\quad \text{in distribution},
}
where 
\begin{align}
    \mu_F&=\frac{(n)_{(v(H))} }{\operatorname{Aut}(H)}\t p^{e(H)}+ \left(\frac{(n-3)_{(v(H)-3)}}{\operatorname{Aut}(H)}\right)\big(2s\t p^{e(H)-2}\mu_{\t V}+6t\t p^{e(H)-3}\mu_{\t \triangle}\big),\\
\sigma_F^2&=\left(\frac{(n-3)_{(v(H)-3)}}{\operatorname{Aut}(H)}\right)^2\left(4s^2\t p^{2e(H)-4}\sigma^{2}_{V} +36t^2\t p^{2e(H)-6}\sigma^{2}_{\t \triangle }\right),
\end{align}
 $(n)_{(k)}=n(n-1)\cdots (n-k+1),$ $\operatorname{Aut}(K)$ denotes the number of automorphisms of $K$
to itself and and $\t \triangle :=\sum_{i<j<k}\t Y_{ik}\t Y_{jk}\t Y_{ij}$. The values of $\mu_{\t V}, \sigma_{V}, \mu_{\t\triangle}, \sigma_{\t \triangle}$ are in \cref{muv,sigmav,IET',sigmat}, respectively. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem thm:rate of arXiv:2509.03048, 'Elephant random walks on infinite Cayley trees'] Let $p \in [0, 1)$. Then for any $m \in [1, 2]$,
    \begin{equation}
        \mathbb{E} \bigg|\frac{\Delta_n}{n} - \frac{d - 2}{d}\bigg|^m \lesssim r_n^{-m}.
    \end{equation}
    In the supercritical regime, (equation eq:upper-bd of the paper) holds for a larger range of $m$, namely, for all $m \in [1, \frac{d - 1}{d(1 - p)}]$.

    In fact, in the subcritical regime $p < p_d$, in a neighbourhood of $1/d$, we can show a matching lower bound: For any $m \in [1, 2)$, there is $\epsilon > 0$ such that for all $p \in (1/d - \epsilon, 1/d + \epsilon)$, one has
    \begin{equation}
        \mathbb{E} \bigg|\frac{\Delta_n}{n} - \frac{d - 2}{d}\bigg|^m \gtrsim n^{-m/2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemme 56 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $\mu \in \mathcal{M}_1(\mathbb{R})$ and $\rho > 1$. Then $\op{s}_{\rho \#} \mu \to \mu$ as $\rho \searrow 1$ in the weak topology. Moreover,
\begin{align*}
   &\text{if } \int x \,  \mathrm{d} \op{s}_{\rho \#} \mu(x) =0   & &\text{ then } & & \int x \,  \mathrm{d} \mu(x) =0  \, , \\
   &\text{and if} \int |x|^\theta \,  \mathrm{d}\mu(x) < +\infty  & & \text{ then } & &  \int |x|^\theta \, \mathrm{d} \op{s}_{\rho \#} \mu(x) < +\infty \, .
\end{align*}
Furthermore,
if $\mu$ satisfies \eqref{cond1} then
\begin{align}

    1+\frac{2}{\ell} \Int{\mathbb{R}}{} \ln|x-y| \, \mathrm{d}(\op{s}_{\rho \#} \mu) (y) \, \geq \, 2\kappa := \frac{2}{\ell} \ln \rho > 0,\quad \op{s}_{\rho \#} \mu \quad a.s.

\end{align}

[Definition 33 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Consider a family of functions $(R_s)_{s\geq 0}$, where each $R_s:[0,1]\to[0,1]$ is a function that satisfies
\begin{equation}
R_0(v)=v, \   R_s(v)\ge v,
\end{equation}
and the family has the property that $s\mapsto R_s(v)$ is non-decreasing and continuous for every $v \in [0,1]$. 

We say the family $(R_s)_{s\geq 0}$ satisfies an enlargement inequality for $(X,d,\mu)$ if
\begin{equation}

\mu(A_s)\ge R_s(\mu(A)).
\end{equation}
We call each $R_s$ an enlargement function. Moreover, we associate with $(R_s)_{s\geq 0}$ the function $\Theta: \R_+ \to [0,1/2]$ given by
\begin{equation}

\Theta(s):=\sup_{0\le v\le1}\sqrt{v\bigl(1-R_s(v)\bigr)}.
\end{equation}
Finally, the function $\Theta$ is non-increasing in $s$.

[Theorem 27 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Assume that there exist constants $L > 0$ and $C_{LG} > 0$ such that the following conditions hold:
    \begin{enumerate}
        \item[(i)] (uniform Lipschitz condition) For all $(t,x) \in \ccC_T^d$ and $(t,y) \in\ccC_T^d$, we have
              \begin{equation}
                  \|b(t,x) - b(t,y)\|^2 + \|\sigma(t,x) - \sigma(t,y)\|^2 \leq L \sup_{0 \leq s \leq t}\|x(s)-y(s)\|^2.
              \end{equation}
        \item[(ii)] (linear growth condition) For all $(t,x) \in\ccC_T^d$, it holds that
              \begin{equation}
                  \|b(t,x)\|^2 + \|\sigma(t,x)\|^2 \leq C_{LG}\left(1 + \sup_{s \in [0,t]}\|x(s)\|^2 \right).
              \end{equation}
    \end{enumerate}
    Then the path-dependent SDE \eqref{path_dependent_sde_existence} admits a unique strong solution $X = (X(t))_{t \in [0,T]}$.
    Moreover, this solution satisfies the integrability condition $E\left[ \int_0^T \|X(t)\|^2 dt \right] < \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Local second-order estimate) of arXiv:2608.29736, '2608.29736'] For every compact subset \(K\Subset M\setminus Z\), there exists a
constant \(C_K>0\), independent of \(t\), such that
\begin{equation}
\omega<\eta_t\leq C_K\omega
\qquad\text{on }K.
\end{equation}

[Lemma lem:GRR of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let $\gamma < \frac{1}{2}$, $p > 2$, and let $\xi \colon [-r,0] \rightarrow \mathbb{R}^n$ be an $\gamma$-H\"older path. Then, there exists a constant $A_p$ such that
				\begin{align}
					\| \xi \|_{\gamma} = \sup_{-1 \leq s < t \leq 0}\frac{\|\xi_{s,t}\|}{(t-s)^{\gamma}} \leq A_p \left( \iint_{[-r,0]^2} \frac{\|\xi_u - \xi_v\|^p}{|u-v|^{p\gamma + 2}} \, du \, dv \right)^{\frac{1}{p}}.
				\end{align}
				If $X$ is $\gamma$-H\"older and $(\xi, \xi') \in \mathscr{D}_{X}^{\gamma}([-r,0])$, then
				\begin{align}
					\sup_{-r \leq s < t \leq 0}\frac{\|\xi^{\#}_{s,t}\|}{(t-s)^{2\gamma}} \leq A_p \left[ \left( \iint_{-r \leq u < v \leq 0} \frac{\|\xi^{\#}_{u,v}\|^p}{|u-v|^{2\gamma p + 2}} \, du \, dv \right)^{\frac{1}{p}} + \|\xi'\|_{\gamma} \|X\|_{\gamma} \right].
				\end{align}

[Lemma explexpr of arXiv:2411.06827, 'The Exponential Lie Series and a Chen--Strichartz Formula for L{\'e}vy Processes'] For $m\geq 1$, we have the explicit expression 
\begin{align*}
	(\overline i^{(m)})^0 & =\, 
	\sum_{n=1}^m\sum_{j_1+\cdots + j_n=m}
	\frac{(-1)^{n-1}}{n}\overline i^{(j_1)}\cdots \overline i^{(j_n)}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Let $\alpha>-1/2$. Assume that $\me[\eta]=0$ and $\sigma^2=\me[\eta^2]\in(0,\infty)$. Then
\begin{equation}
C\Big(\Big(\Big(\frac{2^{2\alpha}}{\sigma^2 \Gamma(1+2\alpha)}\frac{s^{1+2\alpha}}{\log\log1/s}\Big)^{1/2}\sum_{k\geq 2} \frac{(\log k)^\alpha \eta_k}{k^{1/2+s}}: s\in(0, \eee^{-1})\Big)\Big)=[-1,1] \quad\text{\rm a.s.},
\end{equation}
where $\Gamma$ is the Euler gamma function.
In particular,
\begin{equation}
\limsup_{s\to 0+}\Big(\frac{s^{1+2\alpha}}{\log\log 1/s}\Big)^{1/2}\sum_{k\geq 2} \frac{(\log k)^\alpha \eta_k}{k^{1/2+s}}=\frac{(\Gamma(1+2\alpha))^{1/2}}{2^\alpha}\sigma
\quad\text{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] If Assumption \ref{asmp:baseline} and $T\leq \infty$ hold, then $V_T$ is upper semicontinuous, $\mathcal{C}_T$ is open, and $\mathcal{D}_T$ is closed. Furthermore, the stopping time
\begin{equation}
    \tau^*_T(t,x):=\inf\{0\le s<T-t:(t+s,X_s^x)\in\mathcal{D}_T\}\wedge(T-t)
\end{equation}
is the smallest optimal stopping time for $T<\infty$.

