[Lemma timeregularity-es of arXiv:2603.26307, '\LARGE The incompressible Navier--Stokes--Fourier system with thermal noise'] Let 
			$(u_{\epsilon} ,\psi_{\epsilon},q_\epsilon)$ be the weak martingale solutions to  (equation ep_approx of the paper)--(equation eqn354865865 of the paper) with initial data $(u_0,\psi_0)$ constructed in Proposition (prp-existence-ep of the paper). Then, for every $\alpha \in (0,1/2)$ and $l > 5/2$, there exists a constant \[C = C(\alpha,l, u_0,\psi_0, F_1,F_2, G_1,G_2,T) <\infty, \] such that
		\begin{align}
			\mathbb{E}\|u_{\epsilon}\|_{C^{\alpha}([0,T];H^{-l}(\mathbb{T}^3;\mathbb{R}^3))}+\mathbb{E}\|\psi_{\epsilon}\|_{W^{\alpha,2}([0,T];H^{-l}(\mathbb{T}^3))} \leq C,
		\end{align}
			for all $\epsilon\in (0,1)$.

[Theorem thm occu mdp of arXiv:2604.10509, 'Nonequilibrium fluctuations and moderate deviations for the occupation time of the SSEP wi'] As $n \rightarrow \infty$, the sequence  $\{ \Gamma^n (t)/a_n, 0 \leq t \leq T\}$ satisfies the moderate deviation principles with decay rate $a_n^2$ and with rate function ${\mathcal I}_T$ in the space $C([0,T], \mathbb R)$. Precisely speaking,
	for any closed set $C$ and any open set $O$ in $C ([0,T], \mathbb R)$,
	\begin{align*}
		\limsup_{n \rightarrow \infty} \frac{1}{a_n^2} \log \mathbb P^n_{\rho_*} \Big( \{  \Gamma^n (t)/a_n , 0 \leq t \leq T\} \in C\Big) \leq - \inf_{\gamma \in C} \mathcal{I}_T (\gamma),\\
		\liminf_{n \rightarrow \infty} \frac{1}{a_n^2} \log \mathbb P^n_{\rho_*} \Big( \{ \Gamma^n (t)/a_n, 0 \leq t \leq T\} \in O\Big) \geq - \inf_{\gamma \in O} \mathcal{I}_T (\gamma).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj desirables of arXiv:2601.20502, 'Optimal matching under size priority'] Under the setting and notation of Theorem~(maintheorem2 of the paper), let us write $\mathcal{M}_{\max}(G_n)$ the set of maximum size matchings in $G_n$, then:
        \begin{equation}
            \begin{aligned}
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall M \in \mathcal{M}_{\max}(G_n), e \in M}\right] = \mathbb{P}_{((i,Z),(i',Z'))\sim \zeta'\otimes\zeta'}\left( i+i'<k \right), \\
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall M \in \mathcal{M}_{\max}(G_n), e \notin M}\right] = \mathbb{P}_{((i,Z),(i',Z'))\sim \zeta'\otimes\zeta'}\left( i+i'>k \right).
            \end{aligned}
        \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Definition def:class_B of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] We say that $\bm{p} \in \mathcal{B} \subset T(\mathbb{C}^2)$ if there exist three complex numbers
    $$
    \alpha, \beta \in \{z \in \mathbb{C}\colon \, \mathfrak{Re}(z) > 0\} \cup \{ 0\}, \quad \gamma \in \mathbb{C},
    $$
    two natural numbers $m, n \in \mathbb{N}^*$, and three coefficients $\bm{q}, \bm{r}, \bm s \in T(\mathbb{C}^2)$ satisfying
    \begin{align}
        \deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm{q}) < 2n,  \quad \deg_{{\color{NavyBlue}{\mathbf{0}}}}(\bm{q}) = 0, \quad \deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm{r}) < 2m, \quad \deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm s) < 2m \land 2n,
    \end{align}
    such that 
    \begin{equation}
        \bm{p} = -\alpha({\color{NavyBlue}{\mathbf{1}}}^{\otimes 2n} + \bm{q}) - \beta({\color{NavyBlue}{\mathbf{1}}}^{\otimes 2m} + \bm{r}){\color{NavyBlue}{\mathbf{0}}} + \alpha\beta\bm s + \gamma {\color{NavyBlue}{\mathbf{\varnothing}}}.
    \end{equation}
    {The time degrees $\deg_{{\color{NavyBlue}{\mathbf{0}}}}(\bm r)$ and $\deg_{{\color{NavyBlue}{\mathbf{0}}}}(\bm s)$ are only required to be finite.}

