[Definition ass:ft of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] There exist constants $ \alpha \in (0, 2]$, $c_0 > 0$, $\varepsilon > 0$, and $0 < \rho < 1$ such that the following assumptions are satisfied:
\begin{enumerate}
  \item (normalization) $f$ is a probabiltiy density
  \begin{equation}
    f(x)\ge 0, \quad \int_{\mathbb R^d} f(u)\,du \;=\; 1;
  \end{equation}
  \item (small-frequency control) for all $|\xi|\le \varepsilon$,
  \begin{equation}
    |\widehat f(\xi)| \;\le\; \exp\!\bigl(-c_0 |\xi|^\alpha \bigr);
  \end{equation}
  \item (high-frequency contraction) for all $|\xi| > \varepsilon$,
  \begin{equation}
    |\widehat f(\xi)| \;\le\; \rho < 1;
  \end{equation}
  \item (regularity/decay) $f$ is a continuous function and for some   constants $T, K > d$ and $C_T, C_{K} > 1$,   
  \begin{equation}
      f(x)\le \frac{C_T}{(1+|x|)^{T}},
    \qquad |\widehat f(\xi)| \;\le\; \frac{C_K}{(1+|\xi|)^{K}} 
      \qquad  x,\xi \in \mathbb R^d.
  \end{equation}
\end{enumerate}

[Lemma 18 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $\f\in\M_\infty$, $m\in\N$, $u\in2^m$ and $n,k\in\N_0$ be arbitrary. Let us further denote
\begin{equation*}
M\coloneqq\bs{v\in2^{l}\cap u\appinf;l\geq m,\forall j\in[m:l]:f_j(v)\geq \f(u)-2^{-n}}
\end{equation*}
and
\begin{equation*}
s\coloneqq\sup\s{\f(v);v\in M}.
\end{equation*}
Then given any $v\in M$ such that $s-\f(v)\leq2^{-k-n}$, it holds that
\begin{equation*}
\forall w\in2^{\leq k}:s-\f(v\app w)\leq2^{-n},\quad\text{in particular}\quad v\app w\in M.
\end{equation*}

