[Lemma 22 (H\"older bump packing) of arXiv:2608.31157, 'Sharp Approximation Rates for Neural Networks with Affine Latent Parameterizations'] Let $d\in\N^+$ and $0<\alpha\le1$, and let
$\calF\subseteq C(\R^d)$ be a real-valued function class.  Let
$V\in[1,\infty)$ satisfy
\[
 \VCdim(\calF)\le V.
\]
Then
\begin{equation}
 \sup_{f\in\calH_d^\alpha}\inf_{g\in\calF}
 \lVert f-g\rVert_{L^\infty([0,1]^d)}
 \ge \widetilde{c}_\alpha V^{-\alpha/d}.
\end{equation}
Here, as above, $\widetilde{c}_\alpha:=4^{-(\alpha+1)}2^{-\alpha}$.

[Lemma 111 (The ingoing eikonal function $\ubar$ on $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] }$]  

Let $\ubar$ be the ingoing eikonal function solving \eqref{E:INGOINGEIKONALEQUATIONINITIALVALUEPROBLEM} and let $\mr \ubar$ be its restriction to $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}$ as in \eqref{E:RESTRICTIONOFUBARONDATASURFACE}. Then the following identities hold for $A = 2,3$:
\begin{subequations}
	\begin{align} 
		\UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \mr \ubar & = - \Lunit \upmu \big|_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}},   \\ 
		\datasurfacegeometricp{x^A} \mr \ubar & = - \geop{x^A} \upmu \big|_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}},  
	\end{align}
\end{subequations}
Moreover, the following sharp estimate for $\Lunit \mr \ubar$ and identity for $\muX \mr \ubar$ hold provided that $|\timefunction_0|$ is sufficiently small: 
\begin{subequations}
	\begin{align} 
		-1.01  \le \min_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}} \frac{\Lunit \mr \ubar}{\Lunit \upmu} & \le \max_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}} \frac{\Lunit \mr \ubar}{\Lunit \upmu}  \le -0.99,  \\
		\muX \mr \ubar \big|_{\twoargmumuxtorus{0}{0}} &= 0, 
	\end{align}
\end{subequations}
In addition, the following H\"older estimates hold:
\begin{subequations}
	\begin{align} 
		\left\| \Lunit \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)}, \, \left\| \newuL \Lunit \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)}, \, \left\| \newuL\newuL \Lunit \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)} & \le C, \\
		 \left\|  \muX \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)},\,  \left\| \newuL \muX \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)}, \, \left\| \newuL\newuL \muX \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)} & \le C,  \\
		 \left\|  \geop{x^A}  \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)}, \,  \left\| \newuL \geop{x^A}  \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)}, \,  \left\| \newuL\newuL \geop{x^A}  \mr \ubar \right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)} & \le C \initialsmall.  
	\end{align}
\end{subequations}

[Theorem 16 ($L^p$ centered operator) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Fix $p\ge2$ and $\eps>0$.  If
\begin{equation}
 \mathfrak S_H^{(\eps)}(\beta,\sigma)
 +\mathfrak S_B^{(\eps)}(\zeta,\sigma)<\infty,
\end{equation}
then $\cB^\circ_\Lambda$ is a well-defined random bounded operator
\[
 \cB^\circ_\Lambda:\Xspace_T^\sigma\to\Yspace_T^{\beta,\zeta},
\]
uniformly in $\Lambda$, and
\begin{equation}
 \left\|\norm{\cB^\circ_\Lambda}_{\Xspace_T^\sigma\to\Yspace_T^{\beta,\zeta}}
 \right\|_{L^p(\Omega)}
 \lesssim_{p,T,\eps}
 \mathfrak S_H^{(\eps)}(\beta,\sigma)
 +\mathfrak S_B^{(\eps)}(\zeta,\sigma).
\end{equation}
Moreover, as $\Lambda\to\infty$,
\begin{equation}
 \cB^\circ_\Lambda\to\cB^\circ
 \quad\text{in }L^p\bigl(\Omega;\cL(\Xspace_T^\sigma,\Yspace_T^{\beta,\zeta})\bigr).
\end{equation}

