[Proposition 17 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $t \geq 0$.
    Then, if $X \subseteq V_{\geq t}$,

    \begin{equation}
       \sum_{u \in X} w_K(u) \leq |K[{X \leftrightarrow V_{\geq t}}]| .
    \end{equation}
    Similarly, if $Y \subseteq V_{< t}$,
    \begin{equation}
        \sum_{u \in Y} w_K(u) \geq |K[{Y \leftrightarrow (V_{\geq t} \cup Y)}]|.
    \end{equation}


    In particular, $\dsum_{u \in V_{\geq t}} w_K(u) = |K[V_{\geq t}]|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 24 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] Fix a $\widehat{\bb X}_p(\cdot)-$equivalence class
$\mf D\subset \mc S_p$. For every continuous function
$\phi\in C(\bb T)$,
\begin{equation*}
\int_{\Omega_{\mf D}}
\frac{\phi(x)}{\mss a(x)} \,
e^{-S_{\mf D}(x)/\epsilon}\, dx \,=\,
[1+O(\epsilon)]\,
\sqrt{\epsilon}\,
e^{-S_{\mf D}(\mc M_p(\mf D))/\epsilon}
\, \sum_{j:m_j\in\mc M_p(\mf D)}\phi(m_j)\pi_1(j)\,.
\end{equation*}
In particular,
\begin{equation*}
\int_{\Omega_{\mf D}}
\frac{1}{\mss a(x)}
\, e^{-S_{\mf D}(x)/\epsilon}dx \,=\,
[1+O(\epsilon)]\,
\sqrt{\epsilon}\,e^{-S_{\mf D}(\ms
M_p(\mf D))/\epsilon} \, \sum_{k\in D}\pi_p(k)\,.
\end{equation*}

