body:
[Lemma 6 (Covariance/Bessel transfer) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Let $U_1:\wt\cA\to\cA$ and $U_2:\wt\cB\to\cB$ be bounded, and define
\[
 \wt{\mathbf H}(\wt a,\wt b,c,e)
 :=\mathbf H(U_1\wt a,U_2\wt b,c,e).
\]
Then, for $2\le r\le\infty$, with $\Sch_\infty$ understood as the operator norm class,
\begin{equation}
 \max_j\norm{\wt F_j}_{\Sch_r}
 \le \norm{U_1}_{\rm op}\norm{U_2}_{\rm op}
 \max_j\norm{F_j}_{\Sch_r}.
\end{equation}

[Lemma 3.8 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] Let $m,n,k$ be positive integers. 
    For each $s=1,\ldots,k$, consider a probability space $(\Omega_s,\mathcal F^s,\mathbb P_s)$ and denote their product probability space by $(\Omega, \mathcal F,\mathbb P)$. Let $G=\bigcup_{i=1}^n G^{(i)}$ where $G^{(i)}$'s are disjoint sets with $|G^{(i)}|=m$. For each $s$, let $X_l^s:\Omega_s\to G$ with $l=0,1,\ldots$ be random variables adapted to $\{\mathcal F_l^s\}_{l\geq 0}$, where $\{\mathcal F_l^s\}_{l\geq 0}$ is a sequence of increasing $\sigma$-fields.
    Suppose that for any $H^{(i)}\subseteq G^{(i)}$, any integer $1\leq s\leq k$ and any integer $l\geq 1$, we have
    \begin{equation}
        \mathbb P_s\left(X_l^s\in H^{(i)} \,\Big |\,  \mathcal F_{l-1}^s\right)<F(|H^{(i)}|/{m})\,\mathbb P_s\left(X_l^s\in G^{(i)}\,\Big |\,  \mathcal F_{l-1}^s\right),
    \end{equation}
    where $F:(0,1]\to\mathbb R^+$ is a continuous and increasing function such that 
    \begin{equation}
        \int_0^1 \frac{1}{F(x)}dx=\infty.
    \end{equation}
    Then, for any $K>0$, there exist constants $q=q(k,K,F)<1$ and $m_0=m_0(k,K,F)>0$, such that for any $m>m_0$ and any $n\geq1$, we have
    \begin{equation}
    \mathbb P\Big(G\subseteq\{X_l^s:l=0,\ldots,[Kmn],s=1,\ldots,k\}\Big)<q^{mn}.
    \end{equation}

