[Corr martingaleutile of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Under the \hyperlink{gen}{general setting}, let $\varphi \in \mathcal{C}^{1,1}_{\omega}(\mathbb{R}^{+} \times \mathbb{R}^{*}_{+})$. Then the process $(\langle \mu_{t}, \varphi_{t} \rangle)_{t \geq 0}$ is a semi-martingale, with for all $t \geq 0$, a finite variation part given by
\begin{align*}
V_{\varphi,t} := & \hspace{0.1 cm} \langle \mu_{0}, \varphi_{0} \rangle + \displaystyle{\int_{0}^{t}} \langle \mu_{s}, \Phi_{s}(R_{s},.) \rangle \mathrm{d}s - \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+} }} d(x)\varphi_{s}(x) \mu_{s}(\mathrm{d}x) \mathrm{d}s \\
    &  + \displaystyle{\int_{0}^{t}}\int_{\mathbb{R}^{*}_{+} } b(x)\bigg( \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x)\bigg) \mu_{s}(\mathrm{d}x) \mathrm{d}s,
\end{align*}
with $\Phi$ associated to $\varphi$ as in (equation eq:Phidef of the paper), and a square-integrable martingale part $\heartsuit_{\varphi,t} := \langle \mu_{t}, \varphi_{t} \rangle - V_{\varphi,t} $ whose predictable quadratic variation is given by
\begin{align*}
\langle \heartsuit_{\varphi} \rangle_{t} =  \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}b(x)\bigg[ \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x) \bigg]^{2} \mu_{s}(\mathrm{d}x) \mathrm{d}s + \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}d(x)\varphi_{s}^{2}(x) \mu_{s}(\mathrm{d}x) \mathrm{d}s.
\end{align*}

[Lemma 20 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ be a non-zero finite measure and let $\gamma >0$. Consider $\text{DSBM}(\gamma, c)$, $(\Tilde{\mathcal{Y}}_s)_{s \geq 0}$, with initial measure $\Tilde{\mathcal{Y}}_0 = \mu_{\rm a}$. Then the dimension of the range and of the support of $(\Tilde{\mathcal{Y}}_s)_{s \geq 0}$ are those of $\text{SBM}(\gamma)$ given in Proposition \ref{proposition dimension range and support sbm}, i.e. for $s>0$
    \begin{equation*}
        \text{dim}(\text{supp}(\Tilde{\mathcal{Y}}_s)) = 2 \wedge d \hspace{0.25cm} \text{   on   } \{\Tilde{\mathcal{Y}}_s \neq 0\} \hspace{0.25cm} \Tilde{\mathbb{P}}_{\mu_{\rm a}}\text{-a.s.;} \hspace{0.5cm} \text{dim}(\mathcal{R}(\Tilde{\mathcal{Y}})) = 4 \wedge d \hspace{0.25cm} \Tilde{\mathbb{P}}_{\mu_{\rm a}}\text{-a.s.}
    \end{equation*}
    \begin{proof}
        The proof for the upper bounds, i.e. that $\text{dim}(\text{supp}(\Tilde{\mathcal{Y}}_s)) \leq 2 \wedge d$ and $\text{dim}(\mathcal{R}(\Tilde{\mathcal{Y}})) \leq 4 \wedge d$, immediately follows from the fact that $\Tilde{\mathcal{Y}}_s$ is dominated by $\mathcal{X}_s$. The proof for the lower bound for the support uses the same argument as \cite[Theorem IV.7]{le1999spatial} as the following condition is satisfied:
        \begin{equation}
            \Tilde{\mathbb{N}}_b\Big(\int_{\norm{y} \leq K} \int_{\norm{z} \leq K} \Tilde{\mathcal{Y}}_t(dy) \Tilde{\mathcal{Y}}_t(dz) |y-z|^{\varepsilon - 2}\Big) < \infty
        \end{equation}
        For the lower bound for the range, we define the total occupation measure $\Tilde{\mathcal{J}}$ of $\Tilde{\mathcal{Y}}$ by 
        \begin{equation*}
            \langle \Tilde{\mathcal{J}}, g \rangle = \int_{s=0}^\infty ds \langle \Tilde{\mathcal{Y}}_s, g \rangle
        \end{equation*}
        which is supported on $\mathcal{R}(\Tilde{\mathcal{Y}})$. The proof for the lower bound for the range then uses the same argument as in \cite[Theorem IV.7]{le1999spatial} as we have that for $d \geq 4$ and for every $K$, $\varepsilon$, $\delta>0$ that
        \begin{equation}
            \Tilde{\mathbb{N}}_b\Big(\int_{\varepsilon \leq \norm{y - b} \leq K} \int_{\varepsilon \leq \norm{z - b} \leq K} \frac{\mathcal{J}(dy)\mathcal{J}(dz)}{|y-z|^{4-\delta}}\Big) < \infty,
        \end{equation}
        as well as the fact that $\Tilde{\mathcal{Y}}$ is a non-trivial measure-valued process (i.e. a.s. not equal to the zero-measure for a positive initial interval of time $[0,y]$). Both the inequalities in \eqref{equation support inequality lower bound} and \eqref{equation range inequality lower bound} can be seen from a direct comparison with SBM which has the corresponding inequalities in the proof of \cite[Theorem IV.7]{le1999spatial}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:orderMN of arXiv:2603.16824, 'Age-dependent random connection models with arc reciprocity: clustering and connectivity'] Let \(\gamma\geq 1/2\) and consider the quantities \(\mathbf{M}_t\) and \(\mathbf{N}_t\), defined in~(equation eq:defMN of the paper). We have
	\begin{equation*}
	\mathbb{E}[\mathbf{M}_t]\asymp 
	\begin{cases}
		t \log(t), & \text{ if }\gamma = 1/2,
		\\
		t^{2\gamma}(\log t)^{2\gamma-1}, & \text{ if } \gamma>1/2.
	\end{cases}
\end{equation*}
Moreover, \(\mathbb{E}\mathbf{N}_t =o(\mathbb{E}\mathbf{M}_t)\).

[Lemma lem:interior_intersection_right of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Fix $a_1 >0$, $p \in (0,1)$. Suppose that we have the setup of Section~(se:bubble_setup of the paper) with $(D,x_0,y_0) = (\delta\mathbf{D},-i\delta,i\delta)$. Let $z_1,w_1 \in \partial B(0,\delta/2)$. Let $\eta_{z_1}^{\theta_2}$ be the angle $\theta_2$ flow line starting from $z_1$, stopped upon exiting $B(0,3\delta/4)$. Let $\eta_{w_1}^R$ be the angle $-\pi/2$ flow line starting from $w_1$, stopped upon exiting $B(0,3\delta/4)$. In case $\eta_{w_1}^R$ and $\eta_{z_1}^{\theta_2}$ intersect, sample the internal metric in the regions bounded between them. 
Let $E^p$ be the event that the following hold.
\begin{itemize}
\item The right side of $\eta_{w_1}^R$ and the left side of $\eta_{z_1}^{\theta_2}$ intersect with an angle difference of $-\pi/2 - \theta_2$, and they do not intersect in any other way.
\item There exist $x',x,y,y' \in \eta_{z_1}^{\theta_2} \cap \eta_{w_1}^R$ such that $(x,y) \in \intptsapproxbubble{U_{x',y'}}{\epsilon}$ as in~(equation eq:intpts_bubble of the paper) and $U_{x',y'} \subseteq B(0,\delta^{1+a_1})$ and $\metapproxacres{\epsilon}{U_{x',y'}}{x}{y}{\Gamma} \geq \median{\epsilon}+\epsilon^{-a_0}\mathbf{a}_{\epsilon}$.
\item The following event has conditional probability at least $p$ given $\eta_{z_1}^{\theta_2}$, $\eta_{w_1}^R$, $X_\delta^{\theta_2}$, $X_\delta^{-\pi/2}$, and the values of $h$ on these sets:
\begin{itemize}
\item The flow line $\eta_2$ merges into $\eta_{z_1}^{\theta_2}$ before entering $B(0,\delta/4)$.
\item The angle $-\pi/2$ flow line of $h$ from $-i\delta$ to $i\delta$ merges into $\eta_{w_1}^R$ before entering $B(0,\delta/4)$.
\end{itemize}
\end{itemize}
Then $\mathbf{P}[E^p] = O(\delta^{{\alpha_{\mathrm{apr}}}})$ as $\delta \to 0$.

[Thm thmLowerBound of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] For any $p_0\in(0,\tfrac12)$, there exists a positive constant $C(p_0)$ such that, for all~$n$ large enough,
\begin{equation}
\inf_\pi \sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n^\pi(p)\bigr)\ge \frac{C(p_0)}{\sqrt n},
\end{equation}
where the infimum is over all (possibly randomized) \mbox{$p$-blind} rules and where $W_n^\pi(p)$ denotes the win probability of~$\pi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

