[Lemma opt2prefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in \mathbb{R}$, $q\in (0,1)$ and $u\in (0,1)$. Let $\zeta\in \mathrm{Prefix}_2(u,q)$ satisfy the assumptions of Proposition (prop:annealed 0 of the paper). Let $(X_t)_{t\in [0,1]}$ be the Auffinger--Chen process
		\begin{equation*}
			\begin{cases}
				\mathrm{d} X_t=\xi''(t)\zeta([0,t])\partial_x \Phi_\zeta(t,X_t)\mathrm{d} t+\sqrt{\xi''(t)} \mathrm{d} B_t\\
				X_0=0.
			\end{cases}
		\end{equation*}
		For every $s\in [0,1]$, set
		\begin{equation*}
			H_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}[(\partial_x\Phi_\zeta(r,X_r))^2]-r\Bigr)\mathrm{d} r.
		\end{equation*}
		Then, the following hold:
		\begin{enumerate}[label=(\roman*)]
			\item \begin{equation}
				-\mathbb{E}[\Phi_\zeta(q,X_q)]+\int_0^q t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_q^1 t\xi''(t)\zeta([0,t])\mathrm{d} t=-f,
			\end{equation}
			\item \begin{equation}
				\mathbb{E}[(\partial_x\Phi_\zeta(q,X_q))^2]=q,
			\end{equation}
			\item  \begin{equation}
				\mathrm{supp}(\zeta)\cap [q,1]\subset \underset{[q,1]}{\mathrm{arg\,min}}(H_\zeta).
			\end{equation}
		\end{enumerate}

[Theorem 7 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Fix $T\in\N$ and $m\in\N$. Assume $\Delta<\Delta_0$, where $\Delta_0$ is the constant in Theorem~\ref{thm:main}. Under the assumptions \textup{\textbf{(A1.3)}}, \textup{\textbf{(A2)}} and \textup{\textbf{(A3)}}, given any $m$ test functions $\varphi_1,\dots,\varphi_m\in C^2(\T)$ and a function $\Psi\in C_b^3(\R^m)$, we have
    \begin{equation}
        \left|\mathbb{E}\Psi\left(\langle\varphi_1,\eta_t^N\rangle,\dots,\langle\varphi_m,\eta_t^N\rangle\right)-\mathbb{E}\Psi\left(\langle\varphi_1,\eta_t\rangle,\dots,\langle\varphi_m,\eta_t\rangle\right)\right|\leq\frac{C\mathrm{e}^{Ct}}{\sqrt{N}},\quad t=0,\dots,T,
    \end{equation}
    where the constant $C>0$ depends on $\Delta,m,\|\Psi\|_{C_b^3},\|F\|_{C^2},\|h\|_{C^2}$ and $\|\varphi_i\|_{C^2}(1\leq i\leq m)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 (Evolution of the area and its push-forward) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Let $X_t:=\partial_tF_t$.  Then the induced area measure on the fixed
domain satisfies
\begin{equation}

 \partial_t\dd\mu_t
 =-\langle H_t,X_t\rangle\dd\mu_t
 =a_t^{-2}\langle H_t,G_t\rangle\dd\mu_t.
\end{equation}
Moreover, for every $\varphi\in C^1(\Sph^3)$,
\begin{equation}

 \begin{aligned}
 \frac{\dd}{\dd t}\int_{\Sph^3}\varphi\dd\lambda_t
 &=\int_\Sigma
 \left[
  \big\langle\nabla^{\Sph^3}\varphi(F_t),X_t\big\rangle
  -\varphi(F_t)\langle H_t,X_t\rangle
 \right]\dd\mu_t\\
 &=\int_\Sigma a_t^{-2}
 \left[
  -\big\langle\nabla^{\Sph^3}\varphi(F_t),G_t\big\rangle
  +\varphi(F_t)\langle H_t,G_t\rangle
 \right]\dd\mu_t.
 \end{aligned}
\end{equation}

[Lemma def:irreducibility22 of arXiv:2510.00748, '\bf On irreducible central limit theorems'] Let the assumptions and conventions of the present section hold. Then, the sequence $\{Z_n\}$ is reducible in the sense of Definition (def:irreducibility of the paper) (see also Remark (r:reducible of the paper)-{\rm (redCLTconda of the paper),(redCLTcondb of the paper),(redCLTcondc of the paper)}) if and only if there exist partitions $\{B_1,\ldots,B_{m_n}\} = \{B^{(n)}_1,\ldots,B^{(n)}_{m_n}\}$ of the vertex sets $V_n$, such that, as $n \to \infty$,
    \begin{enumerate}[label={\rm (\roman*')}]
    \item  $m_n\to \infty$;
    \item  $\sum_{i=1}^{m_n} E(B_i,B_i) \sim |\mathcal{E}_n|$;
    \item  $\max_{i=1,...,m_n} E(B_i,B_i) = o\big(|\mathcal{E}_n|\big)$.  
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

