\sum_{k=0}^m (-1)^k\binom{a+k}{a}  \binom{b}{m-k}
=(-1)^m\binom{a-b+m}{m}.   
\end{align}
Indeed, the LHS of \eqref{ident} is the coefficient on $x^{a+m}$ in
\begin{align*}
&\sum_{u=0}^{b} \sum_{\ell=a}^\infty \binom{\ell }{a} \binom{b}{u}  (-1)^{\ell-a} x^{u+\ell}
=\left[\sum_{u=0}^{b} \binom{b}{u} x^u\right]\times
\left[\sum_{\ell=a}^\infty \binom{\ell }{a} (-1)^{\ell-a} x^{\ell}\right]    
\\ & =(1+x)^{b} \times \frac{x^a}{(1+x)^{a+1}}=x^a (1+x)^{-(a-b+1)}
=x^a\sum_{m=0}^\infty (-1)^m \binom{a-b+m}{m} x^m.
\end{align*}

