[Thm 75 ({\cite[Theorems 1.5(ii) and 1.7) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {BTM24}}]
Let $\alpha>2$ and $E\in \left(0,\frac{\alpha-2}{10(2\alpha-1)}\right)$.
Then it holds for any $K\in (0,\infty)$ and $0<T_1<T_2<\infty$ that
\begin{equation*}
  \sup_{x\in \R}|P_0(X_1\le x)-P^n_0(X^n_1\le x)|=O(n^{-\theta}),
\end{equation*}
and
\begin{equation*}
  \lim_{n\to\infty}n^{\frac{2}{3}E}\sup_{\substack{|x|\le K\\t\in [T_1,T_2]}}\left| p(t,0,x)-p_n\left( t,0,\frac{\floor{nx}}{n} \right) \right|=0,
\end{equation*}
$P$-almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:two-point-decompose of arXiv:2605.19419, 'Tail exponents of the three-dimensional uniform spanning tree and Abelian sandpile'] Suppose $4r<R$ and $x\in\partial B_R$, $y\in\partial B_r$. Suppose that $\gamma$ is an ILERW started from $0$. $S_{1}$ and $S_{2}$ are two independent SRWs started from $x$ and $y$. Write $P_{x,y}$ for their joint law. Let $E$ denote the intersection of the following events:
\begin{itemize}
\item[1.]\ $S_{1}$ hits $0$ and, writing $\tau_{1}$ for the first hitting time of $0$, $S_{1}[0,\tau_{1}]\cap\gamma=\{0\}$.
\item[2.]\ $S_{2}$ hits $\operatorname{LE}(S_1[0,\tau_1])$ before it intersects $\gamma$.
\end{itemize}
Then,
\begin{equation}
P_{x,y}(E)\gtrsim (\log r)^{-1}R^{-1-\alpha}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 32 (Stein interpolation) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Let $A,B$ be centered $\R^d$-valued vectors with components in
$\mathbb D^{1,2}$, and put $C=\Cov(B)$.  Then, for $u,v\in\R^d$,
\begin{align}
 &\left|
 \E e^{i(u\cdot A+v\cdot B)}
 -\E e^{iu\cdot A}e^{-\frac12v^{\mathsf T}Cv}
 \right|\notag\\
 &\quad\le
 |u|\,|v|
 \left(\sum_{a,b}\norm{\Gamma(A_a,B_b)}_2^2\right)^{1/2}
 +\frac{|v|^2}{2}
 \left(\sum_{a,b}
 \norm{\Gamma(B_a,B_b)-C_{ab}}_2^2\right)^{1/2}.

\end{align}

[Theorem theorem12 of arXiv:2607.01463, 'Two Multi--Draw Coupon Collector models with different retention rules'] Consider the  $d$ coupon collector's problem (d--CCP), where in each run we keep \textbf{the least-collected} coupon so far. Let $T_{N,1}$ be the number of trials until all $N$ different types of coupons, which are uniformly distributed, are collected (at least once). Then,
\begin{equation}
\mathbb{E}[T_{N,1}]
=
\sum_{k=0}^{N-1}
\frac{1}{1-\binom{k}{d}/\binom{N}{d}},

\end{equation}
where $\binom{k}{d}=0,$ if $k<d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

