[Lemma 29 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $x \geq 0$. Assume that, for any $\eta > 0$ and $\pi_0 \in \Sym_n$, there exist $\gamma > 0$, a random subset $\Neg \subseteq \Sym_n$, and a function $F: B(\pi_0, x - \eta) \setminus \Neg \to \mc{P}(\Sym_n)$ verifying the following conditions.

    \begin{enumerate}
        \item if $\pi \in \Dom F$, $|F(\pi)| \geq e^{\gamma n \log n}$;
        \item if $\pi \in \Dom F$ and $\pi' \in F(\pi)$, $\Proba(\pi'| G, H, (p_e)) \geq e^{-o_{\Proba}(n \log n)} \Proba(\pi| G, H, (p_e))$;
        \item if $\pi' \in \Sym_n$, $|F^{-1}(\pi')| \leq e^{o_\Proba(n \log n)}$ (uniformly over $\pi'$);
        \item $\Proba(\pi^* \in \Neg) = o(1)$.
    \end{enumerate}
    Then, if $\hat{\pi}$ is an estimator of $\pi^*$, there exist at least $x(n - o_\Proba(n))$ vertices $v \in [n]$ such that $\hat{\pi}(v) \neq \pi^*(v)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pro: Lp norm of q_infty of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{($L^p$ norm of queue length)} For SSQ, under assumption (ass:heavy_overload of the paper), the $L^p$ norm of the centered queue length is bounded in the below interval
    \begin{align}
        \| \hat{q} \|_{L^p} &\leq \min\{(C_{1,\lambda,\mu}\sqrt{\frac{1}{\gamma}} \sqrt{p} + C_{2,\lambda,\mu} p),  (C_{3,\lambda,\mu} \frac{p}{\log(1+\gamma p/\lambda)})\} \\
        \| \hat{q} \|_{L^p}&\geq C_{4,\lambda,\mu} \exp\left( -C_{5,\lambda,\mu} \frac{1}{ \gamma p} \right) \frac{p}{\log(1+\gamma p/\lambda)} 
    \end{align}
    All the above constants are only dependent on $\lambda, \mu, C$ and $\alpha$. Their closed forms are given in (equation eq: constants for L-p norm of the paper) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:estimate_hyperfluctuating_case of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] \begin{equation*}
			s_{\xi_B}(t)-\bar{s}_{\xi_B}(t) \underset{t\to 0}{=}O(1).
		\end{equation*}

[Lemma L1 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Under Assumption (A1 of the paper), if $\gamma L \leq \frac{1}{2}$, then, for all $t\ge 0 $,
\begin{align*}
	\mathbb{E}[f_s(x^{t+1})]\leq \mathbb{E}[f_s(x^t)]-\frac{\gamma}{4}\mathbb{E}[\|g^t\|^2]+\frac{\gamma}{2}\mathcal{E}_s^t, \quad s \in [S].
\end{align*}
and
\begin{align*}
     \frac{2\left(\mathbb{E}[f_s(x^T)]-f_s(x^0)\right)}{\gamma}+\frac{1}{2}\sum_{t=0}^{T-1}\mathbb{E}[\|g^t\|^2]\leq\sum_{t=0}^{T-1}\mathcal{E}_s^t, \quad s \in [S].
\end{align*}

[Lemma lem:3.2-F of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] There exists a finite constant $C_0$ such that
\begin{equation*}
\begin{aligned}
& \Big |\, \sum_{j=1}^d N^2 (D^2_j \widehat G)(Ax)\,-\, 
K\, (\partial^2_{\vartheta} \widehat G)(Ax) \,-\,
\sum_{k=2}^d (\partial^2_{\theta_k} \widehat G)(Ax)\, \Big|
\\
&\quad 
\, \le\, C_0\, \frac{1}{N} \, 
\Big\{\, K^{3/2}\, \| \partial^3_\vartheta G \|_\infty \,+\,
\sum_{j=2}^d \| \partial^3_{\theta_j} G \|_\infty \, \Big\} 
\end{aligned}
\end{equation*}
for all $N\ge 1$, $x \in {\mathbb{T}}_N^d$, and smooth
$G\colon \sqrt{K} {\mathbb T} \times {\mathbb T}^{d-1}\to {\mathbb{R}}$.

