[Proposition 10 of arXiv:2608.04644, 'Khinchin's and Chung's Laws of the Iterated Logarithm at Time Zero for the Linear Stochast'] Recall that $H$ is given in \eqref{def:H}. Assume  that Condition \ref{hypo} and $H<1$ hold.	There exists a constant $c_{2,11}>0$ such that for all $1\le a<b\le\infty$, $0<t\leq a^{-\frac1{H}},x\in\RR^d$,
\begin{equation}
\begin{split}
	&\|v(\RR_+,t,x)-v([a,b),t,x)\|_{L^2(\Omega)}\\
	\le &\,  c_{2,11}\left(a^{\frac{1-H_0}{H}}t^{H+1-H_0}+b^{-1}\bm{1}_{\{ 0<t<b^{-1/H}\}} +F(b,t,H,H_0)\bm{1}_{\{t\ge b^{-1/H}\}} \right),
    \end{split}
\end{equation}
\textcolor{black}{where, for $b<\infty$ and $t\ge b^{-1/H}$,}
\begin{equation}
	F(b,t,H,H_0):=\begin{cases}	
		b^{-1}, &  H<H_0,\\[1.5ex]
		b^{-1}\left(\log (b^{1/H}t) +  \left(\log (b^{1/H}t)\right)^{1/2}+1\right), &  H=H_0,\\[1.5ex]
		b^{-\frac{H_0}H}t^{(H-H_0)}, &  H>H_0.
	\end{cases}
\end{equation}

