[Theorem thm:RBJ-H5 of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed observable satisfies the mixed diamond
equation
\begin{equation}
\bigl(q\mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}^{-1}
+ p\mathcal{M}_{t+1, \mathbf{a}+\mathbf{2},
\mathbf{n}}^{-1}\bigr)
\mathcal{M}_{t+1, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}
- \mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\bigl(q\mathcal{M}_{t+1, \mathbf{a}+\mathbf{1},
\mathbf{n}}
+ p\mathcal{M}_{t, \mathbf{a},
\mathbf{n}+\mathbf{1}}\bigr) = 0,
\end{equation}
at every $(t, \mathbf{a}, \mathbf{n})$ with
$a_i < y_{n_i+1} + t - 1$ for all~$i$.

[Lemma C-for-critical-def of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For $f$ of the form (equation Form of f of the paper), 
\begin{equation}
\sqrt{\frac{2}{\pi}}\int_0^\infty u_\phi(t, x+\sqrt{2}t)xe^{\sqrt{2} x} dx \to \mathbf{C}(f)
\end{equation}
as $t\to \infty$, where $\mathbf{C}(f)$ is a positive constant. Furthermore, for any fixed $x \in \mathbb{R}$, 
\begin{equation}
\mathbf{C}(f(x+ \cdot)) = e^{\sqrt{2}x}\mathbf{C}(f).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2507.10294, 'Guessing Strategies for Shelf-Shuffling Machines'] We have
    \begin{equation}\max_{1\leq i\leq n-j}p_{i,j}=\frac{\binom{2j-2}{j-1}}{2^{2j-1}}\end{equation}
    and this maximum is achieved if and only if $i=2j-1$ or $i=2j-2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj ER of arXiv:2601.20502, 'Optimal matching under size priority'] Let $G_n$ be Erdös-Reny\'i graphs with parameters $(n, \frac{c}{n})$.
    Define $\mathcal{M}_{\max}(G_n)$ to be the set of maximum size matchings of $G_n$. Writing $\underline{\gamma}$ to be the smallest solution to $x=e^{-ce^{-cx}}$ and $\overline{\gamma}=e^{-c\underline{\gamma}}$, we then have the following:
        \begin{equation}
            \begin{aligned}
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall \mathbb{M} \in \mathcal{M}_{\max}(G_n), e \in \mathbb{M}}\right] &= \underline{\gamma}^2, \\
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall \mathbb{M} \in \mathcal{M}_{\max}(G_n), e \notin \mathbb{M}}\right] &= (1-\overline{\gamma})^2.
            \end{aligned}
        \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition 1 of arXiv:2506.20470, 'Pivot probabilities and norm effects in Gaussian elimination for $\beta$-ensembles'] Let $A$ be a $2 \times 2$ GUE matrix and GEPP pivot comparisons use the $L^1$ norm (as in LAPACK). Then the pivot probability is
    \begin{equation}
    \P(\|A_{21}\|_1 > |A_{11}|) = \P(|Z_1| + |Z_2| > \sqrt 2 |Z_3|) = \frac23
\end{equation}
for $Z_i \sim N(0,1)$ iid. (Proof in the paper; no proof environment follows the statement in the TeX.)

