[Deff eq:doapt of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $S$ be a semigroup  with generator $A$ satisfying $\|S(t)\|_{\mathcal{L}(L^p, L^p)} \lesssim e^{-t}$ (for example if $A$
is a sectorial operator, see (semigrp-deff of the paper)).
  Then for any $\vartheta > 0$ we define the fractional power of $(-A)$ as
  \begin{equation}
      (-A)^{-\vartheta} = \frac{1}{\Gamma(\vartheta)} \int_0^\infty t^{\vartheta - 1} S(t)  dt \,, 
  \end{equation}
  where $\Gamma$ is the usual $\Gamma$-function and the integral exist by the assumed bound on $S$. 

  Furthermore, we define 
  \begin{equation}
      (-A)^\vartheta = ((-A)^{-\vartheta})^{-1} \qquad \textrm{and}\quad A^0 = I \,.
  \end{equation}

[Proposition 3 of arXiv:2605.03902, 'Bundles of Probability Schemes'] The outer rectangle obtained by pasting two fiber products of bundles
  as shown
  \begin{equation}
    \begin{split}
  \xymatrix{
    \Omega_3 \otimes_{\Omega_2} (\Omega_2 \otimes_{\Omega_0}\Omega_1)
      \ar[r] \ar[d] & \Omega_2 \otimes_{\Omega_0} \Omega_1 \ar[r] \ar[d]
      & \Omega_1 \ar[d]^{\alpha} \\ \Omega_3 \ar[r]_{\gamma} & \Omega_2
      \ar[r]_{\beta} & \Omega_0
  }
\end{split}
 \end{equation}
 is isomorphic to the fiber product of the bundles $\alpha$ and $\delta =
 \beta\gamma$.

[Lemma 18 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Let $f:\ZZ^d\to\RR$. Then for all $R\ge 1$,
    \begin{equation}
        \left(\fint_{B_R}\Big|f-\fint_{B_R }f\Big|^{q}\right)^\frac1q\,\lesssim_{p}\, R\left(\fint_{ B_{R}}|\nabla f|^{p}\right)^\frac1p
    \end{equation}
    provided that $\frac1p\le\frac1q+\frac1d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2608.01674, '\textbf{Limit Theorems for Tempered Linear Processes with Innovations in the Domain of Att'] For every $p>1$,
\begin{equation}
 \frac1N\sum_{j\in\Z}|w_N(j)-w(j/N)|^p
 \longrightarrow0, \qquad N\to\infty.

\end{equation}

[Proposition 9 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] Let \((\mathcal{V}, \mathcal{W})\) be Banach spaces and suppose \(K \in L_p(C^\alpha([0, T], \mathcal{V}))\), \(B \in C^\beta([0, T], U)\) for some 
\((\beta \in (\frac{1}{2}, 1])\), \((0 < \alpha \le \gamma < 1)\) and \((\alpha + \beta > 1)\). Also suppose that $f$ is of $BC^2$ and $G$ are Lipschitz continuous with respect to \(x\) and globally bounded over \(r\in[0,t]\).
Then, if \(X : [0, T] \to \mathcal{V}\)
satisfies the controlled Young differential equation
\begin{equation}
X_t = X_0 + \int_0^t f(s,X_s) \dd B_s + \int_0^t G(s) X_s\dd s + K_t.
\end{equation}
Then, 
\begin{equation}
\|X\|_{\infty,p,[0,T]} \le C_2 e^{(2|f|^{p}_{-\kappa,p})^{\frac{1}{(\bar \eta-\alpha)p }}}(\|X_0\|^p+\mathbb{E}[\|K\|_\alpha^p]+\|f\|_{\infty}+1)
\end{equation}
and 
\begin{equation}
\|X\|_{\alpha,p} \le C_1(\mathbb{E}[\|K\|_\alpha^p]+\mathbb{E}[\|X\|^p_{\infty}]+1).
\end{equation}
for some constants \(C_1, C_2 > 0\) depending on \(\alpha, \beta, H, T\) and \(\|f\|_{BC^2}, \|G\|_{Lip}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Let $b,\sigma$ satisfy (equation M1 of the paper), (equation M2 of the paper) and \textup{(M3)}. Let  $\gamma _{k}=\frac{1}{(1+k)^{\beta }}$ with $
		\beta \in (\frac{2}{3},1)$ and  $\hat{p}=\frac{2(p^{\prime }-2)}{(d+5/2)(p^{\prime
			}-2)+(d+2)2}$.  Then, for every 
		\begin{equation*}
			\zeta \in (0,1-\frac{L }{\bar{b} })\cap \big(0,\frac{\hat{p}}{2}\big],
		\end{equation*}
		there exists $C\in {\mathbb R}_+$ such that for all $k\ge 1$,  $\mathbb{E}[W_{2}^{2}(\rho
		_{k}(Y),\mu _{\ast })]\leq \frac{C}{k^{(1-\beta)\zeta}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def PCPS-coherence of arXiv:2607.19511, 'A Conditional Probability Hierarchy for Stochastic Choice\footnote{We thank Samson Abramsk'] A stochastic choice rule $G \mapsto c_G(\cdot)$ satisfies \textbf{PCPS-coherence} if the assignment given by
\begin{equation} 
\mu([E, G]_\Pi) = c_G(E),
\end{equation}
is a well-defined positive real partial charge on $(\Pi, {\cal C}_\Pi)$.

[Cor 31 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $\eta>0$. Let $n\geq 1$.
Then a.s.,
\begin{displaymath}
\E\big[\Vert :\Phi^{n}:\Vert^{2}_{H^{-\eta}(\C)}\big\vert A\big]
=
\Vert \psi_{n,A}\Vert^{2}_{H^{-\eta}(\C)}
+
\E\Big[
\Big\Vert
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A}^{k}:\Phi_{D\setminus A}^{n-2k}:
\Big\Vert^{2}_{H^{-\eta}(\C)}
\Big\vert A
\Big] .
\end{displaymath}
In particular,
\begin{displaymath}
\E\big[\Vert :\Phi^{n}:\Vert^{2}_{H^{-\eta}(\C)}\big]
=
\E\big[\Vert \psi_{n,A}\Vert^{2}_{H^{-\eta}(\C)}\big]
+
\E\Big[
\Big\Vert
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A}^{k}:\Phi_{D\setminus A}^{n-2k}:
\Big\Vert^{2}_{H^{-\eta}(\C)}
\Big].
\end{displaymath}

