[Definition def:dynamics-coupling of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] [Grand coupling of dynamics] For each vertex $v$ in $\mathbb Z^d$, assign an independent intensity-$1$ Poisson process process on $(0,\infty)$, denoted $\mathcal T_v = (t_{v,1}<t_{v,2}<...)$ and to each point $t\in \bigcup_i \{t_{v,i}\}$ assign a $\text{Unif}[0,1]$ random variable $\mathcal U_{v,t}$. For every finite $\Lambda \subset \mathbb Z^d$, boundary conditions $\eta \in \{\pm 1\}^{\Lambda^c}$ and inital configuration $x_0\in \{\pm 1\}^\Lambda$, generate the Glauber dynamics $(X_t)_{t\ge 0} = (X_{\Lambda^\eta,t}^{x_0})_{t\ge 0}$ on $\Lambda$ with boundary conditions $\eta$ initialized from $x_0$ as follows: let $t_1<t_2<...<t_{k(t)}<t$ be the ordered points of $\bigcup_{v \in \Lambda} \mathcal T_v$ at times before $t$, 
    \begin{itemize}
        \item for $s\in [0,t_1)$, let $X_s = x_0$; 
        \item iteratively, for $i = 1,...,k(t)$, for $s\in [t_i,t_{i+1})$, if $t_i\in \mathcal T_v$, let 
        \begin{align*}
            X_s(w) & = X_{t_i^-}(w) \qquad w\ne v\\ 
            X_s(v) & = \begin{cases}+1  & \text{ if }\quad  \mathcal U_{v,t_i}\le \pi_{\Lambda}^{\eta}(\sigma_v = +1 \mid (\sigma_w)_{w\ne v} = (X_{t_i^-}(w))_{w\ne v}) \\ -1 & \text{ else}
            \end{cases}
        \end{align*}
    \end{itemize}

[Theorem thm:hawkes-closure of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Fix a truncation level $m\in\mathbb{N}$. For all pairs $(r,w)$ satisfying
\begin{equation}
0\le r\le m,
\qquad
w\in\{0,1\}^{\ast},
\qquad
r+|w|\le m,
\end{equation}
define
\begin{equation}
Y_{r,w}(t)=\mathbb{E}\big[\lambda_t^r S_w(t)\big].
\end{equation}
Then the vector $Y^{(m)}(t)=(Y_{r,w}(t))_{r+|w|\le m}$ satisfies a finite-dimensional linear ordinary differential equation
\begin{equation}
\frac{\,\mathrm{d}}{\,\mathrm{d} t}Y^{(m)}(t)=A_mY^{(m)}(t),
\qquad
Y_{r,\varnothing}(0)=\ell^r,
\qquad
Y_{r,w}(0)=0\quad(w\ne\varnothing),

\end{equation}
where the matrix entries are determined by the coordinate formula
\begin{align}
\frac{\,\mathrm{d}}{\,\mathrm{d} t}Y_{r,w}
={}&
\mathbf 1_{\{w=v0\}}Y_{r,v}
+r\beta\mu\,Y_{r-1,w}-r\beta\,Y_{r,w}
\nonumber\\
&+
\sum_{j=0}^{r-1}\binom{r}{j}\alpha^{r-j}Y_{j+1,w}
+
\sum_{j=0}^{r}\binom{r}{j}\alpha^{r-j}
\sum_{k=1}^{\rho(w)}\frac{1}{k!}Y_{j+1,w^{[-k]}}.

\end{align}
Terms with negative intensity powers are omitted, so the drift term $r\beta\mu Y_{r-1,w}$ is absent when $r=0$. Consequently,
\begin{equation}
\mathbb{E}[\mathrm{Sig}^{M,(m)}(X)_{0,T}]
=
\big(Y_{0,w}(T)\big)_{|w|\le m}
=
\Pi_m\exp(TA_m)Y^{(m)}(0),
\end{equation}
where $\Pi_m$ selects the coordinates with $r=0$.

