[Lemma 17 of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Under the same conditions as in Proposition~\ref{prop:ratio}, we have
\begin{equation}
  \E\left[\langle U(l)\rangle-\frac{\E_\xi[U(\xi+\gamma)W(\beta(\xi+\gamma)+h)]}{\Wtil(\beta\gamma+h)}\right]^{2k}\le \frac{K}{N^k},
\end{equation}
where now $\xi\sim N(0,v)$ and $v=p-q$. Moreover,
\begin{equation}
  \frac{\E_\xi[U(\xi+\gamma)W(\beta(\xi+\gamma)+h)]}{\Wtil(\beta\gamma+h)}
  =\int U(x)d\nu_N(x),
\end{equation}
where $d\nu_N$ is the mixture of $2S+1$ Gaussian measures defined in \eqref{eq:nu-def}.

[Prop 1 of arXiv:2606.17472, '2606.17472'] Assume that $X$ is recurrent and (\ref{ConditionA}) holds. We have that there is a unique probability measure $\mu_B$ with support in $B$ that arises as the weak limit
  \begin{align*}
    r_q(0)m_B^q\Rightarrow \mu_B,\qquad q\to 0;
  \end{align*}
and a real-valued constant $k(B),$ such that
\begin{align*}
  \lim_{q\to 0}r_q(0)\Big(r_q(0)m_B^q(B)-1\Big)=k(B).
\end{align*} We will refer to $\mu_B$ as the  \emph{equilibrium measure} and to $k(B)$ as the \emph{Robin constant}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:LASS of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $X^{(n)}_H$ be an $n$-MFSM satisfying Assumption~(ass:params of the paper)
with $H \in \mathcal{C}^n(\mathbb{R})$ (i.e., $H$ is $n$-times continuously
differentiable; for $n=1$ this is equivalent to $\beta > 1$).
Then for each $t_0 \in \mathbb{R}$:
\begin{equation}

\left\{
\frac{X^{(n)}_H(t_0 + \varepsilon\tau)
  - \displaystyle\sum_{k=0}^{n-1}\frac{X^{(n,k)}_H(t_0)}{k!}\,
  (\varepsilon\tau)^k}
{\varepsilon^{H(t_0)}}
\right\}_{\tau \in \mathbb{R}}
\overset{\mathrm{f.d.d.}}{\longrightarrow}
\bigl\{Y^{(n)}_{H(t_0)}(\tau)\bigr\}_{\tau \in \mathbb{R}}
\quad \text{as } \varepsilon \to 0^+,
\end{equation}
where $Y^{(n)}_{H(t_0)}$ is an $n$-FSM (in the sense of [Kawai2016])
with constant Hurst parameter $H(t_0)$ and stability index $\alpha$,
whose moving-average representation is
\begin{equation}

Y^{(n)}_{H(t_0)}(\tau)
= \int_\mathbb{R}
\frac{(\tau-u)_+^{H(t_0)-1/\alpha}}{\Gamma(H(t_0)+1-1/\alpha)}
\,dM_\alpha(u).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For $d\ge 3$, $n\ge 1$, $D\subset \widetilde{\mathbb{Z}}^d$ and $v,w\in \widetilde{\mathbb{Z}}^d\setminus D$,
	\begin{equation}
  \big|  \mathbb{P} (v\xleftrightarrow{\ge 0} w  ) -\mathbb{P}^{D}(v\xleftrightarrow{\ge 0} w ) \big|  \lesssim  \widetilde{G}(v,w)-\widetilde{G}_D(v,w). 
\end{equation}

