body:
[Theorem 1 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1}--\eqref{H2}. Define $\alpha(t) :=\frac{1}{4}\int_0^t\sigma(W^{\ell^\sigma}_s)^2\d s$. Let $\alpha^{-1}(t)$ be the inverse of $\alpha(t)$.\footnote{We will verify in Lemma~\ref{lem:alpha} that $\alpha$ is a.s. strictly increasing, so $\alpha^{-1}(t)$ is well-defined.} Then
\begin{align}
    \Big(n^{-1}C_{\lfloor 2n^2 t_1\rfloor}(\mathscr{T}^{n}), n^{-1}H_{\lfloor n^2 t_2\rfloor}(\mathscr{T}^{n})\Big)_{0\le t_1,t_2<\infty} \overset{d}{\longrightarrow} \Big(W_{\alpha^{-1}(t_1)}^{\ell^\sigma}, W^{\ell^\sigma}_{\alpha^{-1}(t_2)}\Big)_{0\le t_1,t_2<\infty}
\end{align}
in the product space \(\big(D[0, \infty)\big)^2\) equipped with the product Skorokhod topology
(where the functions on both sides are extended by \(0\) outside their original domains). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 1 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] Let $0\leq F\leq G$ in $B\left(H\right)$, and set
\begin{equation}
H_{G}=\overline{ran}\,(G^{1/2}).
\end{equation}
Then there is a unique positive contraction $A$ on $H_{G}$ such
that 
\begin{equation}
F=G^{1/2}AG^{1/2},
\end{equation}
where $A$ is extended by zero on $H^{\perp}_{G}$.

