[Lemma 9 of arXiv:2606.00586, 'Stein's Method for Convergence Rates of Invariant Measures in the Nonlocal-to-Local Limit'] Suppose $b$ satisfies \eqref{eq:dispt}, then
    \begin{enumerate}[(a)]
        \item for any $\lambda\in (0,\kappa/\theta)$, it holds that 
        \begin{equation}
        \langle \exp(\lambda |x|^\theta), \pi\rangle <\infty. 
        \end{equation}
        \item for any $\alpha>2-\theta$ and $q\in (0, \alpha+\theta-2)$, it holds that  
        \begin{equation}
            \langle |x|^{q}, \pi_\alpha \rangle <\infty. 
        \end{equation}
    \end{enumerate}

[Proposition prop:Wick of arXiv:2605.21265, 'The non-Hermitian minor process'] Assume the set-up and conditions of Proposition~(prop:underline_comp of the paper) with the only differences that we additionally fix $n\in\mathbf{N}$, consider $j\in[n]$ instead of $j\in[2]$ and do not assume that $x_1\le x_2$. It holds that
\begin{equation}

\mathbf{E}\prod_{i=1}^n\langle G_i-\mathbf{E} G_i\rangle=\sum_{P\in \Pi_n}\prod_{\{i,j\}\in P}\!\!\mathcal{M}_{ij}+\mathcal{O}_\theta\left(\frac{N^{\xi}}{\sqrt{N\eta_*}}\prod_{i=1}^n \frac{1}{N\eta_i} \right),\quad\mathcal{M}_{ij}:=\mathcal{M}\big((x_i,\eta_i,z_i),(x_j,\eta_j,z_j)\big),
\end{equation}
uniformly in the same sense as explained below (equation eq:Cov_UV of the paper). Here $\Pi_n$ denotes the set of all pairings of $[n]$. We use the convention that $\Pi_n=\emptyset$ if $n$ is odd. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem Taylor2 of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] (1) Assume that $\beta\in (0,1)$. We have $h'_\beta(u^{crt})=0$ where $u^{crt}=\frac{p-\beta}{1-\beta}=p-\frac{(1-p)\beta}{1-\beta}$.

(2)  Assume that $\beta\in (0,1)$. Then $h_\beta(\frac{p-\beta}{1-\beta})$ is the unique minimum of $h_\beta(x)$ on $(-\infty,p)$.

(3) Let $D$ be a convex compact set avoiding $p,1$. Then there exists a constant $K>0$ such that for any $z\in D$ and $\beta\in (0,1)$ satisfying $u^{crt}=\frac{p-\beta}{1-\beta}\in D$ we have
\begin{equation}

\left|h_\beta(u)-h_\beta(u^{crt})-\frac{(1-\beta)^3}{2\beta(1-p)^2}(u-u^{crt})^2\right|<K(u-u^{crt})^3.
\end{equation}

[Lemma 8 (Umbilic event versus uniform nonumbilicity) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Let $F\colon[0,T)\times\Sigma\to\Sph^3$ be a smooth MIWF with
$T<\infty$.  Then exactly one of the following alternatives holds:
\begin{enumerate}[label=\textup{(\roman*)}]
 \item there are $t_j\nearrow T$ and $x_j\in\Sigma$ such that
 \begin{equation}

  |A^0_{F_{t_j}}(x_j)|^2\longrightarrow0;
 \end{equation}
 \item there is $c_0>0$ such that
 \begin{equation}

  \inf_{0<t<T}\min_{x\in\Sigma}|A^0_{F_t}(x)|^2\geq c_0.
 \end{equation}
\end{enumerate}

