body:
[Lemma 63 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $U,V$ be quasi-Banach spaces and let $T\colon U\to V$ be a compact linear map and let $t\in(0,\infty)$.
    Assume that 
    \begin{equation*}
       \liminf_{k\to \infty} \bigl( k^{t} \cdot \en_k(T)\bigr) >0.
    \end{equation*}
    Then $\bigl(T(\ball_U), \norm{\cdot \mid V}\bigr)$ is totally bounded and we have $\lmd\bigl(T(\ball_U)\bigr) \ge \frac{1}{t}$.

[Lemma lem:kpz-red-derivative-identities of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Under the hypotheses of
Proposition~(thm:kpz-red-Darboux of the paper), the dressed
observable $\mathcal A=z\Phi R\Psi$ satisfies
\begin{align}
\mathcal A_a
&=\mathcal F_{1,0}-\mathcal A^2+\mathcal F_{0,1},
 \\
\mathcal A_{aa}
&=\mathcal F_{2,0}+\mathcal F_{0,2}
+2\mathcal F_{1,1}
-\mathcal F_{1,0}\mathcal A
-\mathcal A\mathcal F_{0,1}
-\mathcal A_a\mathcal A
-\mathcal A\mathcal A_a,
 \\
\mathcal A_x
&=\mathcal F_{0,2}-\mathcal F_{2,0}
+\mathcal A\mathcal F_{1,0}
-\mathcal F_{0,1}\mathcal A
+2C\mathcal A-2\mathcal A C,
 \\
\mathcal A_t
&=-\tfrac13\mathcal F_{3,0}
  -\tfrac13\mathcal F_{0,3}
  +\tfrac13(\mathcal F_{0,2}\mathcal A
  -\mathcal F_{0,1}\mathcal F_{1,0}
  +\mathcal A\mathcal F_{2,0})
\notag \\
&\quad
  +C\mathcal F_{1,0}+\mathcal F_{0,1}C
  -\mathcal A C\mathcal A
  +(\Lambda+C_a)\mathcal A
  -\mathcal A\Lambda.

\end{align}

[Corollary 32 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Fix $m\in \N$ and a measurable, non-increasing function $\Omega:\R_+\to\R_+$. Let $f_1,\dots,f_{m+1}:\R^n\to\R_+$ be measurable, even functions that satisfy
    $$\left(\prod_{i=1}^{m}f_i(a_i)\right)\cdot f_{m+1}(v) \leq \Omega^{m+1}\left(\sum_{i=1}^m\langle a_i,v\rangle_+\right) \quad \text{for all } a_1,\dots,a_m,v\in \R^n.$$ 
    Then, we have
    \begin{equation}
  \begin{split}
    &\prod_{i=1}^m\left(\int_{\R^n}f_i(x)dx\right)\Bigg(\int_{\R^n} f_{m+1}(v)^\frac{1}{m}dv\Bigg)^m
    \\
    &\leq \left(\int_{\R^n}\cdots\int_{\R^n}\Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m \langle a_i, \xi \rangle_+\right)^{m+1}\right)da_1\cdots da_m\right)\left(\int_{\R^n}\Omega\left(|v|^\frac{m+1}{m}\right)dv\right)^{m}.
\end{split}
    \end{equation}
    When $\Omega$ is log-concave and integrable over $\R_+$, there is equality when there exists $C>0$ such that $$\prod_{i=1}^mf_i(a_i) = C\cdot \Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m \langle a_i, \xi \rangle_+\right)^{m+1}\right) \text{ and }f_{m+1} = \frac{1}{C} \cdot \Omega\left( |\cdot|^{\frac{m+1}{m}}\right)^m.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_key of arXiv:2507.06522, 'Balanced multi-species spin glasses'] Assume that both $(\vc \Delta,\vc\lambda_N)$ and $(\widetilde{\vc\Delta},\vc\lambda_N)$ satisfy (equation delta_decay_finite of the paper).
For either ${\scaleobj{1.1}{\diamond}}\in\{\mathsf{Ising},\mathsf{spherical}\}$, we have
\begin{subequations} 
\begin{align}

F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)- F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N) 
&\leqslant \frac{1}{2}\Big[\xi_{N,\widetilde{\vc\Delta}}({\boldsymbol 1})-\xi_{N,\vc\Delta}({\boldsymbol 1}) \nonumber \\
&\phantom{\leqslant\frac12\Big[}+ \sup_{{\boldsymbol x}\in[-1,1]^\mathscr{S}}\big(\xi_{N,\vc\Delta}({\boldsymbol x})-\xi_{N,\widetilde{\vc\Delta}}({\boldsymbol x})\big)\Big], \\

\text{and}\quad |F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N) - F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)| &\leqslant \sup_{{\boldsymbol x}\in[-1,1]^\mathscr{S}} |\xi_{N,\vc\Delta}({\boldsymbol x})-\xi_{N,\widetilde{\vc\Delta}}({\boldsymbol x})|.
\end{align}
\end{subequations}
In the large-$N$ limit: if (equation converging_ratios of the paper)  holds, and both $(\vc\Delta,\vc\lambda)$ and $(\widetilde{\vc\Delta},\vc\lambda)$ satisfy (equation delta_decay of the paper), then
\begin{subequations} 
\begin{align}

\limsup_{N\to\infty}\big(F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)-F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N)\big)
&\leqslant\frac{1}{2}\Big[\xi_{\infty,\widetilde{\vc\Delta}}({\boldsymbol 1})-\xi_{\infty,\vc\Delta}({\boldsymbol 1}) \nonumber \\
&\phantom{\leqslant\frac12\Big[}+\sup_{{\boldsymbol x}\in[0,1]^\mathscr{S}}\big(\xi_{\infty,\vc\Delta}({\boldsymbol x})-\xi_{\infty,\widetilde{\vc\Delta}}({\boldsymbol x})\big)\Big], \\

\text{and}\quad\limsup_{N\to\infty}|F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)-F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N)|
&\leqslant\sup_{{\boldsymbol x}\in[0,1]^\mathscr{S}}|\xi_{\infty,\vc\Delta}({\boldsymbol x})-\xi_{\infty,\widetilde{\vc\Delta}}({\boldsymbol x})|.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2606.04950, 'The Tricomi equation in the hyperbolic half plane under additive space-time Gaussian White'] For any $t>0$ the stochastic process $\{U(t,x)\}_{x\in\mathbb{R}}$ is second order stationary with expectation
\begin{align*}
\mathbb{E}[U(t,x)]=0\quad\mbox{ for all }x\in\mathbb{R}
\end{align*}
and covariance
\begin{align}
\mathtt{cov}(U(t,x),U(t,y))=\frac{1}{2\pi^2}\int_0^{+\infty}\cos(\rho |x-y|)\int_0^t|C(t,s,\rho)|^2dsd\rho\quad\mbox{ for all }x,y\in\mathbb{R}.
\end{align}
Moreover, the correlation function
\begin{align*}
r_t(h):=\frac{\mathtt{cov}(U(t,x+h),U(t,x))}{\mathbb{V}[U(t,x)]},\quad t>0,x,h\in\mathbb{R},
\end{align*}
verifies
\begin{align*}
r_t(h)=1-\alpha_t|h|+o(|h|)\mbox{ as $|h|$ tends to zero},
\end{align*}
with
\begin{align*}
\alpha_t:=\frac{\pi}{2\int_0^{+\infty}\int_0^{t}\left|C(t,s,\rho)\right|^2ds d\rho}.
\end{align*}
In particular, the stochastic process $\{U(t,x)\}_{x\in\mathbb{R}}$ admits a continuous modification. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Harnack inequality) of arXiv:2604.10142, 'H\MakeLowercase{arnack inequality for} $p$\MakeLowercase{-harmonic functions: \\ improved '] Let $u$ be a positive $p$-harmonic function on $B_R(0)$ where $R>1$. Then $u$ satisfies the Harnack inequality:
        \begin{equation}
            \sup_{B_1(0)}u\leq H_R(p,d)  u(0),
        \end{equation}
        where $\displaystyle H_R(p,d) \le \exp\left( C_R \, \frac{d}{p-1}\log\frac{d}{p-1}\right)$ and $C_R$ depends only on $R$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop R_1< R_0 of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $O_n$ be the event defined in (equation definition of O_n of the paper) and $S_n$ is the random walk defined in (equation def of S_n and S_n hat of the paper). Then, for some absolute constant $C$, 
   \begin{align}
         R_n^1 = \mathbb{E}\biggl[\frac{1}{|X_0-X_2|^2|X_0-X_3|^2|S_n|^4} \mathbbm{1}_{O_n}\biggr] \leq C\mathbb{E}\biggl[\frac{1}{|(X_0-X_2)S_n|^2} \mathbbm{1}_{O_n}\biggr] = C R_{n}^0.
   \end{align}

[Lemma 25 (Krawtchouk transform functional equation) of arXiv:2609.03736, '2609.03736'] For every radial vector $u$,
\begin{equation}
 G_{\cK_nu}(z)=2^{-n/2}(1+z)^nG_u(\omega(z)).

\end{equation}
Thus, if $g\in\cE_n^\varepsilon$ with $\varepsilon\in\{-1,1\}$, then
\begin{equation}
 G_g(z)=\varepsilon2^{-n/2}(1+z)^nG_g(\omega(z)).

\end{equation}

[Proposition 10 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $\bu \in \StokesV$ and $\phi,\,\psi \in \newone{V}$. Then, the following equalities hold:  
   \begin{equation}
      (B_1(\bu,\phi),\psi)_{\newone{H}}= \duality{\tilde{B}_1(u,\phi)}{\psi}{\newone{V}}{\newonep{V}}.
    \end{equation}
Moreover, if $\bu \in \StokesV$, $\phi \in \newone{V}$, and $\psi \in \zero{H}{2}(\domO)$, then
      \begin{equation}
         (B_1(\bu,\phi),\psi)_{\newone{H}}= b_1(\bu,\phi,\psi).
      \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 18 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The probabilities ${\tilde p}_n^{\alpha,\rho}(t)$
satisfy the following  equation
\begin{equation}
	\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) \tilde p_k^{\alpha,\rho}(t) = - \Lambda \tilde p_n^{\alpha,\rho}(t) + \sum_{j=1}^{\min\{n,k\}}\lambda_j \tilde p_{n-j}^{\alpha,\rho}(t), \, n\geq0, 
\end{equation}
with the standard initial condition,
and  the corresponding probability generating function $
	\tilde{G}_{\alpha,\rho}(u, t)$, $|u| \leq 1$, solves the equation
	\begin{equation*}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right)  \tilde G_{\alpha,\rho}(u, t) = -\sum_{j=1}^{k}\lambda_j(1-u^j)\tilde G_{\alpha,\rho}(u, t), 
	\end{equation*}
	with $\tilde G_{\alpha,\rho}(u, 0) = 1$; 
  the generalized fractional derivatives in the C-D sense are defined in \eqref{exfDt}.

[Lem A.1 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] As claimed in the proof of Lemma~(lem:6.3 of the paper), 
	\begin{equation} \begin{aligned} 
	\mathbb{P}\left(\exists k \in I_\varkappa, |k| \leq \varkappa T^{2/3+\iota}: \ x_{d^{-2}T-k}(T) \leq \left(1-2\sqrt{d^{-2}-kT^{-1}}\right)T -\tfrac{d^3 k^2}{4(1+\sqrt{\alpha}d)^2} T^{-1}\right)
	\end{aligned} \end{equation} 
	can be bounded by $C e^{-c\varkappa}$ for all $T$ and $\varkappa$ large enough.

