[Lemma 5 (anisotropic Sobolev embedding) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] Let
\begin{equation}
 \sreg>\frac{n-1}{2},\qquad \preg\ge0,\qquad \sreg+\preg>\frac n2 .
\end{equation}
Then every $f\in Y^{\sreg,\preg}(\Rn)$ satisfies
\begin{equation}
 \|f\|_{L^\infty(\Rn)}
 \le
 \frac{C(n,\sreg,\preg,v_{\rm A})}
 {(\sreg+\preg-\frac n2)^{1/2}}
 \|f\|_{Y^{\sreg,\preg}} .
\end{equation}
Both strict inequalities in \eqref{eq:Y-embed-range} are necessary.

[Theorem 4 of arXiv:2604.16795, '2604.16795'] Under Assumption {\rm\ref{A0}}, for any measurable function $\phi$ on $\R^d$ satisfying
	\begin{align}
		\int_{\R^d} H_{c,c_0}(y) |\phi(y)| \,\mu(\d y) <\infty
	\end{align} with $c>0$ large enough and $c_0>0$ small enough,
	there are constants $T_0>0$ and $C_0>0$ such that all $t > T_0$,
	\begin{align}
		\|e^{\lambda_0t}P_t(\phi)-\Pi(\phi)\|_{L^{\infty}(\mu)}
		\le C_0 e^{-(\lambda_1-\lambda_0)t}.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop:chfuntheta of arXiv:2411.19192, 'Characteristic function and Esscher transform of a switching Levy model for the temperatur'] Under the probability $\mathcal{Q}^{\theta}$ defined by the Esscher transform  in equation ((eq:esscher of the paper)) and the condition $\lambda_{21} > \lambda_{12} > \theta$ the characteristic function of the temperature process is given by:
 \begin{eqnarray}
        \varphi^{\theta}_{T_t}(u)&=& \exp[iu C_1(t, \alpha)]  C_4(u, \theta)C_5(u,\theta)
 \end{eqnarray}
where:
\begin{eqnarray*}
 D(m,n,l, \theta)&=& \frac{(\lambda^{ m}_{12}-\theta)}{(\lambda^{ n}_{21}-\theta) \Gamma(l)}, \; l \geq 1 \\
C_2(u, \theta, k) &=& (\lambda_{12}-\theta)^k (\lambda_{21}-\theta)^k (J^{\theta}_1(u)J^{\theta}_2(u))^k \\
C_3(u, \theta, k) &=& p^{\theta}_{2k}(t)+ (\lambda_{12}-\theta)J^{\theta}_1(u) p^{\theta}_{2k+1}(t)\\
C_4(u, \theta) &=& \sum_{k=0}^{+\infty}  C_2(u, \theta,k) C_3(u, \theta, k)\\
C_5(u,\theta) &=& \sum_{k=0}^{+\infty}   J^{\theta}_3(u,k)  p^{\theta}_{2k}(t) +  \sum_{k=0}^{+\infty}   J^{\theta}_4(u,k)p^{\theta}_{2k+1}(t) \\
\end{eqnarray*}
\begin{equation*}
  g_j(u,s, \theta)=-iu \mu^j_1 \sigma e^{-\alpha (t-s)} +  \mu^j_1 \theta +\frac{1}{2}(-i u\sigma e^{- \alpha (t-s)}+\theta)^2
\end{equation*}

