body:
[Mydef b2.1 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] A matrix \( \mathbf{B} \in \mathbb{C}^{M \times D} \) is said to have the group restricted isometry property (group-RIP) of order \( s \) if there exists a constant \( \delta \in (0, 1) \) such that, for all $\mathbf{x} \in \Sigma_{\mathcal{S}, s}$, the following inequality holds:

	\begin{equation}
		(1-\delta)\|\mathbf{x}\|_2^2 \leq\|\mathbf{B} \mathbf{x}\|_2^2 \leq(1+\delta)\|\mathbf{x}\|_2^2 \quad \forall \mathbf{x} \in \Sigma_{\mathcal{S}, s}
	\end{equation}

The smallest constant \( \delta_s \leq \delta \) satisfying this inequality is referred to as the group restricted isometry constant (group-RIC) of $\mathbf{B}$.

[Problem 40 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] For each $x \ge 0$, show that 
\begin{equation}
\frac1{N} \sum_{j=1}^{N} 1_{\{ c_\gamma \mu_\ph(\Sigma)(\boldsymbol{\lambda}_{j+1} - \boldsymbol{\lambda}_j) \le x\} } \xrightarrow[N\to\infty]{p} F_{\emph{GOE}}(x),
\end{equation}
where $F_{\emph{GOE}} (x)$ is the GOE \emph{level-spacing distribution}. (Stated as a problem by the paper; open unless the paper says otherwise.)

[Corollary thm:complete-linear-estimates of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $\alpha\geq0$ and let $w$ be a regular weight of order $\alpha$.
Suppose that Assumption~(ass:reference-diffusion of the paper) holds and $C_w(X)<\infty$, and take
$F\in L_\alpha^2$ and $\psi\in H^1(\mu_T)$.  If $\psi$ is not
spatially constant, also assume Assumption~(ass:drift-multiplier of the paper).  Then
$u:=\mathcal U(F,\psi)=SF+v^\psi$ is the unique order-$\alpha$ occupation Sobolev solution with data
$(F,\psi)$.  Its Hessian is
\begin{equation}
 \operatorname{Hess}_gu=\mathsf T_wF+\operatorname{Hess}_gv^\psi, \qquad
 D_x^2u=D_x^2SF+D_x^2v^\psi.

\end{equation}
There exists a constant
$C=C(T,\lambda,\Lambda,M_1(a),\operatorname{osc}_\alpha(w),
C_w(X),\Lambda_b)>0$ such that, for every $\kappa\geq1$,
\begin{align}
 \left\lVert u\right\rVert_{w_\kappa}
 &\leq e^{\operatorname{osc}_\alpha(w)/2}\kappa^{-1}
       \left\lVert F\right\rVert_{w_\kappa}
       +CT^{\alpha/2}\norm\psi_{H^1(\mu_T)},\notag\\
 \left\lVert \mathsf Z u\right\rVert_{w_\kappa}
 &\leq e^{\operatorname{osc}_\alpha(w)/2}\kappa^{-1/2}
       \left\lVert F\right\rVert_{w_\kappa}
       +CT^{\alpha/2}\norm\psi_{H^1(\mu_T)},\notag\\
 \left\lVert \mathsf G u\right\rVert_{w_\kappa}
 &\leq C_{w_\kappa}(X)\left\lVert F\right\rVert_{w_\kappa}
 +\frac32\Lambda^2\lambda^{-5/2}M_1(a)
        \kappa^{-1/2}
\times e^{\operatorname{osc}_\alpha(w)/2}
        \left\lVert F\right\rVert_{w_\kappa}
 +CT^{\alpha/2}\norm\psi_{H^1(\mu_T)}.

\end{align}
The corresponding canonical estimate is
\begin{equation}
 \sum_{j=0}^2\left\lVert D_x^ju\right\rVert_\alpha
 \leq C\left(\left\lVert F\right\rVert_\alpha
       +T^{\alpha/2}\norm\psi_{H^1(\mu_T)}\right).

\end{equation}
If $\psi$ is spatially constant, $C$ may be chosen without dependence on
$\Lambda_b$.
For every $s\in(0,T)$, its composition admits a continuous version on
$[s,T]$ satisfying
\begin{equation}
 u(t,X_t)=\mathbb E_t\left[\psi(X_T)+\int_t^TF(r,X_r)\,\mathrm d r\right],
 \qquad s\leq t\leq T.

\end{equation}

[Lem le.finitealpha-s of arXiv:2411.13099, 'Long time behavior of killed Feynman-Kac semigroups with singular Schr{ö}dinger potentials'] Assume {\rm \textbf{[L1]}}. 
Then, for all $z\in \mathscr R^d_0$,  
\begin{equation}
\mathbb P_{z}[\forall t\ge 0, L_t=0 \text{ or } L_{t^-}=0]=0.
\end{equation}
In addition, for all $x\in \mathscr R^d_0$ and $t\ge 0$,  $\mathbb P_x[ L_{[0,t]} \in \mathcal D([0,t],\mathscr R^d_0)]=1$, and,  if   {\rm\textbf{[S1]}} or {\rm\textbf{[S2]}} holds,    $ \int_0^t  \mathbf V_{\mathbf S}(L_s(x))ds$ is  a.s.  finite.

