[Lemma lemma-bound-spin-correlations of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a constant $C>0$ such that for any $k \geq 1$ and any $x_1, \dots , x_k \in D_{\delta}$, 
\begin{equation*}
    \mu_{\delta}^{+}[\prod_{j=1}^{k}\sigma_{x_j}] \leq C^k\delta^{\frac{k}{8}}\exp\bigg( \frac{1}{8}\sum_{j=1}^{k} \log \frac{1}{L(x_j) \wedge {\operatorname{dist}}(x_j, \partial D_{\delta})} \bigg)
\end{equation*}
where for each $j$, $L(x_j) = \frac{1}{2}\min_{p:p \neq j} \vert x_p - x_j \vert$. Above, for $x \in D_{\delta}$, $d_{\delta}(x):={\operatorname{dist}}(x, \partial D_{\delta})$ is the Euclidean distance between $x$ and $\partial D_{\delta}$. Besides, by convention, for $k=1$, $L(x)=\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:extremal_length of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] {lawler2008conformally}}]

		For $L>0$ we set $R_L \defeq(0,L) \times (0,\pi)$ and let $\partial_1 = [0,\ri\pi]$ and $\partial_2 = \partial_{2,L} = [L,L+\ri\pi]$.  Let $\tau = \tau_{R_L}$ denote the first time that a complex Brownian motion exits $R_L$ and set
		\begin{align*}
			&f_1(z) = f_{1,L}(z) = 2 \min\{\BP_z[B_{\tau} \in \partial_1] ,  \BP_z[B_{\tau} \in \partial_2]\}
		\end{align*}
		and set $\Theta(R_L ; \partial_1 , \partial_2) = \sup\{ f_1(z) : z \in R_L\}$, which we abbreviate to $\Theta(L)$.  Then $\Theta(L)$ is a continuous, strictly decreasing function of $L$ such that 
		\begin{align*}
			\Theta(L) = \left(\frac{8}{\pi}\right) e^{-L/2} + O(e^{-L}) \quad \text{as} \quad L \to \infty.
		\end{align*}
		Moreover the supremum in the definition of $\Theta$ is attained when $z$ is the center $(\frac{L}{2}) + \ri (\frac{\pi}{2})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition lem:955 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] For any $K>0$, there exist constants $q=q(k,K,u_1)<1$ and $n_5(k,K,u_1)>0$, such that for all $n>n_5$, we have
\begin{equation}
    \mathbb{P}_{\vec{x}}\Big(\mathscr{T}\subseteq\{X_l^s:l=0,\ldots,[Kn^2],s=1,\ldots,k\}\Big)<q^{c_3n^2}.
\end{equation}

