[Theorem 2 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Fix $T>0.$ Let $X$ be a random variable whose density $f : \N \rightarrow (0, \infty) $ with respect to $\pi_{T}$ is ultra log-concave, then we have
    \begin{displaymath}
        \delta_{\mathrm{Thinn}}(f) \ge a(1-a) \frac{T^{2}}{2} \Theta_{\frac{f(0)}{f(1)}} \Bigg( \frac{\E X}{T} \Bigg)
    \end{displaymath}
    where, for $c>0,$ we denote
    \begin{displaymath}
        \Theta_{c}(z):= \frac{z^{2}}{1+cz} \log \Big( \frac{1}{1+cz} \Big) - \frac{z^{2}}{1+cz} + z^{2}= z^{2} \phi \Bigg( \frac{1}{1 + cz} \Bigg), \quad z\ge 0.
    \end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem8 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] There exist a positive number $R_0$ and a random variable $R_1(\omega)$ depending on the initial data, $\varepsilon_0$, $\nu$, $f$ and universal constants, such that: For every $E >0 $, there exists $t(\omega,E) \leq -1$, such that for all $x_0=(u_0,\rho_0,\sigma_0) \in {H^1}$ with $|x_0| < E$, and for any $t_0 < t(\omega,E)$, we have
		\begin{align}
			\|\sigma(t,\omega,t_0,\sigma_0)\|_{L^2} \leq R_0,~for~all~t \in [-1,0],
		\end{align}
		\begin{align}
			\|\rho(t,\omega,t_0,\rho_0)\|_{L^2} \leq R_0,~for~all~t \in [-1,0],
		\end{align}
		\begin{align}
			\|v^\varepsilon(t,\omega,t_0,z(t_0,\omega)u_0)\|_{L^2} \leq  R_1(\omega),~for~all~t \in [-1,0].
		\end{align}
		Therefore, $B(0,2R_0+R_1(\omega))$ is a random absorbing set in H.
		\begin{proof}
			By Lemma (lem5 of the paper), for all $t \in [-1,0]$ and $t_0 \leq 1$, we get 
			\begin{align*}
				\|\sigma\|_{L^2}^{2}\ + \|\rho\|_{L^2}^{2}\ \leq (\|\sigma(t_0)\|_{L^2}^{2}\ + \|\rho(t_0)\|_{L^2}^{2}\ )e^{2D(t_0+1)} \leq 2{E^2}e^{2D(t_0+1)}.
			\end{align*}
			Choose $t_1$$(E)$ $\leq  -1$ such that 
			\begin{align*}
				2{E^2}e^{2D(t_1+1)} \leq {R_0}^2,
			\end{align*}
			provided $t_0 \leq t_1(E)$, which proves (equation d7 of the paper) and (equation d8 of the paper).\newline
			We see from Lemma (lem7 of the paper) that 
			\begin{align}
				\|v^\varepsilon(t)\|_{L^2}^{2}\ \leq {e}^{-\nu t}[	{z}^{2}(t_0,\omega)	\|u_0\|_{L^2}^{2}\ {e}^{\nu t_0} +\frac{2}{\nu}\int_{t_{0}}^{t} {z^{2}(s,w)}(\|\rho(s) \|_{L^2}^{3}\|\nabla \rho(s) \|_{L^2}+\|f\|_{L^2}^2) {e}^{\nu s}ds],
			\end{align}
			for all $t \in [-1,0]$ and $t_0 \leq -1$. 
			Then by (equation l1 of the paper), we notice that
			\begin{align*}
				{z}^{2}(t_0,\omega)e^{\nu t_0} \to 0,~ t \to -\infty, 
			\end{align*}
			which implies that there exists $t_2(\omega,E) \leq -1$ such that if $t_0 \leq  t_2$,
			\begin{align*}
				{z}^{2}(t_0,\omega)	\|u_0\|_{L^2}^{2}\ {e}^{\nu t_0} \leq E^2{z}^{2}(t_0,\omega) {e}^{\nu t_0} \leq 1.
			\end{align*}
			Then, we estimate the integrals on the right hand of (equation d10 of the paper). \newline
			Let 
			\begin{align*}
				I&=\int_{t_{0}}^{t} {z(s,w)}^{2}\|\rho(s) \|_{L^2}^{3}\|\nabla \rho(s) \|_{L^2} {e}^{\nu s}ds\\ 
				&=(\int_{\frac{t_0}{2}}^{t} + \int_{t_0}^{\frac{t_0}{2}}) [{z^{2}(s,w)}\|\rho(s) \|_{L^2}^{3}\|\nabla \rho(s) \|_{L^2} {e}^{\nu s}]ds \\
				&=I_1+I_2.
			\end{align*}
			To estimate $I_1$, if $\frac{t_0}{2} \textless s \textless t$, then
			\begin{align*}
				\|\rho(s)\|_{L^2} \leq R_0,
			\end{align*}
			provided $t_0$ $\leq$ $t_3(E)$ for some chosen $t_3(E)$ $\leq -1$. \newline
			We see from Lemma (lem6 of the paper) that 
			\begin{align*}
				\|\nabla \rho (t)\|_{L^2}^2+\|\nabla \sigma (t)\|_{L^2}^2 \leq  Ae^{-a(t-t_0) }.
			\end{align*}
			If $\frac{t_0}{2}< s < t$, then
			\begin{align*}
				\|\nabla \rho (s)\|_{L^2}^2 \leq A,
			\end{align*}
			$A$ is given in lemma (lem6 of the paper), provided $t_0$ $\leq$ $t_3(E)$ for some chosen $t_3(E)$ $\leq -1$. \newline			 
			For $t_0 \leq t_3(E)$, $t \in  [-1,0]$,
			\begin{align*}
				I_1 \leq \sqrt A{R_0}^3\int_{-\infty}^{0} {z}^{2}(s,w) {e}^{\nu s} ds = r_1(\omega),
			\end{align*}
			$r_1(\omega)$ is a random variable being independent of $E$. Since $\frac{w(t)}{t}$ $\to 0$ as $t \to$ $\pm$ $\infty$, the ergodic property implies that $s \mapsto$ ${z}^{2}(s,w) {e}^{\nu s}$ is pathwise integrable on $(-\infty,0]$.\newline
			To estimate $I_2$, we choose $t_4(E) \leq -1$ such that 
			\begin{align*}
				8\sqrt A E^3e^{\frac{\nu}{2}t_4} \leq 1.
			\end{align*}
			By Lemma (lem5 of the paper), we deduce
			\begin{equation*}
				\|\rho(s)\|_{L^2}\ \leq 2E, 
			\end{equation*}
			for all s $\in [t_0,\frac{t_0}{2}]$. If $\frac{t_0}{2} \leq t_4(E)$, then we derive
			\begin{align*}
