 egin{equation}
\sn:=\Big\{ x \in V_ g \: : \: \sum_{y\in V_ g:\: xy\in E_ g}
_{xy}	extup{ is odd}\Big\}.
\end{equation}
We also define, for every $ eta\geq 0$ and $\mathsf{h}\in (\mathbb R^+)^V$, 
 egin{equation}
w_{ eta,\mathsf{h}}^G(
):=\prod_{\substack{xy\in E}}\dfrac{ eta^{
_{xy}}}{
_{xy}!}\prod_{x\in V} rac{\mathsf{h}_x^{
_{x g}}}{
