[Theorem WP_H^2 of arXiv:2606.00325, 'Ergodicity for a class of stochastic Hasegawa-Mima equations with dissipation'] Assume that $A$ satisfies (ass2 of the paper), $v\in C^\infty_c(\mathcal{D})$ and the noise coefficients $(f_k)_{k=1}^M \subset L^2(\mathcal{D})$. Then for every $\phi_0 \in H^2 \cap V$ let $\phi_t$ be the unique solution of (eq:main of the paper) in the sense of (def-sol-H1 of the paper). Then the process $\xi = \phi -\Delta \phi - v$ belongs to $C(0, T; L^2) \cap L^2(0, T; Y) $ almost surely and it verifies, for every $\psi \in Y$
    \begin{align}
        \left\langle\xi_t, \psi\right\rangle - \left\langle\xi_0, \psi\right\rangle = -\int_0^t \brak{B^{1/2 }\xi_s, B^{1/2} \psi}ds + \int_0^t\left\langle \xi_s, \nabla^\perp \phi \cdot \nabla \psi\right\rangleds + \int_0^t \left\langle\xi_s , dW_t\right\rangle.
    \end{align}
    Moreover it satisfies the following energy balance
    \begin{align}
    \mathbb{E}[|\xi(t)|^2] - \mathbb{E}[|\xi_0|^2]
     +2\int_0^t\mathbb{E}\left[\|\xi\|_{Y}^2\right]dt = 2 \int_0^t\mathbb{E}\left[\brak{B^{1/2} \xi, B^{1/2} v} \right]dt+ \sigma t,
\end{align}
    where $\sigma = \sum_{k=1}^M \sigma_k^2|f_j|^2$. Moreover, $\xi$ is a Markov process in $L^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 79 of arXiv:2601.16377, '2601.16377'] Suppose Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic} and \ref{Assumptions_offcrit} hold. For any $\zeta_2 \in \big(0,\frac{\mathfrak{b} - \mathfrak{a}}{2}\big)$, there exist $c>0$ depending only on the constants in the assumptions, and $\zeta_1 \in (0,\zeta_2)$ (which may depend on all the data) such that
\begin{equation}
 \sup_{x\in [\mathfrak{a}+\zeta_2, \mathfrak{b}]} \big(V^{\textnormal{eff}}_h(x) -
V^{\textnormal{eff}}_h(\mathfrak{a}+\zeta_1)\big) \leq c
\end{equation}
and
\begin{equation}
 V^{\textnormal{eff}}_h(\mathfrak{a}+\zeta_1)=\sup_{x\in [\mathfrak{a}+\zeta_1,\mathfrak{b}]}
V^{\textnormal{eff}}_h(x).
\end{equation}
Moreover, there exist $\zeta_1^\pm$ depending only on $\zeta_2$ and the constants in the
assumptions such that the choice of $\zeta_1$ can be made to obey $0<\zeta_1^-<\zeta_1<\zeta_1^+<\zeta_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition MAL of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let $\Phi: [s,t]\rightarrow \mathbb{R}^d$ be a stochastic process such that $\phi\in\mathcal{H}^d$ and
			\begin{align*}
				\mathbb{E} (\Vert \Phi\Vert_{\vert\mathcal{H}^d\vert}^2)+
				\sum_{1\leq i\leq d}\int_{s}^{t}\mathbb{E}(\Vert D^{B}\Phi^{i}(r)\Vert_{\vert\mathcal{H}^d\vert}^2) \mathrm{d}r<\infty .
			\end{align*}
			Assume that \( \text{Tr}_{[s,t]} D^B \Phi =\sum_{{1\leq i\leq d}} \text{Tr}_{[s,t]}D^{B^i}\Phi^{i}\) exists, where
			\begin{align}
				\text{Tr}_{[s,t]} D^{B^j} \Phi^i := \lim_{\epsilon \rightarrow 0} \int_{s}^{t} \frac{\langle D^{B^j} \Phi^i(x), \chi_{[x-\epsilon, x+\epsilon] \cap [s,t]} \rangle_{\mathcal{H}}}{2\epsilon} \, \mathrm{d}x,
			\end{align}
			where \( e_k \) denotes the usual unit vector in \(\mathbb{R}^d\).
			Then the symmetric integral is well-defined and
			\begin{align*}
				\int_{s}^{t}\Phi(x)\mathrm{d}^{\circ}B_{x}=\delta^{B}(\Phi)+Tr_{[s,t]} D^{B}\Phi .
			\end{align*}

[Lemma 24 of arXiv:2510.24244, 'Statistical properties of Markov shifts: part II-LLT'] For every $0<\delta<T$ and $L\in\bbN$ there exists $0<\delta(L)<1/2$ such that if
\begin{equation}

\varepsilon\leq \delta(L) 
\end{equation}
then  for every $j$ and $\ell\leq L+1$ we have the following.
If  for some nonzero real $t$ such that $\del \leq |t|\leq T$ there exists $h$ with 
$\|h\|_{\om,*}\leq 1$ and
\begin{equation}

\inf_{x}|\cL_{j,t}^{\ell}h(x)|\geq 1-\varepsilon 
\end{equation}
then
\begin{equation}
f_{j+\ell-1}=g_{j,t,\ell}+H_{j+\ell-1}-H_{j+\ell}\circ T_{j+\ell-1}+(2\pi/t) Z_{t,j,\ell}
\end{equation}
where $Z_{t,j,\ell}$ is integer valued, and for every $0<r<1$ we have 
$\sup_{t,j,\ell}\|g_{t,j,\ell}\|_{j+\ell,\om^r}\leq c_r(\ell)$ where $c_r(\ell)\to 0$ as $\ell\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Fix $0<\kappa \le \kappa_0$ for $\kappa_0$ sufficiently\footnote{For example, $\kappa_0 = 1/100$ would do} small. We write $\mfT$ for the regularity structure generated by the noise types $\mathfrak{L}_- = \{\<b0>, \<p0>, \<0t>\}$ and kernel types $\mfL_+ = \{\<k>, \<bk>, \<pk>\}$ where the rule (in the sense of \cite[Definition 5.7]{BHZ}) is the one naturally associated to the system \eqref{eq:main_sys}. In particular, each $\mathcal{I}_{\diamond}$ for $\diamond \in \mfL_+$ is a degree $2$ integration operator and
\begin{equ}
	|\<b0>|_\fs = |\<p0>|_\fs = - 3/2 - \kappa, \qquad |\<0t>|_\fs = - 2- \kappa.
\end{equ}
Further, we write $\mcT$ for the canonical basis of the model space of $\mfT$, which is therefore henceforth denoted by $\scal{\mcT}$.

[Proposition L-G Trans of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Given the differential equation (equation W-equa1tr of the paper), let $I_1=(a_1,b_1)$, $I_2=(a_2,b_2)$ be two intervals containing exactly one turning point of $f$, say, $z_1\in I_1$ and $z_2\in I_2$. Define $\zeta$ by
\begin{equation}
\left\{
\begin{array}{ll}
  \frac{2}{3}\zeta^{\frac{3}{2}}(z)= \int_{z}^{z_1}f^{\frac{1}{2}}(t)dt,~z\le z_1\\\\
  \frac{2}{3}(-\zeta)^\frac{3}{2}(z)=\int_{z_1}^z(-f)^\frac{1}{2}(t)dt,~z>z_1
\end{array}
 \right. 
\end{equation}
on $I_1$, and similarly,
\begin{equation}
\left\{
\begin{array}{ll}
  \frac{2}{3}\zeta^{\frac{3}{2}}(z)= \int_{z_2}^{z}f^{\frac{1}{2}}(t)dt,~z>z_2\\\\
  \frac{2}{3}(-\zeta)^\frac{3}{2}(z)=\int_{z}^{z_2}(-f)^\frac{1}{2}(t)dt,~z\le z_2
\end{array}
 \right. 
\end{equation}
on $I_2$. Then for any $z\in I_j$ where $j\in\{1,2\}$, $\zeta':=\frac{d\zeta}{dz}$ is positive when $z>z_j$ and negative when $z<z_j$. Moreover, for any $z\in I_j$, define $W:=(\zeta')^{\frac{1}{2}}w$ when $z>z_j$ and $W:=(-\zeta')^\frac{1}{2}w$ when $z\le z_j$. Further define $\tilde{f}:=\frac{f}{\zeta}$, which equals $(\zeta')^2$. Then the previous equation (equation W-equa1tr of the paper) can be expressed as:
\begin{equation}
    \frac{d^2W(\zeta)}{d\zeta^2}=\left(\kappa_N^2\zeta+\Psi(\zeta)\right)W(\zeta)
\end{equation}
where
\begin{equation*}
  \Psi(\zeta)=\tilde{f}^{-\frac{1}{4}}\frac{d^2}{d\zeta^2}\left(\tilde{f}^{\frac{1}{4}}\right)+\frac{g}{\tilde{f}}.
\end{equation*}
This $\zeta$ is called the \textbf{Liouville--Green~transformation} of $f$.

