body:
[Prop 40 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p=p(x,\xi)$ be of the form
    \begin{equation}
        p(x,\xi)=\sum_{k\in \Lambda}p_k(x)e^{2i\pi \ps{k}{\xi}}, \quad(x,\xi)\in [0,1]^d\times \T^d,
    \end{equation}
    where $\Lambda=\prod_{j=1}^d\disc{-n_j}{m_j}$, $n_j,m_j\geq 0$, and $p_k:[0,1]^d\to \C$, $k\in \Lambda$ is measurable. Let us denote 
    \begin{equation*}
        S:=\sum_{j=1}^d (n_j+m_j)>0\mm\m\m\text{and}\mm\m\m \Xi:=\prod_{j=1}^d(n_j+m_j+1).
    \end{equation*}
    We assume that: there exists $m>0$ such that for almost every $x\in [0,1]^d$, 
    \begin{equation}
        \sum_{\substack{k\in \Lambda\\k\neq 0}}^{N_+}\bb{p_k(x)}\geq m>0.
    \end{equation}
    Then, for all $z\in \C$, $t\geq 0$, 
    \begin{equation}
        \mathrm{L}\pr{\acc{(x,\xi)\in [0,1]^d\times \T^d\m;\m \bb{p(x,\xi)-z}^2\leq t}}\leq Ct^\kappa
    \end{equation}
    where
    \begin{equation}
        \kappa=\frac{1}{2S}\mm\text{and}\mm C= 14d\pr{\frac{\sqrt{\Xi}}{m}}^{\frac{1}{S}}.
    \end{equation}

