[Cor lem:simplyconnleaves of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{F}$ be a cooriented $C^0$-foliation on $M$ transverse to $\partial M$ (if nonempty). If $\Lambda$ is a minimal set of $\mathcal{F}$ consisting of simply connected leaves, then one of the cases in the following table holds:

\begin{center}
\begin{tblr}{
  colspec = {|Q[c,m]|Q[l,m,wd=6cm]|Q[l,m,wd=6.5cm]|},
  row{1} = {bg=gray!20},
  column{1} = {bg=gray!20},
  vlines,
  hlines,
}
  & \centering $\Lambda$ is a compact leaf& \centering $\Lambda$ is not a compact leaf \\
  $\partial M = \varnothing$ & $\Lambda \cong S^2$, and $\mathcal{F}$ is conjugate to the standard foliation by spheres on $S^1 \times S^2$. & $\Lambda$ is a $\mathbb{T}^3$-type planar minimal set, and $\mathcal{F}$ is semi-conjugate to an irrational foliation on $\mathbb{T}^3$.\\
  $\partial M \neq \varnothing$ & $\Lambda \cong D^2$, and $\mathcal{F}$ is conjugate to the standard foliation by disks on $S^1 \times D^2$. & $\Lambda$ is a $\mathbb{T}^2$-type planar minimal set, and $\mathcal{F}$ is semi-conjugate to an irrational foliation on $\mathbb{T}^2 \times I$.\\
\end{tblr}
\end{center}

[Corollary cor:SRBM_d3 of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Let $(\zeta_{\lfloor t\rfloor})_{t\ge 0}$ denote the continuous-time SBBS with $d=3$, capacity $c\ge 3$, and  error probability $\varepsilon\in (0,1)$. As $n\rightarrow\infty$, 
			\begin{align}
			(n^{-1/2}(\zeta_{\lfloor \frac{nt}{1-\varepsilon} \rfloor}-nt \mathbf{1}_{3})\,: \, t\ge 0 ) \Rightarrow \mathcal{W} \quad \text{as $n \to \infty$},
			\end{align}
			where $\mathcal{W}$ is an SRBM associated with data $(S, \mathbf{0}, \varepsilon I_{3}, \hat{R}, \delta_{\mathbf{0}})$ with $S = \{x \in \mathbb{R}^3: x_1 \le x_2 \le x_{3} \}$  the 3-dimensional Weyl chamber, 
            \begin{align}
                \hat{R}_{\varepsilon} = \frac{1}{1-\varepsilon}[R_{1},R_{2}]=
                \begin{bmatrix}
                   1-\varepsilon & 0 \\
                   1 & 1-\varepsilon \\
                   0 & 1 
                \end{bmatrix}
                .
            \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 17 (Endpoint branch is dominated for $a \ge 1$) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $a \ge 1$ and $p \in (0, \bar p(a))$. Then
\begin{align*}
    (1-p)\,\nu_{\max}(p,a) < a\left(1 + \log\frac{1}{2p}\right),
    \qquad\text{that is}\qquad
    R(p,a) < a.
\end{align*}

