[Proposition prop cv explo unif of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] For all $y \in \BQ^2$, let $C^{\kappa_n}_t(y)$ be the connected component of $\BD \setminus \SCB^{\kappa_n, \partial}_{\ka_{\kappa_n}t}(\partial \BD)$ containing $y$ when it exists and the empty set otherwise (these components are simply connected, $\SCB^{\kappa_n, \partial}_{\ka_{\kappa_n}t}(\partial \BD)$ being a connected closed subset of $\overline{\BD}$ containing $\partial \BD$). Then, jointly with the convergence~(equation eq cv subsequence of the paper), we have
	\begin{equation}
        (C^{\kappa_n}_t(y))_{t \in \BQ_{\ge 0}, y \in \BQ^2}
        \mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		(C_t(y))_{t \in \BQ_{\ge 0}, y \in \BQ^2}
	\end{equation}
	for the product topology where the space of simply connected domains containing $y$ is equipped with the Carath\'eodory topology viewed from $y$, to which we adjoin $\emptyset$ as the limit of domains whose conformal radius seen from $y$ tends to $0$, 
	where ${C_t(y)}$ is the connected component of $\BD \setminus \SCB_t^\partial(\partial \BD)$ containing $y$, and where $(\SCB_t^\partial(\partial \BD))_{t\ge 0}$ is the explored region at time $t$ in the uniform exploration of the $\CLE_4$ (denoted $\SCB_t(\partial \BD)$ in~(subsec:labeled_cle_4 of the paper)) (where the time parametrization is that of the PPP of SLE bubbles). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma6 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and  let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, we have the following:
\begin{enumerate}[label=(\textbf{\roman*})]
\item  For every $t \in \mathbb{R}$, $\chi^{(\varphi, h)}(t) \in L^{2}(\Omega, \mathcal{F}, \mathbb{P})$. 
\setcounter{Cond3}{\value{enumi}}
\end{enumerate}

\noindent Assume further that (C4 of the paper)-(C5 of the paper) holds. Then, we also have the following:
\begin{enumerate}[label=(\textbf{\roman*})]
\setcounter{enumi}{\value{Cond3}}
\item $\chi^{(\varphi,h)}$ almost surely has c\`adl\`ag paths. 

\item $\chi^{(\varphi,h)}$  satisfies (C1 of the paper)-(C3 of the paper).  

\item  Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$ and recall that $\mathcal{I}_{n} = \{u_{1}, \dots, u_{n}\}$, for $n \in \mathbb{N}$. For $n \in \mathbb{N}$ and $t \in \mathbb{R}$, define
\begin{align} 
Y_{n}^{\varphi}(t) \coloneqq \sum_{u \in \mathcal{I}_{n}} \chi^{(\varphi,h)}_{u}(t-S(u)) = \sum_{i=1}^{n} \chi^{(\varphi,h)}_{u_{i}}(t-S(u_{i})). 
\end{align}
\noindent Then, for every $t \in \mathbb{R}$, as $n \rightarrow \infty$, $Y_{n}^{\varphi}(t) \rightarrow  \mathcal{Z}_{t}^{\chi^{(\varphi,h)}}$, in $L^{1}(\Omega, \mathcal{F}, \mathbb{P})$.

\item For every $t \in \mathbb{R}$,  $\mathbb{E}[\mathcal{Z}_{t}^{(\chi^{(\varphi,h)})^{2}}] < \infty$.

\item For all $t \in \mathbb{R}$ and any admissible order $(u_{n})_{n \in \mathbb{N}}$ of $\mathcal{I}$, as $n \rightarrow \infty$, 
\begin{align} 
\sum_{i=n+1}^{\infty} (\chi^{(\varphi,h)}_{u_{i}}(t-S(u_{i})))^{2} \rightarrow 0, \quad \text{in} \quad L^{1}(\Omega, \mathcal{F}, \mathbb{P}).
\end{align}

\item For $t \in \mathbb{R}$, 
\begin{align} 
\mathcal{Z}_{t}^{\varphi - \mathbb{E}[\varphi]} \stackrel{a.s.}{=} \mathcal{Z}_{t}^{\chi^{(\varphi,h)}} +  \sum_{0 \leq |u| \leq h-1}  ( \varphi_{u}^{(h-|u|)}(t-S(u)) - \varphi_{u}^{(0)}(t-S(u))).
\end{align}
\noindent (If $h=0$, the sum  $\sum_{0 \leq |u| \leq h-1}$ on the right-hand side of (equation eq82 of the paper) is defined to be $0$.) 
\end{enumerate}

[Proposition of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] $\mathsf{acc}$ is strictly proper iff there is a convex function $\varphi$ (with values $\mathsf{acc}_v(v)$) where:
	\begin{align}\mathsf{acc}_v(x):=\mathsf{acc}_v(v)-\br{\varphi(v)-\varphi(x)-(v-x)\varphi'(x)}
	\end{align}
	That is, the error-score is:
	\begin{align}\mathfrak{s}_v(x)=\varphi(v)-\varphi(x)-(v-x)\varphi'(x)
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumption~\ref{assump-particles} hold.
For $k$ as in Assumption~\ref{assump-particles}\ref{hyp:F0Nk} and for any cut-off $A>0$ from \eqref{def:cutoff}, there exists $C = C(T,A,k,d)>0$ such that

\begin{equation}
\sup_{N\in \N^*}  e^{-C T \sigma_{N}^{-2}} \bigg(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} F_{t}^{N} \big\|_{L^{2}_{x,v}}^{2q}
+ \sigma_N^{2q}\, \E \bigg[ \Big(\int_{0}^T \big\lVert \langle v \rangle^k \nabla_{v} F^N_{s}\big\rVert_{L^{2}_{x,v}}^{2} \dd s\Big)^q\bigg] \bigg)^{1/q}<\infty.
\end{equation}

