body:
[Thm 25 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\eta<1/4$ and $\varrho\in \hspace{0.1cm} ]0,1]$. Let $p$ as in \eqref{Developpement en série de Fourier par rapport à xi} and $q:=\bb{p}^2$. Let $\widetilde{p}$ be as in \eqref{Definition de p tilde}, $\mathscr{U}_p$ be given in \eqref{Ensemble des singularités} and $\widetilde{q}$ be as in \eqref{Dvpt de Borel pour le théorème central}. We assume that there exist ${\kappa_2}\in \hspace{0.1cm} ]0,1]$ such that, for $0\leq t\ll 1$,
    \begin{equation}
        \mathscr{V}(t):=\mathrm{Vol}\pr{\acc{\rho\in \T^{2d}\m|\m q(\rho)\leq t}}=\mc{O}(t^{\kappa_2})

    \end{equation}
    and ${\kappa_1}\in \hspace{0.1cm} ]0,1]$ such that for $0\leq t\ll 1$,
    \begin{equation}
        \mathrm{L}\Bigl(\pr{\mathscr{U}_p+B(0,t)}\cap[0,1]^d\Bigl)=\mc{O}(t^{{\kappa_1}}).

    \end{equation}
    Let $\alpha$ be such that
    \begin{equation}
        N^{-\eta\min(\varrho,{\kappa_1})}\ll\alpha\ll 1.
    \end{equation}
    Then, for all $\psi\in \mathscr{C}^\infty_c(\R)$,
    \begin{equation}
       \mathrm{tr}\!\croch{\psi\pr{\frac{\widetilde{q}_{N}}{\alpha}}} =N^d\pr{\int_{\T^{2d}}\psi\pr{\frac{q(\rho)}{\alpha}}d\rho+\mc{O}\pr{N^{-\eta{\kappa_1}}}+\mc{O}\pr{N^{-\varrho \eta}\alpha^{-1}}}.

    \end{equation}
    If $\chi\in \mathscr{C}^\infty_c(\R,[0,+\infty[)$, such that $\chi(0)>0$ then,
    \begin{equation}
        \begin{split}
            \log\det\pr{\widetilde{q}_N+\alpha\chi\pr{\frac{\widetilde{q}_N}{\alpha}}} &= N^d\biggl(\int_{\T^{2d}}\log(q(\rho))d\rho+\mc{O}\pr{N^{-\eta{\kappa_1}}\bb{\log(\alpha)}}\\
            &\mm\mm+\mc{O}\pr{\alpha^{\kappa_2}\bb{\log(\alpha)}}+\mc{O}\pr{N^{-\varrho\eta}\alpha^{-1}}\biggl).
        \end{split}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:grid-norm-recursion-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Let \(q\in(1,2)\) and assume \(\rho(q)<1\).  Fix \(\alpha>1\).  Then there
exists \(C_{q,\alpha}<\infty\) such that, for all integers
\(0<m\le k\le n\),
\begin{equation}
    A_{k,n}
    \le
    C_{q,\alpha} r_n^{q/2}\rho(q)^m A_{k-m,n}
    +
    C_{q,\alpha}2^{-q(k-m)}.
\end{equation}

[Theorem 1 of arXiv:2608.28410, 'Mean curvatures and symmetry\\of convex hypersurfaces'] Let $M\subset\R^{n+1}$ be a $\C^2$ hypersurface bounding a convex body $K$, and $e\in\S^n$ be a direction. Suppose that, for some $1\leq m\leq n$,
\begin{equation}
\sigma_m(p)\leq\sigma_m(q)
\end{equation}
whenever $p-q=\lambda e$, for some $\lambda\geq 0$, and the open
segment joining $p$ and $q$ lies in the interior of $K$. Then $M$ is symmetric with respect to a hyperplane orthogonal to $e$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 of arXiv:2605.05430, 'Dirichlet problems and exit distributions for the telegraph process and its planar extensi'] For $x\in[a,b]$, it holds that
\begin{equation}h_0(x)=\frac{\lambda}{c^2}\,(b-x)(x-a)+\frac{b-x}{c}\end{equation}
and
\begin{equation}h_1(x)=\frac{\lambda}{c^2}\,(b-x)(x-a)+\frac{x-a}{c}\end{equation}
Consequently, \begin{equation}h(x)=\frac{\lambda}{c^2}\,(b-x)(x-a)+\frac{b-a}{2c}.\end{equation}

[Theorem Theorem~2 in \cite{HebischSikora1990} of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\mathbb G$ be any homogeneous Carnot group equipped with the  dilations $(\delta_\lambda)_{\lambda>0}$. Then there exists $\varepsilon_0>0$ such that for every $0<\kappa<\varepsilon_0$, 
    \begin{align*}
        \rho(x):=\inf\{t>0: |\delta_{1/t} x|<\kappa \}
    \end{align*}
    defines a symmetric homogeneous norm on $\mathbb G$. In particular, the unit metric ball $\{x\in\mathbb G: \rho(x)<1\}$ coincides with the Euclidean ball $B_{\mathbb{R}^n}(0,\kappa)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor cor1:sig:gam of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:derv:liningam of the paper)}  hold, then for   $ 2\leq p_0\leq \min\{{\bar p}/((\eta+1)
  (\eta/8+1)),\bar p/2\}$
		\begin{align*}
			\sum_{\mathfrak q=1}^{2}E\big|(\widehat\sigma_{\mathfrak{q}})_{tam}^{\displaystyle{n}}\big(\kappa_n(s),s,x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)\big|^{p_0} 
			+ \sum_{\mathfrak q=1}^{2}\int_Z E\big|(\widehat\gamma_{\mathfrak{q}})_{tam}^{\displaystyle{n}}\big(\kappa_n(s),s,x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)},\bar z\big)\big|^{p_0}\nu(d\bar z)
			\leq &  
			Kn^{-1}
		\end{align*}
  for any   $s\in[0,T]$ and $i\in\{1,\ldots,N\}$   where $K>0$ is independent of $N$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 20 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] For $\kappa>0$, we let $\mathcal G_{\kappa}$ be the set of probability measures $\Ups$ on $\mathbb R$ which are absolutely continuous with respect to 
 Lebesgue measure with density $\dd \Ups(x) \, = \, \varrho(x) \dd x$ such that

\begin{enumerate}

\item $\Ups$ is compactly supported with bounded density, $\varrho \in L^{\infty}(\R)$;

\item $\Int{\mathbb{R}}{} \ln(1+|x|)^4 \, \varrho(x)\, \mathrm{d}x  < +\infty$;

\item $1+ \frac{2}{\ell} \Int{\mathbb{R}}{} \ln |x-y| \, \varrho(y) \, \mathrm{d}y \geq \kappa$ for all $x\in \mathbb R$. 

\end{enumerate}

[Proposition 4 of arXiv:2605.16733, 'Concentration Inequalities for Sample Cross-Covariances'] Let \((X_i,Y_i)_{i=1}^N\) be i.i.d. copies of a centered Gaussian random
vector $(X,Y) \in \R^{d_X+d_Y}$.
Then
\begin{align*}
\E \bigg\|\frac{1}{N}\sum_{i=1}^{N} X_i Y^{\top}_i-\E XY^{\top}\bigg\| \gtrsim (\|\Sigma_{X}\|\|\Sigma_Y\|)^{1/2} \bigg(\sqrt{\frac{r_{X}+r_{Y}}{N}}+ \frac{\sqrt{r_{X}r_{Y}}}{N}\bigg).
\end{align*}

[Lemma 1 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] The operator-valued increment $a$ from \eqref{eq:a-def} satisfies
\begin{equation*}

(\delta a)_{tus}=a_{tu}a_{us},
\qquad 0\le s\le u\le t\le T.
\end{equation*}

