[Theorem 3 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For every fixed $k\in {\mathbb Z}$, as $n\to\infty$,
\begin{align}
{\mathbb P}[M_n-b_n\leq k]&=\int_{-\infty}^\infty p_\ell(e^{-s}) e^{-s} \exp\left(- e^{(e-1)s+c_n-k}\right)
{\rm d}s+o(1)
\\\nonumber
&= \frac{1}{\ell!}
\int_{-\infty}^\infty\exp\left(- e^{-s} -(\ell+1)s- e^{(e-1)s+c_n-k}\right)
{\rm d}s+o(1).
\end{align}
\nopf (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:eigenvalue_comparison of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\phi$ be a Bernstein function such that 
\begin{align}
    \int_0^\infty u^{\frac{Q}{2}-1} e^{-t\phi(u)}du<\infty
\end{align}
for some $t>0$. Then,
\begin{enumerate}[leftmargin=*]
\item $\Delta^{\phi,\Omega}_{\mathcal{H}}$ has purely point spectrum in $L^2(\Omega, dx)$ and the first eigenvalue is strictly larger than $\phi(0)$. Moreover, denoting the eigenvalues of $\Delta^{\phi,\Omega}_{\mathcal H}$ by 
\begin{align*}
\lambda_{1,\phi}\leqslant \lambda_{2,\phi}\leqslant \cdots,
\end{align*}
we have
\begin{align} 
    \lambda_{n,\phi}\leqslant 4\phi(\lambda_n) \quad \mbox{for all $n$},
\end{align}
where $0<\lambda_1\leqslant \lambda_2\leqslant \cdots$ denote the eigenvalues of the Dirichlet sub-Laplacian $\Delta^{\Omega}_{\mathcal H}$. 
\item If $\phi$ is a complete Bernstein function, then 
\begin{align} 
    \lambda_{n,\phi}\leqslant \phi(\lambda_n) \quad \mbox{for all $n$}.
\end{align}
If in addition $\Omega$ satisfies the intrinsic exterior cone condition (see Definition~(def:cone_cond of the paper)), then 
\begin{align} 
    \lambda_{n,\phi}\geqslant c(\Omega)\phi(\lambda_n) \quad \mbox{for all $n$},
\end{align}
where $c(\Omega)>0$ is a constant independent of $n$ and $\phi$, and depends only on $\Omega$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] (\cite{chen2026edge}, Lemma 7.15)
    Let $\theta\in(0,1)$ and given constants $\eta_{\operatorname{op}}\geq 1,K_{\operatorname{low}}\geq 1$. Let $\mu$ be a probability distribution on $\{0,1\}^m$. Assume that for any $t\in[0,\theta]$ and every feasible pinning $\tau=\mathbf{1}_S$, where $S\subseteq [m]$, the distribution $\nu:=(1-t)*\mu^\tau$ satisfies
    \begin{itemize}
        \item Marginal bound: $\nu(i)\geq\frac{1}{K_{\operatorname{low}}}$ for all $i\in[m]$;
        \item Spectral stability: $\lambda_{max}(\operatorname{Cor}_\nu)\leq\eta_{\operatorname{op}}$,
    \end{itemize}
    Then if we let $L:=(K_{\operatorname{low}}+1)(\eta_{\operatorname{op}}-1)+1$, then $\mu$ satisfies
$$
\operatorname{ES}(\mu)\leq\frac{L}{1-(1-\theta)^L}
.$$ Meanwhile, the vertex-field denoising process $(Y_t)_{t\in[0,1]}$ from $\mu$ satisfies $R$-approximate conservation of entropy up to final time $\theta$ with 
$$
R=1+\frac{\max_\tau\operatorname{ES}((1-\theta)*\mu^\tau)}{L(1-\theta)^L}
.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] Let $|\gamma|<\sqrt{d_H/C_0}$. For any $u\in C_b(K)$, the sequence $\{\nu_{\ell}^\gamma(u)\}_{\ell\geq 1}$ given by
    \begin{equation*}
        \nu_{\ell}^\gamma(u):=\int_K u\,d\nu_{\ell}^\gamma,\qquad \ell\geq 1,
    \end{equation*}
    is an $L^2(\Omega)$-bounded martingale with respect to the filtration $\mathcal{F}=\{\mathcal{F}_\ell\}_{\ell\geq 1}$, where
    \begin{equation*}
        \mathcal{F}_\ell:=\sigma(h_\ell),\qquad\ell\geq 1.
    \end{equation*}

