$$
\bar X_\alpha(i, 1; j, m) = X_\alpha(i, 1; j, m) - \nu_\alpha(j-i + 1, m), \qquad \bar X_\infty(i, 1; j, m) = X_\infty(i, 1; j, m) - \mu(j-i + 1, m).
$$
We start with (equation E:half-space-upper-bd of the paper).  Let $u_1 = (1, 1), v_1 = (m, m)$, $u_2 = (t + 1, 1), v_2 = (t + n, m)$. By Corollary (C:exp-quadrangle of the paper), 
\begin{align*}
\bar X_\alpha(u_2; v_2) \le \bar X_\alpha(u_1; v_1) + \bar X_{\infty}(u_2; v_2) - \bar X_{\infty}(u_1; v_1) \le \bar X_\alpha(u_1; v_1) + Y(u_2; v_2)-\mu(n,m) - \bar X_{\infty}(u_1; v_1).
\end{align*}
