[Lemma 11 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] (Theorem 1 in \cite{VD2023B}). Let Conditions B1 and B2 be
valid and let $r_{1},r_{2},...,$ be a sequence of positive integers such
that $r_{n}\leq n$ and $r_{n}\rightarrow \infty $. If $\varphi (n),n\in
\mathbb{N},$ is a deterministic function such that $a_{n}\gg \varphi
(n)\rightarrow \infty $ as $n\rightarrow \infty $, then
\begin{equation*}
\mathcal{L}\left( X_{u}^{r_{n},n},0\leq u\leq 1|S_{n}\leq \varphi
(n),Z_{n}>0\right) \underset{n\rightarrow \infty }{\Longrightarrow }\mathcal{
L}\left( W_{u},0\leq u\leq 1\right) ,
\end{equation*}
where $\left\{ W_{u},0\leq u\leq 1\right\} $ is a stochastic process with
a.s. constant paths, that is
\begin{equation*}
\mathbf{P}\left( W_{u}=W\text{ for all }u\in (0,1]\right) =1
\end{equation*}
for some random variable $W$. Furthermore,
\begin{equation*}
\mathbf{P}\left( 0<W<\infty \right) =1.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma re4D of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Under the same assumption as in Lemma (keyI of the paper), let $\tilde{x}_N(s)=\tilde{\mu}_{n,N}-\tilde{\sigma}_{n,N}s$ with
\begin{equation}
    \tilde{\mu}_{n,N}=\left(\frac{1}{\sigma_{n-1,N}^{1/2}}+\frac{1}{\sigma_{n,N-1}^{1/2}}\right)\left(\frac{1}{\mu_{n-1,N}\sigma_{n-1,N}^{1/2}}+\frac{1}{\mu_{n,N-1}\sigma_{n,N-1}^{1/2}}\right)^{-1}
\end{equation}
and
\begin{equation}
    \tilde{\sigma}_{n,N}=\left(\frac{\sigma_{n-1,N}^{1/2}}{\mu_{n-1,N}}+\frac{\sigma_{n,N-1}^{1/2}}{\mu_{n,N-1}}\right)\left(\frac{1}{\mu_{n-1,N}\sigma_{n-1,N}^{1/2}}+\frac{1}{\mu_{n,N-1}\sigma_{n,N-1}^{1/2}}\right)^{-1}.
\end{equation} 
Then
\begin{equation*}
    N^{\frac{2}{3}}D(\tilde{x}_N(s))\le C(s_0,\gamma)e^{-\frac{s}{2}}
\end{equation*}
holds for any $s\in\left[s_0,\frac{e_0\tilde{\mu}_{n,N}}{\tilde{\sigma}_{n,N}}\right]$ when $N$ large enough.

[Proposition prop:Phi1-Phi2-fg of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $f,f'\in L$ and $g,g'\in\Gamma$. We have
    \begin{equation}
        \Phi^{(1)}(U_{f,g})=\tau_{G}(U_{f,g})=\1_{f=e_{L},\;g=e_{\Gamma}}.
    \end{equation}
    Moreover, if $g\neq e_{\Gamma}$ or $g'\neq e_{\Gamma}$,
    \begin{equation}
        \Phi^{(2)}(U_{f,g},U_{f',g'})=0 .
    \end{equation}
    Finally, when $g=g'=e_{\Gamma}$,
    \begin{align}
        \Phi^{(2)}(U_{f,e_{\Gamma}},U_{f',e_{\Gamma}})
        &=\1_{f\neq e_{L}}\1_{f'\neq e_{L}}
        \sum_{h\in\Gamma}
        \Phi^{(1)}\left(U_{f,h}U_{f',h^{-1}}\right)
        \\
        &=\1_{f\neq e_{L}}\1_{f'\neq e_{L}}
        \#\left\{h\in\Gamma:\
        f\cdot(f'\circ h^{-1})=e_{L}\right\}.

    \end{align}

