[Lemma 26 of arXiv:2608.03497, 'Connective Constants on Nested Fractal Graphs'] For \(j=0,1\), let
\[
  \mathcal E_s^{(j)}
  =
  \#\{w\in\cW_{O,s}:m_+(w)\le j\}.
\]
Then, for every \(n\ge1\),
\begin{equation}
  c_{n+h}
  =
  \mathcal E_{n+h}^{(0)}
  +
  \sum_{w\in\cW_{O,n}}
  \frac{m_-(w)}{m_+(w)+1},

\end{equation}
and
\begin{equation}
  c_{n+2h}
  =
  \mathcal E_{n+2h}^{(1)}
  +
  \sum_{w\in\cW_{O,n}}
  \frac{m_-(w)(m_-(w)-1)}
       {(m_+(w)+1)(m_+(w)+2)}.

\end{equation}

[Thm 10 of arXiv:2609.03054, 'The classes of bivariate Schur and Herglotz matrix-valued rational functions: realizations'] Let $G\in \mathbb C^{n\times n} (s,p)$ be a rational  matrix  function. Then the following conditions are equivalent:
\begin{enumerate}[\rm (i)]
\item $G$ has no singularities in $\mathbb{GH}$, the matrix $G(s,p)$ has nonnegative real part
for any $(s,p)\in \mathbb{GH}$,
and $\lim_{(s,p)\to\infty} G(s,p)$ exists;
\item $G$ admits a realization of the form
\begin{equation} 
G(s,p)=  D+  \frac12{C} \left(s I+ 2A -
    (s^2-4p) P(s I+ 2A)^{-1} P\right)^{-1}B.
\end{equation}
where the block matrix $\matr{A&B\\C&D} \in\Cmats{(k+n)}{(k+n)}$ is such that
\begin{equation*}
\matr{
A+A^* & C^*- B \\ C- B^* & D+D^*
} \geq 0
\end{equation*}
and $-I\le P \le I$.
\end{enumerate}
Additionally, if $G\in {\mathbb R}^{n\times n}(s,p)$, then the matrices $A,B,C,D$ and $P$ can be chosen as real.

