body:
[Theorem 67 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is countably monotonically bounded;
\item[(ii)] $F$ is countably $r$-monotonically bounded, for some $r\ge 1$;
\item[(iii)] Every countable directed dominable subset of $\Ba_{F_{+}}$ is order bounded;
\item[(iv)] Every countable subset of $F$ which is order bounded in $F^{**}$ is also order bounded in $F$;
\item[(v)] $F$ has a countably monotonically bounded super order dense sublattice.\medskip

Moreover, the countable monotone boundedness implies the $\sigma$-demicontinuity. The countable $r+$-monotone boundedness implies the $r$-$\sigma$-demicontinuity. A super order dense countably monotonically bounded sublattice of $F$ is majorizing.

[Proposition 57 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every \(p>1\),
\begin{equation}
  \sup_{a\geq2}\widehat{\EE}_a[J_a^{-p}]<\infty.

\end{equation}
In particular, \((J_a^{-1})_{a\geq2}\) is uniformly integrable.

[Theorem 6 (Chung's LIL) of arXiv:2608.04644, 'Khinchin's and Chung's Laws of the Iterated Logarithm at Time Zero for the Linear Stochast'] Suppose that Condition \ref{hypo} holds, $H<1$,   {$0\le\gamma<1$}, and $\beta+\gamma<2+H$.
	Then, for every  fixed $x\in\RR^d$,
	\begin{equation}
		\liminf_{\varepsilon\downarrow0} \sup_{t\in[0,\varepsilon]}\frac{|u(t,x)|}{\e^{H}(\log\log \e^{-1})^{-H}}
		=\kappa\lambda_H^{H},\ \ \ a.s.,
	\end{equation}
	where   
	\begin{equation}
		\textcolor{black}{\kappa:=
		\Bigg(\frac{1}{\pi}\int_{\mathbb{R}}\frac{1-\cos\tau}{|\tau|^{2H+1}}\,d\tau
		\int_{\mathbb{R}^d}\frac{|\xi|^{\ell-d}}
		{1+2|\xi|^\alpha\cos(\pi\beta/2)+|\xi|^{2\alpha}}\,d\xi
		\Bigg)^{1/2}.}
	\end{equation}
 \textcolor{black}{Here,} $\lambda_H$ is the small-ball constant of a standard FBM $\{B_H(t)\}_{t\ge0}$ with index $H$ (see, e.g., \cite{LS2001}), defined by
 \begin{equation}
\lambda_H:=-\lim_{\varepsilon\downarrow0}\varepsilon^{1/H}
\log\mathbb P\left(\sup_{0\le t\le1}|B_H(t)|\le\varepsilon\right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:BLPP-kernel-reform of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The multipoint distribution satisfies
\[
\det(I - \chi_{\mathbf{a}} K
\chi_{\mathbf{a}})_{L^2(\{t_1, \dotsc, t_k\}
\times \mathbb{R})}
= \det(I - K_{\mathbf{t}, \mathbf{a}, n})_{L^2(\mathbb{R})},
\]
where
\begin{equation}
K_{\mathbf{t}, \mathbf{a}, n}
= \sum_{1 \leq i \leq j \leq k}
\int_{a_i}^{\infty} \int_{a_j}^{\infty}
\psi_{t_i, z, n}
[B_{\mathbf{t},\mathbf{a}}]_{ij}(z, w)\phi_{t_j, w, n}\mathrm{d} w\mathrm{d} z.
\end{equation}

[Lemma lem:JordanLowerBoundUpper of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For the Jordan ordering $\widehat{\sigma}_J$, there exist positive constants $C$ and $c$ such that for any $n\geq 1$, any vertex $v\in [n]$ and any $S\geq 1$, 

    \begin{equation}
        \mathbb{P}\left(\widehat{\sigma}_J(v)\leq \frac{v}{S}\right) \leq C \left( e^{- c v/S} +  e^{-S/64} \right).
    \end{equation}

