[Lem 19 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)\subset H=(V',E')$ be two subgraphs of $\mathbb Z^d$. For every $\beta\geq 0$, and every $x,y \in V'$,
\begin{equation}
	\langle \sigma_x\sigma_y\rangle_{H,\beta}-\langle \sigma_x\sigma_y\rangle_{G,\beta}\leq \sum_{u\in \partial V}\langle \sigma_x\sigma_u\rangle_{G,\beta}\langle \sigma_u\sigma_y\rangle_{H,\beta},
\end{equation}
where $\p V:= \{ u\in V : \exists v\in V' \setminus V \text{ with } uv \in E' \}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:spectral_heat1 of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega$ be a bounded, open subset of $\mathbb{G}$. If $\Omega$ has $C^2$ boundary with no characteristic points, then
    \begin{enumerate}[leftmargin=*]
        \item  For $1<\alpha<2$, 
        \begin{align*}
            \lim_{t\to 0}\frac{\operatorname{Vol}(\Omega)-\widetilde{H}^{(\alpha)}_\Omega(t)}{t^{\frac{1}{\alpha}}}= \mathbb{E}\left[\sup_{0\leqslant t\leqslant 1} Y_t\right]\operatorname{Per}_{\mathcal H}(\Omega),
        \end{align*}
        where $(Y_t)_{t\geqslant 0}$ is a one-dimensional symmetric $\alpha$-stable L\'evy process such that $\mathbb{E}[e^{i \xi Y_t}]=e^{-t|\xi|^\alpha}$ for all $t\geqslant 0$ and $\xi\in\mathbb R$.
        \item  When $\alpha=1$, 
        \begin{align*}
            \lim_{t\to 0}\frac{\operatorname{Vol}(\Omega)-\widetilde{H}^{(1)}_\Omega(t)}{t\log(1/t)}= \frac{1}{\pi}\operatorname{Per}_{\mathcal H}(\Omega).
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:3.1 of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $(f_n)_{n \geqslant 0}$ be a sequence of increasing differentiable functions from $[0, \beta_0]$ to $[0, M]$. Assume that this sequence converges to a function $f$ and that, for all $n \geqslant 1$, we have
  \begin{equation}
    f_n' \geqslant \frac n {\sum\limits_{k=0}^{n-1} f_k} f_n.

  \end{equation}
  Then there exists $\beta_1 \in [0, \beta_0]$ such that
  \begin{itemize}
      \item for $\beta < \beta_1$ there exists $c_\beta > 0$ such that for any $n$ large enough $f_n(\beta) \leqslant \exp(- c_\beta n)$,
      \item for $\beta > \beta_1, f(\beta) \geqslant \beta - \beta_1$.
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

