[Definition def-condlim of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix an edge potential $h$, and $c \in \R$, $c \neq \sref.$ Let $\Conset_n(h,c)$ and  $(c_\delta)_{\delta > 0}$ be  as in Definition (\oldref{def-rareevent}) and  (equation sdelta of the paper), respectively. 
\begin{enumerate}
\item Given $\rho^*\in \P(\Gstar[\X])$, we say  that {\em   $U_n$  given $\Conset_n(h,c)$ converges to $\rho^*$ } if  
   \begin{align}
\lim_{\delta\downarrow0}\lim_{n\to \infty}\mathbb{P}(U_n\in \cdot\mid \Conset_n(h, c_\delta))=\delta_{\rho^*}(\cdot).
\end{align}
    \item 
For any $\mathcal{U}\subset \P(\Gstar[\X]),$ we say that {\em  $U_n$ given $\Conset_n(h,c)$ lies in $\mathcal{U}$ asymptotically} if for every open set $U\supset \mathcal{U}$, the following holds:
    \begin{align}
        \lim_{\delta\downarrow 0}\limsup_{n\to \infty}\frac{1}{n}\log\mathbb{P}\left(U_n\notin U\ \vert\ 
        \Conset_n(h,c_\delta) \right)<0.
    \end{align} 
\end{enumerate}

[Proposition 19 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every \(0<R<\infty\),
\begin{equation}
  \lim_{\delta\downarrow0}
  \sup_{\substack{F\subset\mathbb D\\F\text{ finite}}}\;
  \sup_{\substack{s,t\in[-R,R]\\|s-t|\leq\delta}}
  |m_F(t)-m_F(s)|=0.

\end{equation}
In particular, the same conclusion holds with the outer supremum replaced
by \(\sup_n\) and \(m_F\) replaced by \(m_n\) for every sequence satisfying
\eqref{eq:wall-parameter-limit}.

