\begin{enumerate*}
\item $t\mapsto \varphi(t)$ is absolutely continuous in $t\in[0,\infty)$, and
\item $\dot{\varphi}(t)\in F(\varphi(t))$ for almost every $t\geqslant 0$, with $\varphi(0)=(a,b,c)$.
\end{enumerate*}
Let $\Phi(a,b,c)$ denote the set of all such solutions $\varphi$. Our goal, here, is to show that $\varphi(t)\in\hat{\mathcal{S}}$ for every $t\geqslant 0$ and every $\varphi\in\Phi(a,b,c)$, for each ...","release_manifest_digest":"sha256:babf3ae4eaa0601b15439eecac860d7475eeea6007c39e79dc42095ac6e928b8","revision_digest":"sha256:ed42306e3f77bccda177173bff12f0530cb7ca84338fc0ffab6bc7eba11a7044","source_id":"arxiv:2608.01419","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

