body:
[Proposition prop:prn_integral of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For $1\le r\le n$, the probability $p_{r,n}$ admits the integral representation
\begin{equation}
p_{r,n}
=\int_0^\infty r {\rm e}^{-r t}
\prod_{\substack{1\le k\le n\\k\neq r}}
\bigl(1-{\rm e}^{-k t}\bigr)\,{\rm d}t.
\end{equation}
Equivalently,
\begin{equation}
p_{r,n}
=\int_0^1 r\,u^{r-1}
\prod_{\substack{1\le k\le n\\k\neq r}}
(1-u^k)\,{\rm d}u.
\end{equation}

[Lemma 14 of arXiv:2608.27374, '\Large \bf Distribution-constrained optimal multiple stopping: the Root-type solution'] For every \(t\in[t_0,r_\xi^\beta)\) and \(x\in\mathbb R\),
\begin{equation}

    u^\beta(t,x)
    =
    \inf_{\rho\in\mathcal T_t^\Gamma}
    \E^x\!\left[
        v^\xi(t-\rho,Y_\rho)
        +
        w^\beta(t-\rho)\mathbf 1_{\{\rho<t\}}
    \right].
\end{equation}

[Proposition prop:WicksWigner of arXiv:2510.01021, '\Large Random Matrices, Intrinsic Freeness, and Sharp Non-Asymptotic Inequalities\relatedv'] Let $W_1,\dots,W_n$ be $N\times N$ independent standard Wigner matrices (recall Definition~(def:standardWignerMatrix of the paper)). Given a partition $\nu\in\mathbb{P}[2p]$ let $u_\nu$ be the $\nu$-assignment (see Definition~(def:pairpartition of the paper)). We have
    \begin{equation}
            \mathbb{E}\left[\tr W_{u_\nu(1)}\cdots W_{u_\nu(2p)}\right]  = 1,
    \end{equation}
    if $\nu\in \mathrm{NC}[2p]$ is non-crossing, and 
\begin{equation}
            \lim_{N\to\infty} \mathbb{E}\left[\tr W_{u_\nu(1)}\cdots W_{u_\nu(2p)}\right] = 0,
    \end{equation}
if $\nu\in \mathbb{P}[2p]\setminus \mathrm{NC}[2p]$ is crossing.

    Furthermore, $W_1,\dots,W_n$ enjoy (in the limit) a Wick's formula summing only over non-crossing partitions: For $u:[2p]\to[n]$ we have
    \begin{equation}
\lim_{N\to\infty}\mathbb{E}\left[\tr W_{u(1)}\cdots W_{u(2p)}\right] = \sum_{\nu\in \mathrm{NC}_2[2p]} 1_{u \sim \nu}.
    \end{equation}
The identities (equation eq:WignerNONcrossingpairings of the paper)--(equation eq:WicksforWigner of the paper) hold for a free semicircular family $s_1,\dots,s_n$ (without needing to take a limit). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p=1$ and~\eqref{co:1} and~\eqref{co:2} be valid. Then pathwise uniqueness holds for~\eqref{eq:SIS epidemic model}, and any two solutions $I$ and $\tilde{I}$ to~\eqref{eq:SIS epidemic model} satisfy
\begin{equation}
\E\big[|I_{t} - \tilde{I}_{t}|\big] \leq e^{\int_{0}^{t}(\hat{b}_{k+1} + \hat{\lambda}_{k+1})(s,N(s))\,\mathrm{d}s}\E\big[|I_{0} - \tilde{I}_{0}|\big]
\end{equation}
for all $t\geq 0$. In particular, if $(\hat{b}_{k+1} + \hat{\lambda}_{k+1})^{+}(\cdot,N)$ is integrable, then $\sup_{t\geq 0} \E[|I_{t} -\tilde{I}_{t}|]$ is finite. If additionally
\begin{equation*}
\int_{0}^{\infty}(\hat{b}_{k+1}+\hat{\lambda}_{k+1})^{-}(s,N(s))\,\mathrm{d}s = \infty,\quad\text{then}\quad \lim_{t\uparrow\infty} \E\big[|I_{t}-\tilde{I}_{t}|\big] = 0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] For every fixed $a>0$, every $s\ge0$, and every integer $k\ge1$,
\begin{equation}
 \int_0^\infty e^{-a\lambda u}
 (1-e^{-\lambda u})^{a(k-1)}\dd u\ll_a(1+k)^{-a}.
\end{equation}
Moreover, for $k>e^{\lambda s}$,
\begin{equation}
 \int_0^s e^{-a\lambda u}
 (1-e^{-\lambda u})^{a(k-1)}\dd u
 \ll_a(1+k)^{-a}e^{-a k e^{-\lambda s}/4}.
\end{equation}

[Theorem 4 (Decision-boundary representation of the error-rate Hessian) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Under \Cref{ass:boundaries}, with $p_Y$ continuous at the boundaries,
\begin{equation*}
 \left.\frac{\partial R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta}\right|_{\widetilde\theta=\theta}=0,
\end{equation*}
and
\begin{equation}
 H_{R}(\theta)
 :=\left.\frac{\partial^2 R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta\partial\widetilde\theta^\top}
 \right|_{\widetilde\theta=\theta}
 =\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{2|\delta_y(y_j;\theta)|}
 g(y_j;\theta)g(y_j;\theta)^\top.

\end{equation}
Let $\widehat\theta$ satisfy
\begin{equation}
 \sqrt n(\widehat\theta-\theta)\xrightarrow{d}N(0,V),
 \qquad
 n\E\{(\widehat\theta-\theta)(\widehat\theta-\theta)^\top\}\longrightarrow V,

\end{equation}
and suppose that, for some $\epsilon>0$,
\begin{equation}
 \E\|\sqrt n(\widehat\theta-\theta)\|^{2+\epsilon}=O(1).

\end{equation}
Then
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top Vg(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For a correctly specified regular maximum-likelihood estimator satisfying the stated moment conditions,
$V=\J(\theta)^{-1}$, so
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top\J(\theta)^{-1}g(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For the estimator that ignores the missingness mechanism, the same specialisation holds with $\J=\J_{\mathrm{ig}}$ by \Cref{lem:ig-information}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma mns1-mns2 lemma used for passing limit of arXiv:2411.04631, 'Existence of Martingale Solutions to Stochastic Constrained Heat Equation'] For all $t_1,t_2 \in [0,T]$ with $t_2 \leq t_1$, for all $\phi$ in $ \mathcal{V}$ and for all $h$ in $\mathcal{C}([0,T], \mathcal{H})$. Then following holds.
    \begin{align}
        \lim_{n \rightarrow \infty }\hat{\mathbb{E}}\left[ \left \langle \hat{M}_{n}(t_1)-\hat{M}_{n}(t_2) , \phi_1 \right \rangle_{\mathcal{H}}h(v_{n|[0,t_2]}) \right]= \hat{\mathbb{E}}\left[ \left \langle \hat{M}(t_1)-\hat{M}(t_2) , \phi_1 \right \rangle_{\mathcal{H}}h(v_{|[0,t_2]}) \right]. 
    \end{align}

