[Theorem IPM of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume   $({\bf A}_0)$, $({\bf A}_1)$ and  $({\bf H}_1)$-$({\bf H}_5)$, and suppose further $({\bf A}_5)$ once $\beta $ involved  in $({\bf H}_5)$
satisfies  $\beta> 1/2.$
Then,  there exists a   constant
$  C_0  >0$
such that for all
 $\delta\in(0,\delta_2^{\star\star}]$, $n\ge0,$ $\mu\in \mathscr P_2(\mathds R^d)$,
\begin{equation}
\mathbb{W}_{2}\big(\pi_\8,\pi_\8^{(\delta)}\big)\le  C_0 \delta^{1\wedge\beta}  d^{\frac{1}2\ell_\star}   ,
\end{equation}
  and
\begin{align}
\mathbb{W}_2(\mu P^{(\delta)}_{n\delta},\pi_\8)\le C_0 \big(\text{\rm{e}}^{-\frac{1}2(\lambda_1\wedge\lambda_2) n\delta}	\mathbb{W}_2(\mu,\pi_\8)+\delta^{1\wedge \beta}  d^{\frac{1}2\ell^\star}   \big),
\end{align}
where  $\pi_\8$ $($resp. $\pi_\8^{(\delta)}$$)$
is  the $($resp. unique$)$   IPM of $(X_t)_{t\ge0}$ $($resp. $(X_{n\delta}^\delta)_{n\ge0}$ determined by (equation E2 of the paper)$)$,
\begin{align}
\ell_\star:= \big(2\ell_0+1+(1+\ell_0^\star)\mathds 1_{\{\beta>\frac12\}}\big)\vee(\ell_0+l_2)\vee l_\beta^{*},~~   ~~ \delta_2^{\star\star}:=\delta_1^\star\wedge\big( K_R^*/(4\psi^2_2(1))\big)^{\frac{1}{1-2 \theta}},
\end{align}
and the quantities $\lambda_1,\lambda_2, \delta_1^\star>0$ were given in Theorem (thm of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, $p\in [1,2]$ and $q\in [1,2)$,
\begin{equation}
    \sum_{J\subseteq[n]:|J|=k}\frac{\left\|\Dop_J f\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\Dop_J f\right\|_{\Leb^p}^{p}/\left\|\Dop_J f\right\|_{\Leb^q}^{2})\big]^{k}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-inf-Boolean}}}(q)^k \Wop^{\geq k}(f),
\end{equation}
where $C^{\text{\rm\ref{thm:high-order-Lp-Lq-inf-Boolean}}}(q) = \big(1+\frac{q}{2\upe(2-q)}\big)^{-1} \gtrsim 2-q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: example1 of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that $f_0 =\{ f_0(n , N, n_X  ) \}_{ (n , N , n_X   ) \in   \mathbb N^4    } $ is such that $f_0(n , N, n_X  ) \neq 0 $ if and only if $n_X = e_k $ for $ k \in \{ 1, 2 \} $. Moreover assume that 
\[ 
\sum_{ n \in \mathbb N  } \sum_{ N  \in \mathbb N  } \sum_{ n_X \in \mathbb N^2 }   f_0(n, N, e_k ) =1   \ \text{ and } \ \sum_{ n \in \mathbb N  } \sum_{ N  \in \mathbb N  } \sum_{ n_X \in \mathbb N^2 }   (N+n+1)  f_0(n, N, n_X  ) < \infty . 
\]
Then there exists a unique sequence of functions  $ \{ f(t,n,N, n_X ) \}_{ (n , N , n_X  ) \in   \mathbb N^4 \times \{ 0, 1 \}   }$  such that for every $(n,N, n_X)$ the function $t \mapsto f(t,n,N, n-X  )$ is continuously differentiable and satisfy (equation eq:master example of the paper) for every $ \varphi \in c_{ 00} (\mathbb N^4 ) $. 
Moreover we have that 
\begin{equation} 
f(t, n , N, n_X  ) \neq 0 \text{  if and only if } n_X = e_k  \text{  for }  k \in \{ 1, 2 \}. 
\end{equation}
Finally, there exists a unique steady state $  \{  \bar f (n, N, n_X ) \}_{ (n , N , n_X  ) \in   \mathbb N^4} $  to equation (equation eq:master example of the paper) and 
    \begin{equation}
        f(t, (n, N, n_X)  ) \rightharpoonup  \overline f (n, N, n_X) \text { as }  t \to \infty \text{ for every } (n, N, n_X) \in \mathbb N^4.
    \end{equation}

[Corollary cor:varianceunderinvariance of arXiv:2411.08848, 'Stationary random measures: Covariance asymptotics, variance bounds and central limit theo'] Let the setting be as in Lemma~(l:exactcov of the paper) and in addition, assume that $f$ satisfies the same assumptions as $g$.   

\begin{enumerate}
\item {\bf Flip invariance:} If ${\bf K}$ is invariant under reflections in the co-ordinate hyperplanes, then $I(\gamma)=0$ unless $\gamma\in (2\mathbb{Z}_+)^d$ and hence,
\begin{align}
Q_{2p}^{{\bf K}}(f,g)=\sum_{|\gamma|=p}\frac{(-1)^p}{(2\gamma)!}I(2\gamma)\langle \partial^{\gamma} f,  \partial^{\gamma}g\rangle

\end{align}

\item {\bf Orthogonal invariance:} If ${\bf K}$ is invariant under orthogonal transformations, we may write ${\bf K}(\mathrm{d} z)= r^{d-1}{\bf K}(\mathrm{d} r)\sigma(\mathrm{d} \omega)$ where $z = r\omega$ with $r>0$, $\omega\in \mathbb{S}^{d-1}$ and $\sigma$ denotes the surface-area measure on $\mathbb{S}^{d-1}$. Here we abuse notation by using ${\bf K}$ for the measure on the radial part as well but that will not cause any confusion. Then 
\begin{align}
Q_{2p}^{{\bf K}}(f,g)  = \begin{cases}(\lambda_D + \sigma_dJ(d-1))\ \langle f,g\rangle & \mbox{ if }p=0, \\
\frac{(-1)^p\sigma_d J(d-1+2p)}{p! \ 2^p \ d(d+2)\ldots (d+2p-2)}\langle \Delta^{p/2}f, \Delta^{p/2}g\rangle & \mbox{ if }p\ge 1. \end{cases}    
\end{align}
Here  $J(p):=\int_0^{\infty}r^{p} \,{\bf K}(\mathrm{d} r)$ and $\Delta$ is the Laplacian, whose $\tfrac{p}{2}$ power is interpreted as $\Delta^{p/2}f:=\nabla(\Delta^q f)$ if $p=2q+1$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 (Solving Nekrasov equations with one band) of arXiv:2601.16377, '2601.16377'] Take four real parameters $\hat{a} <\alpha < \beta <\hat{b}$ and set $\sigma(z)=\sqrt{(z-\alpha)(z-\beta)}$. Assume that we have four functions $F(z)$, $A(z)$ (unknown), $E(z)$ and $s(z)$ (known) such that
\begin{equation}
s(z) \cdot \sigma(z) \cdot F(z)= E(z) +A(z),
\end{equation}
 where $F(z) =  O(\frac{1}{z^2})$ as $z \rightarrow \infty$, the functions $E(z),F(z)$ are holomorphic for $z \in \amsmathbb{C} \setminus [\hat{a},\hat{b}]$ while $s(z)$ and $A(z)$ are holomorphic in a neighborhood of $[\hat a,\hat b]$ and $s(z)$ has no zeros in this neighborhood. Then \eqref{eq_theeqa_intro} has a unique solution $F(z)$ given by
 \begin{equation}
F(z)=\Op\bigg[\frac{E}{s}\bigg](z) \qquad \textnormal{with}\quad \Op[f](z) := \frac{1}{\sigma(z)} \oint_{\gamma} \frac{\dd \zeta}{2\ii\pi} \frac{f(\zeta)}{z - \zeta},
\end{equation}
where the contour $\gamma$ surrounds $[\hat{a},\hat{b}]$ but leaves $z$ outside.

