[Theorem fpcomm of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] Let $ X=(X_t)_{t\in[0,T]} $ be the solutions of the SDEs ((mSDEscom of the paper)), if $ f, g$ and $ h$ are bounded smooth functions and satisfied the commutativity conditions. Then the memory-dependent PDEE for PDFs $ p(x,t) $ of the solutions $ X_t $, satisfies the following equation
		\begin{align}
		\frac{\partial }{\partial t}p(x,t)=&-\frac{\partial }{\partial x}\big\{\big(f(x)+\frac{1}{2}g(x)g'(x)+Ht^{2H-1}h(x)h'(x)\big)p(x,t)\big\}\cr
		&+\frac{\partial^2 }{\partial x^2}\big\{\big(\frac{1}{2}g^2(x)+Ht^{2H-1}h^2(x)\big)p(x,t)\big\},
		\end{align}
		where the initial condition is given by $p(x,0)=\delta(x-x_0)$.

[Definition eqn:delay_controlled of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume $J = [a,b]$ is a compact interval and $\frac{1}{3} < \beta \leq \gamma$. Let $\mathbf{X}$ be a delayed $\gamma$-rough path. We say that a $\beta$-H\"older path $\zeta \colon J \to W$ is a \emph{delayed controlled path} based on $\mathbf{X}$ over the interval $J$ if there exist $\gamma$-H\"older paths $\zeta^0, \zeta^1 \colon J \to L(\mathbb{R}^d, W)$ such that
		\begin{align}
			\zeta_{s,t} = \zeta^0_s (\delta X)_{s,t} + \zeta^1_s(\delta X)_{s-r,t-r} + \zeta^{\#}_{s,t}
		\end{align}
		for all $s,t \in J$, where $\zeta^{\#} \colon J \times J \to W$ satisfies $\|\zeta^{\#}\|_{2\gamma ; J} < \infty$.



		The paths $\zeta^0$ and $\zeta^1$ are referred to as the \emph{Gubinelli derivatives} of $\zeta$. We denote the space of delayed controlled paths based on $\mathbf{X}$ over the interval $J$ by $\mathcal{D}_{\mathbf{X}}^\beta(J, W)$. A norm on this space is defined as
		\begin{align}
			\|\zeta\|_{\mathcal{D}_{X}^{\beta}(J,W)} := \|(\zeta,\zeta^0,\zeta^1)\|_{\mathcal{D}_{X}^{\beta}(J,W)} := |\zeta_a| + |\zeta^0_a| + |\zeta^1_a| + \|\zeta^0\|_{\beta; J} + \|\zeta^1\|_{\beta; J} + \|\zeta^{\#}\|_{2\beta; J}.
		\end{align}

[Lem construction-of-mn of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] There exist open sets $\mathcal{M}_N \subset \mathbb{R}^d \times S^{n-1}$ for $N \in \mathbb{N}$ satisfying
\begin{equation}
    \mathcal{M}_\infty \coloneqq \{(z,v) \in \mathbb{R}^d \times S^{n-1} \mid P_0(z)v = 0\} \subset \bigcup_{K = 1}^\infty \bigcap_{N=K}^\infty \mathcal{M}_N
\end{equation}
and
\begin{equation}
    \lim_{N \to \infty} \limsup_{\epsilon \downarrow 0} \sup_{\mu^\epsilon \in P^\epsilon_{\mathrm{inv}}} \mu^\epsilon(\mathcal{M}_N) = 0\,.
\end{equation}

