[Proposition 191 of arXiv:2601.16377, '2601.16377'] The Green function $\textnormal{Gr}$ on $\Sigma^{\textnormal{half}}$ with Dirichlet boundary conditions has the following expression\footnote{One should compare this with (4.21), (4.22) in \cite{BuGo3} and note a sign error in that paper --- one needs to multiply $\frac{1}{4\pi}$ by $(-1)$ in both formulae. In the proofs of \cite{BuGo3} this sign error compensates with wrong signs in (4.25), (4.26) and in the computation of mixed partial derivative above (4.58).} for non-real $z_i\in \Sigma^{(q_i)}$ ($i = 1,2$):
 \begin{equation} 
 \textnormal{Gr}(z_1,z_2)= \left\{\begin{array}{lll} -\dfrac{1}{4\pi} \displaystyle\int_{z_1^*}^{z_1}\displaystyle\int_{z_2^*}^{z_2} \mathcal{F}^{(q,q)}(w_1,w_2) \dd w_1 \dd w_2- \dfrac{1}{2\pi} \log\left|\frac{z_1-z_2}{z_1-z_2^*}\right|& & \textnormal{ if }\, q_1 = q_2 = q,\\[12pt] - (-1)^{\textnormal{par}(q_1,q_2)}\dfrac{1}{4\pi} \displaystyle\int_{z_1^*}^{z_1}\displaystyle\int_{z_2^*}^{z_2} \mathcal{F}^{(q_1,q_2)}(w_1,w_2) \dd w_1 \dd w_2 && \textnormal{ if }\,\, q_1\neq q_2,\end{array}\right.
 \end{equation}
 where the parity $(-1)^{\textnormal{par}(q_1,q_2)}$ is $(+1)$ if $\mathcal T_{q_1},\mathcal T_{q_2}$ are both left, or both right trapezoids, and $(-1)$ otherwise. In particular, \eqref{eq_Green_function_explicit} extends to a continuous function of $\Sigma^{\textnormal{half}} \times \Sigma^{\textnormal{half}}$ minus the diagonal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 19 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a m-dependent stationary sequence in a sub-linear space $\sles$ satisfying following conditions :
\begin{itemize}
    \item[(1)] $\bE[X_1] = \be[X_1] = 0$;
    \item[(2)] $\bE[X_1^2]<\infty$;
    \item[(3)] $C_{\V}\left[\frac{X_1^2}{\log\log|X_1|}\right]<\infty$.  
\end{itemize}
Then we have 
\begin{equation}
\mvstar\left(\lsigma\le\limsup_{n\to\infty}\frac{S_n}{\sqrt{2n\log\log n}}\le\usigma\right)=1
\end{equation}
for some $0\le \lsigma\le\usigma<\infty$ where the following limits exist:
\begin{equation}
    \usigma^2:=\lim_{n\to\infty}\frac{\bE[S_n^2]}{n},\quad \lsigma^2:=\lim_{n\to\infty}\frac{\be[S_n^2]}{n}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop cauchy of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Let $V \subseteq \mathcal{U}$ be finite and $((\xi^{u}_{0})_{u \in V},R_{0}) \in (\mathbb{R}^{*}_{+})^{|V|} \times [0,R_{\max}]$. Then, there exists a neighborhood $O \subseteq (\mathbb{R}^{*}_{+})^{|V|} \times [0,R_{\max}]$ of $((\xi^{u}_{0})_{u \in V},R_{0})$, and a neighborhood $J \subseteq \mathbb{R}^{+}$ of 0, such that
\begin{itemize}
\item[1.] For every $((\xi^{u})_{u \in V},R) \in O$, there exists a unique local solution with values in $(\mathbb{R}^{*}_{+})^{|V|} \times [0,R_{\max}]$ to the system of coupled equations (equation eq:regroupindiv of the paper)-(equation regeoupee of the paper), starting from $((\xi^{u})_{u \in V},R)$ at time 0. This solution is at least defined on $J$, and denoted as $\left((X^{u}_{t}(\Xi,R))_{u \in V},X^{\Re}_{t}(\Xi,R)\right)$, with $\Xi := (\xi^{u})_{u \in V}$. 
\item[2.] The function $(t,(\xi^{u})_{u \in V},R) \in J \times O \mapsto \left((X^{u}_{t}(\Xi,R))_{u \in V},X^{\Re}_{t}(\Xi,R)\right)$ is $\mathcal{C}^{1,1}(J \times O)$, and $\mathcal{C}^{2}$ in the variable $t$.
\end{itemize}

[Lemma lemma number of clockwise loops of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] We have the following convergence
	\begin{equation*}
	\left( (D_t^\kappa)_{t\ge 0}, \tau^\kappa_\mathrm{ccw}, \theta^\kappa,\left( \ka_\kappa^{-1} \# \{i\ge 1: \tau^\kappa_i \le t\}\right)_{0 \le t \le \tau^\kappa_\mathrm{ccw}} \right)
	\mathop{\longrightarrow}\limits_{\kappa\downarrow 4}^{(\mathrm{d})}
	\left( (D_t)_{t\ge 0}, \tau, \theta,\left( \frac{1}{4\pi} L^0_t(\theta)\right)_{0 \le t \le \tau} \right),
	\end{equation*}
	where the first coordinate converges in $\SD$, the second one in $\BR$ and the third and fourth ones converge for the topology of uniform convergence on compact subsets of $\BR_{\ge 0}$, using the extension described below (equation eq cv theta of the paper).

[Theorem 10 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$ and $q\in [1,2)$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^2}^{2} \geq \Wop^{\geq k}(f) \left[1+ \frac{q}{2k(2-q)}\ln^+\left(\frac{\Wop^{\geq k}(f)}{\sum_{\kappa:|\kappa|=k} \left\|\Dop^\kappa f\right\|_{\Leb^q}^2} \right)\right]^k,
\end{equation}
and further for $\left\|f\right\|_{\Leb^\infty}\leq 1$ and $q\leq p<2$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Eldan-Gross-Gaussian}}}(p,q)^k\Wop^{\geq k}(f) \left[1 +  \frac{q}{2k(2-q)}\ln^+\left(\frac{1}{\sum_{\kappa:|\kappa|=k} \left\|\Dop^\kappa f\right\|_{\Leb^q}^2} \right)\right]^\frac{kp}{2},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Eldan-Gross-Gaussian}}}(p,q) = C^{\text{\rm\ref{thm:high-order-Eldan-Gross-Boolean}}}(p,q) \gtrsim \left(2-p\right)\left(2-q\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem uniform-triangular-nerman of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Fix $\varepsilon\in(0,1/2)$ and $y\in\mathds{R}$.
If $\phi$ is continuous and $|\phi(a)|\leqslant Ce^{\eta a}$ for some $\eta<1$, or if $\phi$ is bounded and Riemann-integrable, then
\begin{align}
 \sup_{\mathfrak{s}_0\leqslant t\leqslant \mathfrak{s}_1}
 \abs{
 e^{-\alpha_nt}Z_n^\phi(t)
 -\frac{\mathcal{W}_{n,\infty}}{\theta_n}
 \int_0^\infty e^{-\alpha_na}\phi(a)\,\mathrm d a
 }
