[Theorem 1 of arXiv:2606.03973, 'A remark on the \\ majorizing measures theorem for general processes'] Suppose that $X \sim \mu$ is a centered random vector in $\R^n$ such that
  \begin{equation}

  \klconst(\mu) = \sup_{\substack{\theta, \eta \in \R^n \\ \theta \neq \eta}} 
\frac{\kl{\mu_\theta}{\mu_\eta}}{\|\theta - \eta\|_2^2} < \infty,
  \end{equation}
  where $\mu_\theta$ denotes the law of the translate $\theta + X$.
  Then, for any nonempty, bounded $T \subset \R^n$,
  \[
  \E_\mu \Big[\sup_{t \in T} \, \langle X, t \rangle \Big] \gtrsim \frac{1}{\sqrt{\klconst(\mu)}} \, \gamma_2(T).
  \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 54 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $\SC$ be as defined at the start of \cref{sec:example_lmd<umd} and
    consider $\SC$ as a subset of $\ell^{\infty}(\NN)$.
    Then for every $\eps \in (0,1)$ we have
    \begin{equation*}
        \prod_{i=1}^{n(\eps)} \frac{a_i}{\eps}
        \le \cn(\SC,\eps) 
        \le \prod_{i=1}^{n(\eps)} \Bigl(\frac{a_i}{\eps} +1\Bigr)  .
 \end{equation*}

[Lem 44 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For any $K \geq (\widetilde C_{\mu}+\varepsilon) \log N$ and $i\in \{\iota(p),\ldots,\tau(p)-2\}$, and any $\xi>0$, there exists an event $F_i=F_i(\xi) \in \sigma(\mathbf a_i)$ and $\zeta=\zeta(\mu,\xi)$, such that the following holds.
        \begin{enumerate}[label=(\alph*)]
            \item 

            We have
            \begin{equation} 
                \mathbb P(F_{i}) \geq 1- \exp(-N^{\zeta}).
            \end{equation}
            \item 

            There exists $C(\mu,\chi)>0$ such that if $s_i \in \mathsf S^\p _{\for}$, we have that for all $x \in \mathsf S^\p_{\for}$ and $x>_{\lex} s_i$, 
            \begin{equation}

                \mathbb E\left[\left|\cI(B_x) \right|\big\vert \mathbf a_i\right] \leq C(\mu,\chi)N(\lambda_{x})^{1-o_{\chi}(1)}\cdot N^{O(\chi)}.
            \end{equation}
            on the event $F_i$.
            \item 

            There exists $C(\mu,\chi)>0$ such that if $s_i \in \mathsf S^\p _{\for}$, we have
            \begin{equation}

                \mathbb E\left[\left|\{j>i:s_j=s_i \}\right|\big\vert \mathbf a_i\right] \leq C(\mu,\chi)N(\lambda_{s_i})^{1-o_{\chi}(1)}\cdot N^{O(\chi)}.
            \end{equation}
            on the event $F_i$.
            \item

            There exists $C(\mu,\chi)>0$ such that if $s_i \in \mathsf S^\p _{\for}$, we have that for all $x \in \mathsf S^\p_{\for}$ and $x>_{\lex} s_i$, 
            \begin{equation} 
                \mathbb E\left[\left|E(G_{B_x}) \right|\big\vert \mathbf a_i\right] 
                \leq C(\mu,\chi)N^{2-\frac{K-M}{\log N}\sum_{1 \leq i \leq z} h_i\psi_{\bp^{(i)}}(2)+o_\chi(1)} \cdot(\lambda_{x})^{2-o_\chi(1)} 
            \end{equation}
            on the event $F_i$,
            where $M$ is the length of prefix $x$.
            \item 
             For any prefix $x$ such that $\lambda_x \geq N^{-1+\xi}$, we have 
            \begin{equation}
                \P \lt( \big|\,|\cI(B_x)|-N \lambda_x \big| \leq (N \lambda_x)^{\frac{4}{5}} \big|\mathbf a_i \rt)\geq 1-\exp(-N^{\xi/2})
            \end{equation}
            on the event $F_i$.
            \item 

            For any prefix $x$ such that $\lambda_x \geq N^{-1+\xi}$, we have 
            \begin{equation}
                \P \Big(\Big|n^{(t),x}_{ l}-N \lambda_x \cdot \frac{n^{(t)}_{ l}}{N}\Big| \leq (N \lambda_x)^{\frac{4}{5}} \mbox{  for all $(t,l) \in \mathsf{P}$ and $ M<t\leq K$}\big|\mathbf a_i \Big)\geq 1-\exp(-N^{\xi/2})
            \end{equation}
            on the event $F_i$, where $M$ is the length of prefix $x$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:main of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] Under the assumptions of Theorem (thm:main of the paper) the following holds:
\begin{itemize}
    \item[(A)] We have 
    \begin{equation*}
        \mathbb{E} f_{j}(\mathcal{P}_{n,\operatorname{bd}}^{\boldsymbol{\beta}}) \asymp n^{\frac{k_{\max}-1}{k_{\max}+1}} (\ln n)^{\#k_{\max}-1},
    \end{equation*}
    for all $j\in\{\lfloor{d/2}\rfloor -1,\ldots,d-1\}$.

    \item[(B)] In the uniform case ${\boldsymbol{\beta}}=(0,\ldots,0)$, we have
    \begin{align*}
        \mathbb{E} f_{j}(\mathcal{P}_{n,\operatorname{bd}}^{\boldsymbol{\beta}}) &\asymp n^{\frac{d_{\max}-1}{d_{\max}+1}} (\ln n)^{\#d_{\max}-1},
    \intertext{for all $j\in\{0,\ldots,d-1\}$ and}
        \operatorname{Vol}_d(Z_\operatorname{bd}) - \mathbb{E}\operatorname{Vol}_d(\mathcal{P}_{n,\operatorname{bd}}) &\asymp n^{-\frac{2}{d_{\max} + 1}} (\ln n)^{\#d_{\max}-1},
    \end{align*}
    with $d_{\max} := \max\limits_{i=1,\dotsc,m} d_i$ and $\#d_{\max} := \#\left\{i: d_i = d_{\max}\right\}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

