[Lemma 16 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $\tau\in \mathcal T$. Let $M\in \mathcal M$ be a minimal class. If at least one of the following properties is verified then $\tau\not\in \mathcal T^F$: 
\begin{itemize}	
\item[i)] $\tau$ is rooted at $x\in M$ 
and contains an edge going out from $M$;
\item[ii)] 
$\tau$ contains two or more edges going out from $M$;
\item[iii)] 
$\tau$ contains a slow edge connecting two points of $M$.
\end{itemize}

[Proposition 104 (Transport equation satisfied by $\fullymodquant{\tander^N}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Assume that $\wavearray = (\RRiemann,\LRiemann,v^2,v^3,\Ent)$ verify the geometric wave equations \eqref{E:VELOCITYWAVEEQUATION}--\eqref{E:ENTROPYWAVEEQUATION}. Then the following identity holds:
	\begin{align}   \begin{split}
		L \fullymodquant{\tander^N}  &  = 2 \frac{\Lunit \upmu}{\upmu}  \fullymodquant{\tander^N} - 2 \frac{\Lunit \upmu}{\upmu} \tander^N \mathfrak{X} +  \upmu [\Lunit,\tander^N] \mytr_{\gtorus} \upchi    \\
		& \ \ + [\Lunit,\tander^N] \mathfrak{X} + [\upmu,\tander^N] \Lunit \mytr_{\gtorus}\upchi + [\tander^N,\Lunit \upmu] \mytr_{\gtorus}\upchi   \\ 
		&\ \  - \tander^N(\upmu |\upchi|^2)  - \tander^N \mathfrak{A},
		\end{split}
	\end{align}
	where $\mathfrak{A}$ is the term on the right hand side of \eqref{E:RICCICONTRACTEDLANDL} and $\tander^N$ is the same differential operator every time it appears in \eqref{E:TRANSPORTEQUATIONFORFULLYMODIFIEDQUANTITY} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 32 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] For a local section $\mathfrak{v}$ of $A_U$ we use the notation from \Cref{setup:PF_PB}. 
Then, for every $x \in U$ for which the expressions are defined, 
\begin{align}
\left. \frac{\partial}{\partial t} \right|_{t=s} (\mathfrak{F}^{t,s}_\mathfrak{u})^*\mathfrak{v}(x) = \LB[\mathfrak{u}_s,\mathfrak{v}]_A(x). 
\end{align}

[Defn 10 ({\cite[Definition 2.2 and 2.9) of arXiv:2609.02561, 'NON-NEF LOCI IN MIXED CHARACTERISTIC'] {Keeler},\cite[Definition 3.1]{Ushiro}}]
Let $L$ be a line bundle on $X$.
We say that $L$ is:
\begin{enumerate}
\item $f$-ample
if there exists an affine open cover $\{ U_{\lambda} \}$ of $S$ such that $L|_{f^{-1}(U_{\lambda})}$ is ample for every $\lambda$;
\item $f$-nef
if $(L.C)\geq 0$ for every irreducible curve $C\subset X$ that is closed in $X$ and satisfies that $f(C)$ is a closed point of $S$;
\item $f$-semiample if $f^{*}f_{*}L^{\otimes m}\rightarrow L^{m}$ is surjective for some $m\in\Z_{>0}$;
\item $f$-$\Q$-effective if $f_{*}L^{\otimes m}\neq 0$ for some $m\in\Z_{>0}$;
\item $f$-big if $f_{*}(L^{\otimes m}\otimes A^{-1})\neq 0$
for some $m\in\Z_{>0}$ and some $f$-ample line bundle $A$.
\end{enumerate}
These notions extend to $\Q$-Cartier $\Q$-divisors $D$ by requiring that some positive multiple $L:=\sO_X(mD)$ satisfies the corresponding properties.

[Lemma 11 of arXiv:2606.30349, 'Attenuated Poisson Dirichlet approximations for divisibility configurations'] There exists a constant \(C>0\) such that, for all \(n\) sufficiently large,
\begin{align*}
\mathcal E_{A^o}[\mathcal X_n^{\mathrm{geo}},\mathcal X_n^0]
\le
C\frac{\log\log n}{\log n}.
\end{align*}
In particular,
\begin{align*}
\mathcal E_{A^o}[\mathcal X_n^{\mathrm{geo}},\mathcal X_n^0]
\le
C\frac{(\log\log n)^{\mathrm e-\frac32}}{\log n}.
\end{align*}

