[Theorem 4 (Graph sparsification~\protect{\cite[Thm.~1) of arXiv:2604.27119, '\Large Applied Random Matrix Theory\relatedversion'] {SS11:Graph-Sparsification}}]
Let $\mtx{L}$ be the Laplacian~\eqref{eqn:graph-laplacian} of a weighted graph
on $n$ vertices, and let $\widehat{\mtx{L}}$ be the Laplacian~\eqref{eqn:sparse-graph}
of a random sparse graph with at most $q$ edges.  With probability at least $1 - \delta$,
the random matrix $\widehat{\mtx{L}}$ is an $\eps$-approximation of $\mtx{L}$ in the sense~\eqref{eqn:graph-spectral-equiv}
provided that $q \geq 3 \eps^{-2} n \log(2n / \delta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2608.30578, 'Compactly Supported Solutions near a Nehari Critical Value'] Let $D\subset\mathbb R^N$ be a bounded Lipschitz domain and let
$F:D\times(0,+\infty)\to\mathbb R$ be a Carath\'eodory function such that,
for a.e. $x\in D$, the map
\begin{equation}
	s\mapsto\frac{F(x,s)}{s}

\end{equation}
is strictly decreasing on $(0,+\infty)$. Let
$U,V\in H^1(D)\cap L^\infty(D)$, with $U>0$, $V>0$ a.e. in $D$, and assume
the one-sided trace condition
\begin{equation}
	(U-V)^+\in H_0^1(D).

\end{equation}
Suppose that $U$ is a weak subsolution and $V$ a weak supersolution of
\begin{equation}
	-\Delta w=F(x,w)
	\qquad\hbox{in }D,

\end{equation}
that is,
\begin{align}
	\int_D\nabla U\cdot\nabla\varphi\,dx
	&\leq
	\int_DF(x,U)\varphi\,dx,
	\\
	\int_D\nabla V\cdot\nabla\varphi\,dx
	&\geq
	\int_DF(x,V)\varphi\,dx

\end{align}
for every non-negative
$\varphi\in H_0^1(D)\cap L^\infty(D)$ for which the right-hand sides are
finite. Assume, moreover, that
\begin{equation}
	F(\cdot,U),F(\cdot,V)\in L^1_{\rm loc}(D)

\end{equation}
and
\begin{equation}
	\left(
	\frac{|F(x,U)|}{U}
	+
	\frac{|F(x,V)|}{V}
	\right)
	(U^2-V^2)^+
	\in L^1(D).

\end{equation}
Then
\[
U\leq V
\qquad\hbox{a.e. in }D.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:mainSmallMu of arXiv:2608.24830, 'Motion helps the contact process: survival below\\ the percolation threshold on Poisson Br'] Fix $\mathfrak{b}$ and $\mathfrak{o}$. There are $C,c>0$, depending only on $\mathfrak{o},\mathfrak{b},r,d,\lambda$, such that
for all large $L$ and all $\mu>0$ with $\mu\beta\le\log2$,
\begin{equation}

  \mathbb{P}\big[(i,\tau)\text{ is acceptable}\big]\ \ge\
  1-\mu T_L-Ce^{-cL^{1/3}}-C L^{d}\exp\big\{-c\,\eta L^{1/3}\big\} .
\end{equation}
Consequently, for every $\alpha_0>0$ there is $L_0=L_0(\alpha_0,\lambda,\eta,r,d,\mathfrak{b},\mathfrak{o})$ such
that the right-hand side of (equation eq:cellbound of the paper) exceeds $1-e^{-\alpha_0}$ whenever $L\ge L_0$ and
\begin{equation}

  \mu\ \le\ \mu_*(L)\ :=\ \frac{\log 2}{\mathfrak{b} L^{2}} .
\end{equation}

[Proposition 36 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $x \in E$ and let $h>0$. The snake $X$ under the probability measure $\mathbb{N}_x(\cdot | T_h<\infty)$ can be expressed as the concatenation of the following two snakes.
    \begin{enumerate}
        \item $(\zeta(X_t), 0 \leq t \leq T_h(X))$ has the distribution $P_0^{\text{Bes}(3)}$. Conditional on $(\zeta(X_t), 0 \leq t \leq T_h(X))$ being given by $g \coloneqq (g_t)_{0 \leq t \leq T_h(g)}$, the process $(X_t, 0 \leq t \leq T_h(X))$ is a time-inhomogeneous snake with distribution $\mathbb{P}_{x|g}(\cdot)$.
        \item Conditional on $X_{T_h(X)}=w$ for an $E$-valued killed path $w$, the processes $(X_t, 0 \leq t \leq T_h(X))$ and $(X_{T_h(X)+t}, t \geq 0)$ are independent and the latter has law $\mathbb{P}_w(\cdot)$.
    \end{enumerate}
    \begin{proof}
        The proof follows almost immediately from Theorem \ref{theorem bivariate brownian snake} and the representation of the excursion measure $n$ for Brownian motion given in Definition \ref{definition brownian excursion}. The second part follows by the Markov property of the time-inhomogeneous snake $X$ conditionally given the contour process and of the decomposition $\mathbb{P}_w(\cdot) = \int_g P^R_{\zeta(w)}(dg)\mathbb{P}_{w|g}(\cdot)$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Skorokhod modulus) of arXiv:2607.12666, 'Sample-path Large deviations for \\Scheduled Arrival Processes with Unpunctuality'] For $\phi \in D([0,T])$ and $\delta>0$, define
\begin{equation}
w'(\phi,\delta,T)
:=
\inf_{\Pi}
\max_{1\le i\le m}
\sup_{s,t \in [t_{i-1}, t_i]} |\phi(t)-\phi(s)|,
\end{equation}
where the infimum is taken over all partitions
$
\Pi=\{0=t_0<t_1<\cdots<t_m=T\}
$
such that
$
t_i - t_{i-1} \ge \delta$, with $i=1,\dots,m.$

[Thm CM results kappa>0 of arXiv:2505.16093, 'Multiple chordal SLE($\kappa$) and quantum Calogero-Moser system'] The multiple chordal SLE($\kappa$) is described by the partition function $\mathcal{Z}(\boldsymbol{x})$, we have
\begin{equation}
\mathcal{L}_j \mathcal{Z}(\boldsymbol{x})= h \mathcal{Z}(\boldsymbol{x})   
\end{equation}
where $\mathcal{L}_j$ is the null vector differential operator:
\begin{equation}
\mathcal{L}_j=  \frac{\kappa}{2}\left(\frac{\partial}{\partial x_j}\right)^2 +\sum_{k \neq j}\left( \left(\frac{2}{x_k-x_j}\right) \frac{\partial}{\partial x_k}-\frac{6-\kappa}{\kappa}\frac{1}{\left(x_k-x_j\right)^2}\right)  
\end{equation}

\begin{itemize}


\item[(i)] We transform the partition function $\mathcal{Z}(\boldsymbol{x})$ into an eigenfunction of quantum Calogero-Moser system by multiplying Coulomb gas correlation $\Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{x})$ 

\begin{equation}
\tilde{\mathcal{Z}}(\boldsymbol{x})=\Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{x})\mathcal{Z}(\boldsymbol{x})   
\end{equation}

where $$\Phi_{r}(\boldsymbol{x})=\prod_{1 \leq j<k \leq n}\left(x_j-x_k\right)^{-2r}$$

 Then $\tilde{\mathcal{Z}}(\boldsymbol{x})$ satisfies 
 $$\left(\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}\right)  \tilde{\mathcal{Z}}(\boldsymbol{x}) = h\tilde{\mathcal{Z}}(\boldsymbol{x})$$  where the differential operator $\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}$ is given by

\begin{equation}
\begin{aligned}
\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}= & \frac{\kappa}{2} \partial_j^2- F_j \partial_j+\frac{1}{2\kappa} F_j^2-\frac{1}{2} F_j^{\prime} -\sum_{k \neq j}\left(f_{j k}\left(\partial_k-\frac{1}{\kappa} F_k\right)-\frac{6-\kappa}{2\kappa} f_{j k}^{\prime}\right) \\
&=\frac{\kappa}{2} \partial_j^2- \sum_{k} f_{jk}(\partial_j+\partial_k)\\
&-\frac{1}{\kappa}\left[\sum_k \sum_{l \neq k} f_{j k} f_{j l}-2\sum_{k\neq j} f_{j k}^2\right]- F_{j}'
\end{aligned}   
\end{equation}

 The sum of the null vector differential operators $\mathcal{L}=\sum \mathcal{L}_j$ is given by
\begin{equation}
\Phi_{-\frac{1}{\kappa}} \cdot \mathcal{L} \cdot \Phi_{\frac{1}{\kappa}}=\kappa H_n\left(\frac{8}{\kappa}\right)
\end{equation}

where $H_{n}(\beta)$ with $\beta=\frac{8}{\kappa}$ is  the quantum Calogero-Moser Hamiltonian
$$H_n(\beta)=\sum_{j=1}^n \frac{1}{2} \frac{\partial^2}{\partial x_j^2}-\frac{\beta(\beta-2)}{16} \sum_{1 \leq j<k \leq n} \frac{1}{\sin ^2\left(\frac{x_j-x_k}{2}\right)}
$$
\item[(ii)]
The commutation relation between growing two SLEs can be expressed as
$$[\mathcal{L}_j,\mathcal{L}_k]= \frac{1}{\sin^2(\frac{x_j-x_k}{2})}(\mathcal{L}_k-\mathcal{L}_j)$$
\end{itemize}
then
$$[\mathcal{L}_j,\mathcal{L}_k]\mathcal{Z}(\boldsymbol{x})= \frac{1}{\sin^2(\frac{x_j-x_k}{2})}(\mathcal{L}_k-\mathcal{L}_j)\mathcal{Z}(\boldsymbol{x})=0$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

