[Theorem 11 (Finite-Sample Bounds on the Expected Mahalanobis Error) of arXiv:2608.28198, 'Performative Privacy: When Differential Privacy Maximizes Utility'] Assume that the population is floored at one participant ($N_t \ge 1$). Conditioned on $N_{t-1}$, the expected squared Mahalanobis error of the private empirical mean $o_t$ satisfies:
\begin{align}
    \frac{\gamma^2 \mathrm{Tr}(\Sigma^{-1}) + d}{C_t(\gamma)N_{t-1}}
    \le \expectation \left[ \|o_t - \mu\|_{\Sigma^{-1}}^2 \;\middle|\; N_{t-1} \right]
    \le\, \frac{\gamma^2 \mathrm{Tr}(\Sigma^{-1}) + d}{C_t(\gamma)N_{t-1}} \cdot  \bigO\left(\frac{1}{1-q}\right)
\end{align}
where the asymptotic notation in the upper bound is particularly useful in the regime $q \rightarrow 1$.

[Proposition 19 of arXiv:2604.01852, 'The on/off Brownian snake'] In the setting of Corollary \ref{corollary range sbm in range oosbm}, for any $s>0$ we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. that
    \begin{equation*}
        \text{supp}(\mu_{\rm a}) \subseteq \text{supp}(\mathcal{Y}_s).
    \end{equation*}
    \begin{proof}
        We consider the on/off Brownian snake given in Definition \ref{definition oo snake} on probability space $(\Omega, \mathcal{F}, \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})})$. We assume that $\mu_{\rm a}$ is a non-zero measure otherwise the proposition is trivial.
        \par
        Let $x \in \text{supp}(\mu_{\rm a})$ and let $\varepsilon>0$. Let $B(x, \varepsilon/2)$ denote the ball of radius $\varepsilon/2$ and centre $x$, i.e. we have $B(x, \varepsilon/2) = \{y \in \mathbb{R}^d: \norm{y - x} < \varepsilon/2\}$. Then we have $\mu_{\rm a}(B(x, \varepsilon/2))>0$. Recall, for $y>0$ and an excursion $f$, that we define the hitting time of $y$ to be $T_y(f) = \inf\{t, f_t = y\}$ (and we set $T_y(f)$ to be infinity if $f$ does not hit $y$). Our aim is to partition the set $I$ into a collection of disjoint sets. For $k \in \mathbb{N}$ let $I_k$ be defined by
        \begin{equation*}
            I_k \coloneqq \{ i  \in I: \hspace{0.25cm} T_{1/k}(f^i) < \infty = T_{1/(k-1)}(f^i)\}.
        \end{equation*}
        We note that for $k \in \mathbb{N}$ that $n(\{f: T_{1/k}(f) < \infty = T_{1/(k-1)}(f)\}) = 1/2$. As $\sum_{i \in I}\delta_{f^i}$ is a Poisson random measure with intensity measure $(\norm{\mu_{\rm d}} + \norm{\mu_{\rm a}})n(\cdot)$ and the sets $I_k$ are disjoint, we have that $|I_k|$, $k \in \mathbb{N}$, are independent Poisson random variables each with mean $(\norm{\mu_{\rm d}} + \norm{\mu_{\rm a}})/2$.
        \par
        For a compound Poisson subordinator with drift $S$, let $\tau(S) = \inf\{u: S_{u-} \neq S_u\}$ be the time of the first discontinuity of $S$ and let $\Delta(S) = S_{\tau(S)} - S_{\tau(S)-}$ be the size of this discontinuity. We can then consider the sets $J_k$, $k \in \mathbb{N}$ given by
        \begin{equation*}
            J_k = \Big\{ i \in I_k: \hspace{0.25cm} s_i = 0, \hspace{0.25cm} \norm{b_i - x} < \frac{\varepsilon}{2}, \hspace{0.25cm} \tau(v^i_{T_{1/k}}) \in (0,1/2k), \hspace{0.25cm} \Delta(v^i_{T_{1/k}})>s \Big\}.
        \end{equation*}
        By the independence of the marking we have that $|J_k|$, $k \in \mathbb{N}$, are independent Poisson random variables with means given by
        \begin{equation*}
            \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})}(|J_k|) = \frac{1}{2}\mu_{\rm a}(B(x, \varepsilon/2))(1-e^{-c/2k})(e^{-\Tilde{c}s})
            \geq \frac{c}{4k}\mu_{\rm a}(B(x, \varepsilon/2))e^{-\Tilde{c}s}e^{-c/2},
        \end{equation*}
        where, for the inequality, we have used the fact that for $z<c/2$ that $1-e^{-z} \geq ze^{-c/2}$. We consider subsets of the sets $J_k$, $k \in \mathbb{N}$, that relate to the following probabilities. For a $d$-dimensional Brownian motion $(W(t))_{t \geq 0}$ started at the origin on probability space $(\Omega, \mathcal{F}, P)$, for $k \in \mathbb{N}$, we have
        \begin{equation*}
            P\Big(\sup_{0 \leq s \leq 1/2k} \norm{W(s)} \leq \varepsilon/2\Big) \geq P\Big(\sup_{0 \leq s \leq 1/2} \norm{W(s)} \leq \varepsilon/2\Big) > 0.
        \end{equation*}
        We now consider a further restriction of the sets $J_k$, $k \in \mathbb{N}$, given by 
        \begin{equation*}
            J'_k \coloneqq \Big\{i \in J_k: \hspace{0.25cm} \sup_{u \in [0, 1/k]}\big\{\norm{w^i_{T_{1/k}}(u) - x}\big\} < \varepsilon\Big\}.
        \end{equation*}
        We again note that by the independence of the marking that the $|J'_k|$, $k \in \mathbb{N}$, are independent Poisson random variables with means that satisfy
        \begin{equation*}
            \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})}(|J'_k|) \geq P\Big(\sup_{0 \leq s \leq 1/2k} \norm{W(s)} \leq \varepsilon/2\Big)\mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})}(|J_k|) \geq P\Big(\sup_{0 \leq s \leq 1/2} \norm{W(s)} \leq \var (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem set of measures tight thm of arXiv:2411.04631, 'Existence of Martingale Solutions to Stochastic Constrained Heat Equation'] Let $\left\{\mathcal{L}(u_{n}): n\in \mathbf{N}\right\}$ be a set of measures, then this set is tight on $(\mathcal{Y}_{T}, \mathcal{F}))$. Here
\begin{align*}
\mathcal{Y}_{T}=C{([0,T],\mathcal{L}^{2});\mathcal{H})}\cup L_{w}^2([0,T];D(\Delta))\cup \mathcal{L}^{2}([0,T];\mathcal{V})\cup \mathcal{C}([0,T],\mathcal{V}_{w}).
\end{align*}

