[Prop LT-1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Given $\eta \in (0,\frac{1}{2}-\gamma)$, for each $\theta \geq 0$ there exists a constant $C=C(\theta,\gamma) > 0$ such~that, if $k$ is sufficiently large, given any integer $j > 1$, $n \geq k$ and $\widetilde{x} \in {\rm D}_n$ with $\overline{{\rm B}^+[\widetilde{x};j]}\subseteq {\rm D}_n$, we have that 
	\begin{equation}

 {\rm e}^{-2\sqrt{2}\widehat{v}-\frac{\widehat{v}^2}{k+jk^\gamma}-Ck^\gamma} \leq \mathbb{P} \bigg( \min_{x \in {\rm B}^-[\widetilde{x};j-1]}L_t(x) \leq \theta \,\Big|\, \sqrt{\widehat{N}_t[\widetilde{x};j]} \geq v \,; 
\mathcal F[\widetilde{x};j]\bigg) \leq  {\rm e}^{- 2\sqrt{2}\widehat{v}+Ck^\gamma}
\end{equation} uniformly over all $t >0$ and $v \in \mathcal R^\eta_k(j)$, where above we abbreviate $\widehat{v}:=v-\sqrt{2}(k+(j-1)k^\gamma)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2606.22526, 'The conditional expectation of the product of the first $n-1$ Hermite polynomials in a mul'] Assuming the sequence of random variables $X_{1},\ldots,X_{n}$ form a Markov
chain with zero expectations, $f_{N}$ as its marginal distributions and
(\ref{MCN}) as conditional distribution of $X_{j+1}|X_{j}=y$ the conditional
expectoration $C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=E\left(  H_{k}
(X_{j})|X_{n},\ldots,X_{j+1}=z,X_{j-1}=y,\ldots,X_{1}\right)  $ takes one of
the following equivalent forms
\begin{gather}
C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=\sum_{s=0}^{k}\binom{k}{s}\rho
_{j-1,j}^{k-s}\left(  1-\rho_{j-1,j}^{2}\right)  ^{s}\rho_{j,j+1}^{s}
H_{k-s}(y)\\
\times H_{s}\left(  \frac{z-\rho_{j-1,j}\rho_{j,j+1}y}{\sqrt{1-\left(
\rho_{j-1,j}\rho_{j,j+1}\right)  ^{2}}}\right)  /\left(  1-\left(
\rho_{j-1,j}\rho_{j,j+1}\right)  ^{2}\right)  ^{s/2},\nonumber
\end{gather}
\begin{gather}
C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=\frac{1}{\left(  1-\left(  \rho
_{j-1,j}\rho_{j,j+1}\right)  ^{2}\right)  ^{k}}\sum_{s=0}^{\left\lfloor
k/2\right\rfloor }(-1)^{s}\binom{k}{2s}\binom{2s}{s}s!\nonumber\\
\times\left(  \rho_{j-1,j}\rho_{j,j+1}\right)  ^{2s}\left(  \left(
1-\rho_{j-1,j}^{2}\right)  \left(  1-\rho_{j,j+1}^{2}\right)  \right)  ^{s}\\
\times\sum_{m=0}^{k-2s}\binom{k-2s}{m}\left(  1-\rho_{j-1,j}^{2}\right)
^{m}\left(  1-\rho_{j,j+1}^{2}\right)  ^{k-2s-m}\rho_{j-1,j}^{k-2s-m}
\rho_{j,j+1}^{m}H_{m}(z)H_{k-2s-m}(y).\nonumber
\end{gather}
\begin{gather}
C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=\left(  \frac{\rho_{j-1,j}^{2}
+\rho_{j,j+1}^{2}-2\rho_{j-1,j}^{2}\rho_{j,j+1}^{2}}{1-\rho_{j-1,j}^{2}
\rho_{j,j+1}^{2}}\right)  ^{k/2}\\
\times H_{k}\left(  \frac{y\rho_{j-1,j}\left(  1-\rho_{j,j+1}^{2}\right)
+z\rho_{j,j+1}\left(  1-\rho_{j-1,j}^{2}\right)  }{\sqrt{\left(
1-\rho_{j-1,j}^{2}\rho_{j,j+1}^{2}\right)  \left(  \rho_{j-1,j}^{2}
+\rho_{j,j+1}^{2}-2\rho_{j-1,j}^{2}\rho_{j,j+1}^{2}\right)  }}\right)
.\nonumber
\end{gather} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:negative-potential-results of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] For $-2<\beta<0$,
    \begin{equation}
            U_\beta(\mathrm{d} x)
            =\eta_\beta\delta_0(\mathrm{d} x)
            +\left[
            \frac1{\mu_\beta}
            +\sum_{k\ge1}
            \frac{e^{s_{\beta,k}x}}{\phi_\beta'(s_{\beta,k})}
            \right]\mathrm{d} x.
    \end{equation}
    The residues $1/\phi_\beta'(s_{\beta,k})$ are positive, and the series
    converges locally uniformly for $x>0$.  Equivalently, for $\textnormal{Re} z>0$,
    \begin{equation}
            \frac1{\phi_\beta(z)}
            =\eta_\beta+\frac1{\mu_\beta z}
            +\sum_{k\ge1}
            \frac1{\phi_\beta'(s_{\beta,k})(z-s_{\beta,k})}.
    \end{equation}
    In particular,
    \begin{equation}
            \eta_\beta
            -\sum_{k\ge1}
            \frac1{s_{\beta,k}\phi_\beta'(s_{\beta,k})}
            =-\frac{\phi_\beta''(0)}{2\mu_\beta^2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

