[Lem 210 (quenched first moment bounds on $\tilde{Q}$ and $\tilde{Q}^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] With $\tilde{Q}$ the approximation of $Q$ given by Definition~\ref{d:tQ}, we have the quenched bounds
    \begin{align*}
    &\max\bigg\{
    \frac{\bE\Delta\tilde{Q}^{\RomI}(q_d)}{(\delta_d)^2 p'(q_d)},
    \frac{\bE\Delta\tilde{Q}^{\RomII}(q_d)}{\delta_d p(q_d)}
    =\bE \vvv^\trunc(q_d), \\
    &\qquad\qquad\qquad
    \frac{\bE|\Delta\tilde{Q}^{\RomII,\RomIII}|}
    {\delta_d [p(q_d) q_d p'(q_d)]^{1/2}}
    =\bE |\uuu^\trunc(q_d)|,
    \frac{\bE\Delta\tilde{Q}^{\Ising}(q_d)}{\delta_d}
    =\bE \www^\trunc(q_d)
    \bigg\}
    \le (\MAX_N)^2\,,
    \end{align*}
with $\MAX_N$ as in \eqref{e:MAX.N}. The same bounds hold for $\tilde{Q}^\frozen$, $\vvv^\frozen$, $\uuu^\frozen$, $\www^\frozen$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 29 (Karamata's theorem, direct half, \protect{\autocite[section 1.6) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] {BinghamGoldieTeugels1987RegularVariation}}]

Let \(\ell\) be a slowly varying function. There is \(A>0\) such that
\(\ell\) is locally bounded on \([A,+\infty)\), hence we can integrate
and we have the following estimates:

\begin{itemize}
\item
  For \(\beta > -1\),

  \begin{equation*}{
  \int_{A}^x t^{\beta}\ell(t)\dd t \sim_{x \to +\infty} \frac{x^{\beta+1}}{\beta+1} \ell(x).
  }\end{equation*}
\item
  For \(\beta < -1\),

  \begin{equation*}{
  \int_{x}^{+\infty} t^{\beta}\ell(t) \dd t \sim_{x \to +\infty} \frac{x^{\beta+1}}{-\beta-1}\ell(x).
  }\end{equation*}
\item
  For \(\beta=-1\), the function
  \(x \mapsto \int_{A}^x \frac{\ell(t)}{t}\dd t\) is slowly varying and
  such that

  \begin{equation*}{
  \frac{1}{\ell(x)}\int_{A}^x \frac{\ell(t)}{t}\dd t \xrightarrow[x \to +\infty]{} 0. 
  }\end{equation*}

  Moreover if \(\int_{A}^{+\infty} \frac{\ell(t)}{t}\dd t <+\infty\)
  then the function
  \(x \mapsto \int_{x}^{+\infty} \frac{\ell(t)}{t}\dd t\) is also slowly
  varying and such that

  \begin{equation*}{
  \frac{1}{\ell(x)}\int_{x}^{+\infty} \frac{\ell(t)}{t}\dd t \xrightarrow[x \to +\infty]{} +\infty.
  }\end{equation*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 40 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] There exist constants $\varepsilon > 0$ and $C>1$ 
                such that the following holds whenever $q \in [0,\varepsilon]$. Fix a point $z_0 \in {\mathfrak{L}}_{q}$, and define $\widehat{\mathcal{H}}_q = \widehat{\mathcal{H}}_{q;1,1,1}$ as in \eqref{e:funzrescaled}.
         There exist $a,b,c\in [1-Cq, 1+Cq]$  and $z_1 \in \mathfrak{L}_{ {a}, {b}, {c}}$ such that, defining 
                  \begin{flalign}

                    \widecheck \cH_{a,b,c}(\hat z)=\mathfrak{d}_{z_0}^{-1/2} \mathfrak{e}_{z_0;q}^{-3/2}  \cH_{a,b,c}(z_1+(\mathfrak{d}_{z_0} \mathfrak{e}_{z_0;q})^{1/2} \bu_{z_0;q} \hat x + (\mathfrak{d}_{z_0} \mathfrak{e}_{z_0;q})\bw_{z_0;q} \hat y ), \quad \hat z=(\hat x,\hat y),
                  \end{flalign}
                  we have 
                  \begin{equation}
                                 \nabla \widehat{\mathcal{H}}_{q} (0,0) = \nabla \widecheck{\mathcal{H}}_{a,b,c} (0,0), 
                  \qquad D^2\widecheck{\mathcal{H}}_{a,b,c}(0,0)-D^2\widehat{\mathcal{H}}_{q}(0,0) \ge C^{-1} \mathfrak{d}_{z_0} q \cdot \Id.

                                 \end{equation}
                                 Moreover, for every $B\ge 0$ there exists $C'>1$ such that 
		 for any $\gamma$ with $1 \le |\gamma| \le B$ we have 
		\begin{flalign*}
			\big| \partial_{\gamma} \widehat{\mathcal{H}}_{q} (0,0) - \partial_{\gamma} \widecheck{\mathcal{H}}_{a,b,c} (0,0) \big| \le C' \mathfrak{d}_{z_0} q.
		\end{flalign*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop martingalerenormalisee of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Under the \hyperlink{ren}{renormalized setting}, let $\varphi \in \mathcal{C}^{1,1}_{\omega}(\mathbb{R}^{+} \times \mathbb{R}^{*}_{+})$ and $K \in \mathbb{N}^{*}$. Then the process $(\langle \mu^{K}_{t}, \varphi_{t} \rangle)_{t \geq 0}$ is a semi-martingale, with for all $t \geq 0$, a finite variation part given by
\begin{align*}
V^{K}_{\varphi,t} := & \hspace{0.1 cm} \langle \mu^{K}_{0}, \varphi_{0} \rangle + \displaystyle{\int_{0}^{t}} \langle \mu^{K}_{s}, \Phi_{s}(R^{K}_{s},.) \rangle \mathrm{d}s - \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+} }} d(x)\varphi_{s}(x) \mu^{K}_{s}(\mathrm{d}x) \mathrm{d}s \\
    &  + \displaystyle{\int_{0}^{t}}\int_{\mathbb{R}^{*}_{+} } b(x)\bigg( \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x)\bigg) \mu^{K}_{s}(\mathrm{d}x) \mathrm{d}s,
\end{align*}
with $\Phi$ associated to $\varphi$ as in (equation eq:Phidef of the paper), and a square-integrable martingale part $\heartsuit^{K}_{\varphi,t} := \langle \mu^{K}_{t}, \varphi_{t} \rangle -V^{K}_{\varphi,t} $ whose predictable quadratic variation is given by
\begin{align*}
\langle \heartsuit^{K}_{\varphi} \rangle_{t} & = \dfrac{1}{K} \Bigg( \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}b(x)\bigg[ \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x) \bigg]^{2} \mu^{K}_{s}(\mathrm{d}x) \mathrm{d}s \\
& \hspace{8cm} + \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}d(x)\varphi_{s}^{2}(x) \mu^{K}_{s}(\mathrm{d}x) \mathrm{d}s\Bigg).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop loiderho2 of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] For the Skorokhod $J_1$-topology, when $i \rightarrow +\infty$
    \begin{align}
    (\frac{{\rho^{\mathcal{Z}}_{\lfloor t i \rfloor }}}{i^{2}},t) \xrightarrow{\mathcal{L}} (V_{1/2}(t),t),
    \end{align}
 $V_{1/2}(t)$ is 1/2-stable Lévy subordinator with Lévy triple $(0,0,v_{1/2})$ with $v_{1/2}(dt)=  {\mathbf{c_{_2}}} t^{-3/2}\mathds{1}_{t>0}dt$ and recall $ {\mathbf{c_{_2}}}=8/ \sqrt{\pi}$.

