[Lemma 20 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $K' = (K'_n)$ be a sequence of random graphs with vertex set $[n]$.
    \begin{itemize}
         \item If $K \simeq_{n \to +\infty} K'$ then $SOV(K) = SOV(K')$.
        \item If $K \subseteq K'$ whp then $SOV(K) \leq SOV(K')$.
    \end{itemize}

[Lem H comp of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Assume $\hat{d}_{\mathrm{s}} > 2$.
  For each $a > 0$ and $t > 0$, set
  \begin{equation}
    F(a,t)
    \coloneqq
    \left\{
      x \in \supp \Pi_t \,\middle|\,
      \varlimsup_{r \downarrow 0}
      \frac{\Pi_t(B(x,r))}{\Psi_{\mathrm{cp}}(r)}
      <a
    \right\}.
  \end{equation}
  Then, for all sufficiently small $a>0$,
  $\mathcal{H}_{\Psi_{\mathrm{cp}}}(F(a,t))=0$ for all $t > 0$, $\hat{P}_{\bm{\rho}}$-a.s.

