[Theorem 10 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] For each~$t>0$, the weak limit \eqref{E:1.18} exists and defines an a.s.-finite random Borel measure~$Z_t$ on~$[0,1]$. Moreover, there exists a Borel probability measure~$\nu$ on~$\R^\N$ such that for all~$t>0$, all~$f\in\Cloc^+$ and all sequences $\{k_n\}_{n\in\N}$ with $k_n\to\infty$ and $n-k_n\to\infty$, 
\begin{equation}

\begin{aligned}
E^\varrho\bigl(&\texte^{-\langle\zeta_{n,k_n}^{(t)},f\rangle}\bigr)
\\
&\,\,\,\underset{n\to\infty}\longrightarrow\,\, \E\biggl(\exp\Bigl\{-\int Z_t(\textd x)\otimes\texte^{-2\slb\, h}\textd h\otimes\nu(\textd\phi)(1-\texte^{-f(x,h,\phi)})\Bigr\}\biggr),
\end{aligned}
\end{equation}
where the expectation on the right is with respect to the law of~$Z_t$. The measure $Z_t$ obeys \eqref{E:1.13},
$\nu$ is concentrated on~$\{\phi_0=0\}\cap
\bigcap_{x\in\N\smallsetminus \{0\}}\{\phi_x>0\}$ and the set $\{x\in\N\colon \phi_x\le a\}$ is finite~$\nu$-a.s.\ for each~$a>0$. A.e.\ sample of~$Z_t$ is diffuse (i.e., does not charge singletons). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Expected Population Evolution) of arXiv:2608.28198, 'Performative Privacy: When Differential Privacy Maximizes Utility'] We define the \textit{marginal leakage probability}, $p^{(t-1)}_\tau$, as the expected fraction of the population that breaches the privacy threshold $\tau$ at round $t-1$, i.e $p^{(t-1)}_{\tau} = \mathbb{E}(\mathds{1}(\Lambda(o_{t-1}|z) > \tau)$. 
Letting $\bar{z}$ denote the record subjected to the clipping and $\mu_{\bar z}$ denote the sample mean of clipped vectors, the marginal leakage probability evaluates to:
\begin{align}
p^{(t-1)}_\tau
&=
\bigint_{\mathbb{R}^{dN_{t-1}}}
\left[
1-\Phi\!\left(
\frac{\tau (N_{t-1}-1)\gamma}
{s\sqrt{N_{t-1}}}
-
\frac{s\sqrt{N_{t-1}}}
{2(N_{t-1}-1)\gamma}
\right)
\right]
\prod_{j=1}^{N_{t-1}} f_{\mathcal{N}}(z_j)\,
d z_{1:N_{t-1}},
\end{align}
Where $s\triangleq\|\bar z_1-\mu_{\bar z}\|_2$ and $d z_{1:N_{t-1}} \triangleq d z_1 \cdot\dots d {z_{N_{t-1}}}$.Under assumption \ref{assump:normal}, the expected population size at round $t$ in \Cref{alg:memoryless_dp}, is given by:
\begin{equation}
    \expectation[N_t \mid N_{t-1}] = N_{t-1} \Big( 1 + r - (q + r) p^{(t-1)}_\tau \Big)
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 31 of arXiv:2608.30752, '2608.30752'] Along every unit-speed Teichm\"uller geodesic,
\begin{equation}
  |E'(t)|\le2E(t),
  \qquad
  \left|\frac{d}{dt}\log E(t)\right|\le2.

\end{equation}

[Lemma lem:root of arXiv:2609.00889, 'Dominant-Degree Conditions for Ramsey--Tur\'an Factors of Non-Directed Cycle Orientations'] For $D(z,Q,R)$, the following hold.
\begin{enumerate}
 \item If $\Delta^+(Q)\le1$, then there is no $C_4^{\mathrm{ad}}$ containing the vertex $z$.
 \item If $s\ge3$ and the matching number of the underlying graph of $Q$ is at most $1$, then there is no $C_{2s}^{\mathrm{ad}}$ containing the vertex $z$.
\end{enumerate}

[Theorem theorem_localized_eigenvector_localization of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under (main_assm of the paper), given any $k\in[\![{1,DN}]\!]$, suppose there exists a positive constant $\varepsilon_A$ such that
\begin{equation}
\|A\|_{\text{\rm{HS}}}\le N^{1/3-\varepsilon_A}{\mathfrak{r}}\left({k}\right)^{-1/3} . 
\end{equation}
Then, for any small constant $\varepsilon\in(0,2{\varepsilon}_A)$, there exists a constant $\varepsilon_0=\varepsilon_0\left({\varepsilon}\right)>0$ such that
\begin{equation}\nonumber
    \begin{aligned}
        \mathbb P\left(\max_{a=1}^D \|E_a{\bf v}_k\|^2 \le 1 - N^{-2/3+\varepsilon}{\mathfrak{r}}\left({k}\right)^{2/3}\left\lVert A \right\rVert_{\text{\rm{HS}}}^2\right)\le N^{-\varepsilon_0}.
    \end{aligned}
\end{equation}
As a consequence, it implies that 
\begin{equation}
\mathbb P\left(\max_{a=1}^D \|E_a{\bf v}_k\|^2 \le 1 - N^{-c}\right)\le N^{-c}
\end{equation}
for a constant $c>0$ depending on ${\varepsilon}_A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Prop ident 2pt corr of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] We have
\begin{multline*}
\lim_{\max(\varepsilon_1,\varepsilon_2)\to 0}
\mathbb{E}
\big[
\CR(z_1,\widehat{D}_{r_0}(z_1))^{-1/8}
\CR(z_2,\widehat{D}_{r_0}(z_2))^{-1/8}
\1_{E_{r_0,\varepsilon_1,\varepsilon_2}}
\1_{\{\mathbb{D}(z_j,r(\varepsilon_j))
\subset
\widehat{D}_{r_0}(z_j), j\in\{1,2\}\}}
\big]
\\
=\mathbb{E}
\big[
\CR(z_1,\widehat{D}_{r_0}(z_1))^{-1/8}
\CR(z_2,\widehat{D}_{r_0}(z_2))^{-1/8}
\1_{E_{r_0}}
\big]
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:exact-point-count of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:dereg-defects}
The point-incoherent exact count is
\begin{equation}
 \widehat{\mathscr C}_{N,L}^J(V)
 :=\mathbb E\sum_{\substack{x:\nabla_SH_N^J(\sqrt N x)=0\\x\in D_{N,L}}}
 e^{-NV(h_N^J(x))}.
\end{equation}
Whenever this quantity is finite and positive, put
\begin{align}
 \widehat Q_{N,L}
 &:=
 \frac1N\log\widehat{\mathscr C}_{N,L}^J(V),\\
 \widehat P_{N,L}(\varepsilon,\eta)
 &:=
 \frac1N\log
 \mathbb E\widehat\mathcal Z_{N,L}^J(V,\varepsilon,\ell_\eta).
\end{align}
For a nonnegative function \(a(\varepsilon,\eta)\), write
\[
 \liminf_{(\varepsilon,\eta)\to(0,0)}a(\varepsilon,\eta)
 :=\lim_{\delta\downarrow0}
 \inf_{0<\varepsilon,\eta<\delta}a(\varepsilon,\eta).
\]
Define the upper and lower transfer defects
\begin{align}
 \delta_{L,\mathrm{dr}}^{J,\mathrm{up}}(V)
 &:=
 \liminf_{(\varepsilon,\eta)\to(0,0)}
 \limsup_{N\to\infty}
 [\widehat Q_{N,L}-\widehat P_{N,L}(\varepsilon,\eta)]_+,
 \\
 \delta_{L,\mathrm{dr}}^{J,\mathrm{low}}(V)
 &:=
 \liminf_{(\varepsilon,\eta)\to(0,0)}
 \limsup_{N\to\infty}
 [\widehat P_{N,L}(\varepsilon,\eta)-\widehat Q_{N,L}]_+.

\end{align}
Thus only one favorable vanishing-regularizer test sequence is required
in each direction, and the two sequences may differ.  They require
neither a common test sequence nor an iterated absolute comparison of
the uncut pressures.  The frame-slice quantities in
(prop:primitive-dereg of the paper) give checkable upper bounds for them.

[Definition def_balanced of arXiv:2507.06522, 'Balanced multi-species spin glasses'] We say the multi-species parameter pair $(\vc\Delta,\vc\lambda)$ is \textit{balanced} if
\begin{equation}  \tag{H3} 
\begin{split}
\Delta^2_{t} \quad &\text{does not depend on $t\in\mathscr{S}$ for $p=1$, and} \\
\sum_{s_2,\dots,s_p\in\mathscr{S}}\Delta^2_{t,s_2,\dots,s_p}\lambda_{s_2}\cdots\lambda_{s_p} \quad &\text{does not depend on $t\in\mathscr{S}$, for every $p\geqslant2$.}
\end{split}
\end{equation}

[Definition DUFJ-INT-SJ-B of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] A random function $v\left( {x} \right)$ is said to be inertial-range intermittent, if for two positive exponents ${p_1} > {p_2}$, there exists an increasing function $\mathfrak{h}_2\left( r \right)$ such that
\begin{equation}
\frac{{{{\left\| {v\left( { \cdot  + l\mathbf{n}} \right) - v\left(  \cdot  \right)} \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| {v\left( { \cdot  + l\mathbf{n}} \right) - v\left(  \cdot  \right)} \right\|}_{{L^{{p_2}}}}}}} \sim {\mathfrak{h}_2}\left( {r} \right) \to  \infty , \ \  \forall \, l \in \left[ {{l_D},{l_I}} \right] , \  \mbox{as}\ r \to  \infty , \ \mathbb{P}\mbox{-a.s.} 
\end{equation}

[Lemma 19 of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] For $\Pp$-a.e.~$\omega$,
\begin{equation*}     \max_{0\le k<b^n}\abs{\xi_{n,k}(\omega)}\le C(\omega)n     \qquad\text{for all sufficiently large }n.                 
\end{equation*}

[Definition 79 of arXiv:2609.03875, 'Measure theory without infinities'] We say that a nonempty set $\mathcal Q$ is an $\alpha$-class if it satisfies the following conditions:
  \begin{enumerate}
  \item[(1)] If $A,B\in \mathcal Q$ and $A\cap B=\varnothing$, then $A\cup B\in \mathcal Q$.
  \item[(2)] If $A,B\in \mathcal Q$ and $B\subset A$, then $A\setminus B\in \mathcal Q$.
  \item[(3)] If $\mb A\colon\N\to\mathcal{Q}$ is a decreasing sequence of sets, then $\bigcap_{n\in\N} \mb A(n)\in \mathcal Q$.
  \end{enumerate}

[Thm smasympexOSp of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] There is a universal constant $C>0$, and a compactly supported 
distribution $\mu_k$ for every $k\in\mathbb{Z}_+$, so that the following 
hold. Fix any $h\in C^\infty(\mathbb{R})$, and let
$f(\theta):= h(K\cos\theta)$. Then
\begin{multline*}
	\left| \mathbf{E}[\mathop{\textnormal{tr}} h(X^N)]- \sum_{k=0}^{m-1} \frac{\mu_k(h)}{N^k} 
	\right| 
	~\vee~
	\left| \mathbf{E}[\mathop{\textnormal{tr}} h(Y^N)]- \sum_{k=0}^{m-1} \frac{\mu_k(h)}{(-2N)^k} 
	\right| 
\\
	\leq 
	\frac{(C\tilde q_0)^m}{u^mN^m}
	\|f^{(m'+1)}\|_{[0,2\pi]} 
	+\frac{(C\tilde q_0)^{2m}}{m!\, u^{2m} N^m} 
	\|f^{(2m'+1)}\|_{[0,2\pi]} 
\end{multline*}
for all $m, N\in \mathbb{N}$ and $u\in (0,1)$, where
$m':=\lceil (1+u)m\rceil$ and $\tilde q_0 := q_0(1+\log q_0)$.

