[Proposition 23 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $B, C \in \widehat{\Bcal}(S)$ be disjoint such that $\pbb(\nu(B) = 0) < 1$ and $\pbb(\nu(C) = 0) < 1$, and let $f_B$ and $f_C$ be sampling functions for $\xi$ on $B$ and $C$, respectively. Then, for some $p \in (0,1)$,
    \begin{align*}
        f_{B \cup C}(x) \coloneqq \begin{cases}
            f_B \left( \frac{x}{p}\right), &\text{for } x \in [0, p) \\
            f_C \left( \frac{x - p}{1 - p} \right), &\text{for } x \in [p, 1]
        \end{cases}
    \end{align*}
    is a sampling function for $\xi$ on $B \cup C$.

[Prop prop2 of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},P,T)$  be an ergodic measure preserving system, where $(\Omega,\mathcal{F})$ is a standard measurable space. Then the following two statements are equivalent:
	\begin{longlist}
		\item there exists $B\in\mathcal{F}$ with $P(B)>0$ such that for any $C\in\mathcal{F}$ with $C\subset B$,
		\begin{equation}
			\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P^{1/2}(B\cap T^{-i}C)=P^{1/2}(B)P(C);
		\end{equation}
		\item $P$ is a periodic probability, i.e., there exist $r\in\mathbb{N}$ and distinct points $\omega_1,\ldots,\omega_r\in\Omega$ such that $P(\{\omega_i\})=\frac{1}{r}$, $i=1,2,\ldots,r$.
	\end{longlist}
	In this case, $r=\frac{1}{P(B)}\in\mathbb{N}$.

[Theorem thm:optimalliftgns of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{M}$ be a finite-dimensional von Neumann algebra. For a symmetric QMS generator $\mathcal{L}_O$ satisfying the $\kappa$-intertwining condition for $\kappa \in \mathbb{R}$, there exists a second-order lift $\mathcal{L}$ with convergence rate:
    \begin{align*}
         \Omega\left(\frac{\sqrt{\lambda_O}}{  1 +  \sqrt{\max\{0,-\kappa\}\lambda_O^{-1}}}\right) \le \nu(\mathcal{L}) \le \mathcal{O}\left(\sqrt{\lambda_O}\right)\,.
    \end{align*}
    Such lift is optimal if $\max\{0,-\kappa\}\lambda_O^{-1} = \mathcal{O}(1)$, which always holds if $\kappa \ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 68 of arXiv:2601.16377, '2601.16377'] Under Assumption~\ref{Assumptions_Theta}, there exists $C > 0$ depending only on the constants in the assumptions, such that for any $\boldsymbol{\ell} \in \amsmathbb{W}_\N$, there exists an absolutely continuous nonnegative measure $\tilde{\mu}_{\N}$ with the following properties:
\begin{itemize}
\item $\widetilde{\mu}_{\N} \in \mathscr{P}_{\star}$.
\item $|\widetilde{\mu}_{\N} - \mu_{\N}^*|(\amsmathbb{R}) \leq \frac{C}{\N}$.
\item $\widetilde{\mu}_{\N}$ and $\mu_{\N}^*$ coincide outside $[-C,C]$.
\end{itemize}

[Prop 13 (Variational identity) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $a > 0$ and $c > 0$. Then $X \lecx c\Lap$ holds for every $X \in \SE(1,a)$ if and only if
\begin{align*}
    p(1-p)\,\nu_{\max}(p,a) \le c\,\Lambda(p)
    \qquad \text{for all } p \in (0, 1/2],
\end{align*}
with $\Lambda$ as in \eqref{eqn:Lambda}. Consequently,
\begin{align}
    c^{\SE}(1, a) = \sup_{p \in (0,1/2]} R(p,a),
    \qquad
    R(p,a) \coloneqq \frac{(1-p)\,\nu_{\max}(p,a)}{1 + \log\frac{1}{2p}},

\end{align}
and the infimum in \eqref{eqn:defc} is a minimum: $c^{\SE}(1,a)$ is itself admissible.

