body:
[Thm 85 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For the generation $m=0$ and $n\geq 1$ odd,
\begin{displaymath}
\psi^{\rm gen}_{n,m=0} = 
\sum_{j=0}^{+\infty}
\Big(
\sigma_{m=0,j}
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big),
\end{displaymath}
where the infinite sum in $j$ converges in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.
Moreover,
\begin{displaymath}
\E\Big[\Vert \psi^{\rm gen}_{n,m=0}\Vert_{H^{-\eta}(\C)}^{2}\Big] = 
\sum_{j=0}^{+\infty}
\E\Big[
\Big\Vert
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big].
\end{displaymath}
For $n\geq 2$ even,
\begin{multline*}
\psi^{\rm gen}_{n,m=0} =
\\
\sum_{j=0}^{+\infty}
\Big(
\Big(
\sum_{0\leq k < \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big)
+
(-1)^{n/2} \dfrac{n!}{2^{n/2} (n/2)! }
\ind_{\inter(\Gamma_{m=0,j})}
V_{A^{\rm gen}_{0}}^{n/2}
\Big).
\end{multline*}
For the generations $m\geq 1$ and $n\geq 1$ odd,
\begin{multline*}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
=
\\
\sum_{j=0}^{+\infty}
\Big(
\sigma_{m,j}
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,m,j}
\Big),
\end{multline*}
and
\begin{multline*}
\E\Big[
\Big\Vert
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
=
\\
\sum_{j=0}^{+\infty}
\E\Big[
\Big\Vert
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,m,j}
\Big)
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big].
\end{multline*}
For $n\geq 2$ even,
\begin{multline*}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
=
\\
\sum_{j=0}^{+\infty}
\Big(
\Big(
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,j}
\Big)
+
\ind_{\inter(\Gamma_{m,j})}
(-1)^{n/2} \dfrac{n!}{2^{n/2} (n/2)! }
(V_{A^{\rm gen}_{m}}^{n/2} - V_{A^{\rm gen, +}_{m-1}}^{n/2})
\Big)
.
\end{multline*}

[Theorem 1 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $p\in [1,2]$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Poincare-type-Boolean}}}(p)^k\Wop^{\geq k}(f),
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Poincare-type-Boolean}}}(p)=2^{1-p}/\Beta(\frac{1}{2};\frac{p}{2},\frac{p}{2})$, where $\Beta(x;a,b) := \int_0^x t^{a-1} \left(1-t\right)^{b-1} \dif t$ is the incomplete Beta function. (Proof in the paper; no proof environment follows the statement in the TeX.)

