[Theorem prop: levy processes 1 of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Fix $S\subseteq\mathbb R$ with and let  $X=(X_t)_{t\in[0,T]}$ be an $S$-valued Lévy process, with characteristics $(b,a,F)$. Assume that $\int_{|y|>1}\exp(\alpha  |y|) F(dy)<\infty$ for some $\alpha>0$.        Set  
\begin{align*}
    \mathcal{V}&\subseteq\{h\in H(\mathbb C) \colon h \text{ is of exponential type }\tau<{\alpha}\},\\
       \mathcal{V}^*&:=\{\mathbf{u}\in \mathcal{S}^* \colon h_\mathbf{u}=h,  \ h\in \mathcal{V}\}.
\end{align*}
Then,
\begin{enumerate}
\item $X$ is an $S$-valued $\mathcal{V}$-holomorphic process. 
    \item  For all $h\in \mathcal V$, the process $N^h$ given in equation (equation eq:localmart of the paper) is a true martingale.
    \item  For all $\mathbf{u}\in  \mathcal{V}^*$, there exists a $\mathcal{V}^*$-valued solution $(\mathbf{c}(t))_{t\in[0,T]}$ of (equation eq: ODE pointwise of the paper) with initial condition $\mathbf{u}$ which satisfies condition~(moment formula iii of the paper) of Theorem~(th: moment formula holomorphic of the paper). 
 \end{enumerate}
 In particular, for each $\mathbf{u}\in  \mathcal{V}^*$, the holomorphic formula holds true:
    \begin{align*}
    \mathbb E[h_\mathbf{u}(X_T)]=h_{\mathbf{c}(T)}(x_0).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 75 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] There exist  $d_{0}\in(1,d)$ and a constant    $N $, depending only
on $d,\delta$, 
 such that for any ($\lambda\geq\varkappa_{0}^{2}\rho_{b}^{-2}$)  ball  $B$ of radius $\rho\leq \varkappa_{0}/(2\sqrt\lambda)$ 
 and $p\geq d_{0}  $, we have
\begin{equation}

\| g_{\cA}\|_{L_{p/(p-1)}(B)}\leq N \rho^{-d /p }
\| g_{\cA}\|_{L_{1}(2B )} , 
\end{equation}
which is equivalently rewritten as
$$
\Big(\dashint_{B}g^{p/(p-1)}_{\cA}\,dx \Big)^{(p-1)/p}
\leq N\dashint_{2B }g_{\cA}\,dx.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] Under Assumption \ref{assumption}, it holds that 
    \begin{align}
        \limsup\limits_{T \to +\infty} \exp(\lambda_1 T)\chi^2(\mu_{T/2}^{T}||\diffref) &\leq 2(K^2+1)\sum_{i\in \mathcal{I}_1} (p_i^2 + q_i^2),
    \end{align}
    where $K = \sup\limits_{T \geq T^*} \norm{b^{T}}_{L^{\infty}(\diffref)}$ for some $T^* > 0$ chosen large enough, guaranteed to exist by \eqref{eq:uniform-bdd-potents}.

