[Lem convergence of conditioned ER graphs wrt resistance metric of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] If a sequence $(m_{n})_{n \geq 1}$ of natural numbers satisfies $n^{-2/3}m_{n} \to \sigma \in (0,\infty)$,
  then it holds that
  \begin{equation}
    (V(G_{m_{n}}^{p_{n}}), n^{-1/3} R_{G_{m_{n}}^{p_{n}}}, \rho_{G_{m_{n}}^{p_{n}}}, n^{-2/3} \dot{\mu}^{\#}_{G_{m_{n}}^{p_{n}}})
    \xrightarrow{\mathrm{d}}
    (M^{(\sigma)}, R_{M^{(\sigma)}}, \rho_{M^{(\sigma)}}, \mu_{M^{(\sigma)}} \otimes \tilde{p})
  \end{equation}
  in the space $\mathfrak{M}_{c}(\markedfinMeasFunct{\mathbb{R}_{\geq 0}})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop edgeworth-prop of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] For any sequence $C_n$ of non-negative numbers such that $\sqrt{n}C_n \to 0$, 
    \begin{align}
        \mathbb{P}&\bigl[ \log |P_n(X_0)| > nC_n, X_0 \in \mathbb{A}_n\bigr] \\& \qquad\quad= 2 \bigintsss_{ 1- \kappa\sqrt{\frac{\log n}{n}}}^1 (1- \Phi(C_r(n)))rdr + 2 \bigintsss_{ 1- \kappa\sqrt{\frac{\log n}{n}}}^1 \frac{Q_1(C_r(n))}{\sqrt{n}}rdr + O\left(\frac{1}{n} \right), \nonumber
    \end{align}
    where $\Phi$ is the distribution function of a standard normal random variable. In particular, by taking $C_n = 0$, 
\begin{equation}
 \mathbb{E}[Area(\mathbb{D}\setminus \Lambda_n)] = 2 \pi\bigintsss_{ 1- \kappa\sqrt{\frac{\log n}{n}}}^1 \biggl(1- \Phi\biggl(\frac{\sqrt{n}(1-r^2)}{2\sigma(r)}\biggr)\biggr)rdr + O\biggl(\frac{1}{n}\biggr).
\end{equation}
    Moreover, as $n\to \infty$, 
    \begin{equation}
      \sqrt{n} \bigintsss_{ 1- \kappa\sqrt{\frac{\log n}{n}}}^1 (1- \Phi(C_r(n)))rdr \to   \sqrt{\frac{1}{2\pi}Var(\log(|1-X_1|))}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2607.04193, 'Onsager--Machlup Functionals for Generalized Newtonian Equations of Motion with Time-Varyi'] Let $f \in I_{a^+}^\alpha(L^p)$ and $g \in I_{b^-}^\alpha(L^p)$ with $p \ge 1$. The left-sided and right-sided Riemann--Liouville fractional derivatives of order $\alpha > 0$ are defined respectively by
    \begin{align*}
        (D_{a^+}^\alpha f)(x) &:= \left( \frac{d}{dx} \right)^{[\alpha] + 1} I_{a^+}^{1 + [\alpha] - \alpha} f(x), \\
        (D_{b^-}^\alpha g)(x) &:= \left( -\frac{d}{dx} \right)^{[\alpha] + 1} I_{b^-}^{1 + [\alpha] - \alpha} g(x),
    \end{align*}
    where $[\alpha]$ denotes the integer part of $\alpha$.

