[Theorem 34 (\cite{chen2022hamilton}) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\psi:\mcl Q_2^\D\to\R$ be $\Ll(\mcl Q_2^\D\Rr)^*$-increasing and satisfy
\begin{align}
    \Ll|\psi(q)-\psi(q')\Rr|\leq \Ll|q-q'\Rr|_{L^1},\qquad\forall q,q'\in\mcl Q_2^\D.
\end{align}
With initial condition $f(0,\cdot)=\psi$, there exists a viscosity solution $f$ of~\eqref{e.hj}, unique in the class of Lipschitz functions on $\R_+\times\mcl Q_2^\D$. Moreover, if $\psi$ is convex on $\mcl Q_2^\D$, then $f$ admits the Hopf representation
\begin{align}
        f(t,q) = \sup_{p \in \mcl Q_\infty^\D}\inf_{q' \in \mcl Q_\infty^\D}\left\{ \psi(q') + \la q - q', p\ra_\cH +t\int_0^1\xi(p(s))\d s\right\},\quad\forall(t,q)\in\R_+\times\mcl Q_2^\D.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Variational reduction for a high-centered wedge) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] For $0<p<q<1$,
\begin{align*}
 &\inf\left\{
 \KL(x_1\|p)+\KL(x_2\|p)+\KL(y\|q):
 (x_1,x_2,y)\in[0,1]^3,\ x_1\ge y,\ x_2\ge y
 \right\}
 \\
 &\hspace{25mm}
 =\inf_{0\le z\le1}\{2\KL(z\|p)+\KL(z\|q)\}.
\end{align*}
The minimizer is unique and has $x_1=x_2=y=z^*(p)\in(p,q)$.

[Proposition 12 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] For a.e. $x\in \T^2$, it holds that
    \begin{equation}
        \P\left( \omega\in\Omega: \lim_{q\to\infty} \dist ( X_1^{\kappa_q}( x, \omega), X^q_1( x))=0\right) =1.
    \end{equation}

