body:
[Theorem 13 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Consider a pullback square of fpqc algebraic stacks
  \begin{equation*}
    \begin{tikzcd}
      \mcalY' \arrow[r,"g'"] \arrow[d,"f'"'] & \mcalY \arrow[d,"f"] \\
      \mcalX' \arrow[r,"g"'] & \mcalX.
    \end{tikzcd}
  \end{equation*}
  Assume that \(g \colon \mcalX' \to \mcalX\) is flat and \(f \colon \mcalY \to \mcalX\) is a \(B\mcalG\)-torsor for a flat affine group scheme \(\mcalG\) over \(\mcalX\).
  For $\mcalF \in \mcalD_{\qcoh}^+(\mcalY)$, the base change morphism
  \begin{equation*}
    \BC_{f,g}(\mcalF)\colon Lg^*Rf_*\mcalF\to Rf'_*L(g')^*\mcalF
  \end{equation*}
  defined in \Cref{QuasiCoherentBaseChangeMorphism} is an equivalence in \(\mcalD_{\qcoh}(\mcalX')\).

[Lemma lem:trace-diagonal of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] Conditionally on $\mathcal{F}_k$,
\begin{equation}
 \operatorname{tr} Q_k=(n-k)S_k,
\end{equation}
and, for every $i\in[n]$,
\begin{equation}
 (Q_k)_{ii}
 =\sum_{\substack{A\in\binom{[n]}{k}\\i\notin A}}X_k(A)^2
 \leq S_k.
\end{equation}
Consequently, whenever $S_k>0$,
\begin{equation}
 \max_i(Q_k)_{ii}\leq\frac{\operatorname{tr} Q_k}{n-k}.
\end{equation}

[Definition 38 of arXiv:2609.02197, '2609.02197'] Let $\left(\alpha,U\right) \in \mathbb{R}\times \mathbb{R}_+.$ We define $$\text{\gls{pc6}}:=\left\{g \in C_U\mathscr{C}^{\max\left(\alpha,0\right)},\exists\mu\in\mathbb{R}_+,\forall\left(r,q\right)\in\left[0,U\right]^2,\left\Vert g\left(r\right)-g\left(q\right)\right\Vert_{\mathscr{C}^0}\leq\mu\left|r-q\right|^{\frac{1}{16}}\right\}$$
and
\begin{align*} 
\left\Vert\cdot\right\Vert_{\mathfrak{Y}_U^\alpha}: \mathfrak{Y}_U^\alpha &\longrightarrow \mathbb{R}_+ \\ f & \longmapsto \left\Vert f\right\Vert_{\mathfrak{Y}_U^\alpha}=\max\left(\left\Vert f\right\Vert_{C_U\mathscr{C}^{\max\left(\alpha,0\right)}},\sup_{\substack{\left(r,q\right)\in\left[0,U\right]^2\\ r\neq q}}\frac{\left\Vert f\left(r\right)-f\left(q\right)\right\Vert_{\mathscr{C}^0}}{\left|r-q\right|^{\frac{1}{16}}}\right)
\end{align*}

[Lemma lem:seq_grow of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Consider the sequences $(\underline{a}_i)_{i \geq 0}, (\Bar{a}_i)_{i \geq 0},$ as defined in (equation eq:inductive_def_seq_a of the paper) and $ (\underline{b}_i)_{i \geq 0}, (\Bar{b}_i)_{i \geq 0}$ as defined in (equation eq:inductive_def_seq_b of the paper). Then for all $i \geq 1$, there are universal constants $A,B>1$ such that
    \begin{align*}
        &\frac{\alpha m^i}{A}\leq \underline{a}_i<\Bar{a}_i\leq \alpha Am^i,\textrm{ and  }\beta+\frac{m'\alpha m^i}{B}\leq \underline{b}_i<\Bar{b}_i\leq\beta+m'\alpha Bm^i.\addtocounter{equation}{1}\tag{\theequation} 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

