\sup_{t\in[0,T]}\mathbb{E}|X_{t}^{\varepsilon}-\bar{X}^{\varepsilon}_{t}|^2\le  C_T(1+|x|^2+|y^2|)\varepsilon^{1/3}. 
\end{align}

