\eqref{eq:newton-recursion} belongs to $p_k(x_k)\mathscr D$.
\end{enumerate}

[Lemma 12 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=(V,E)$ be a locally finite weighted graph and let $\psi\in C^{1}(0,+\infty)$ be a concave function with $\psi^\prime \left(1\right)>0$ and $H_{\psi}<\infty$.  Assume that $u:V\times[T_{1},T_{2}]\rightarrow(0,+\infty)$ satisfies
    \begin{equation*}
        \left(1-\alpha\right)\Gamma^{\psi}\left(u\right)-\psi^{\prime}\left(1\right)\frac{\partial_t u}{u}\leq\frac{c_1}{t}+c_2,
    \end{equation*}
    where $\alpha\in[0,1), c_{1}>0$ and $c_{2}\ge0$. Then for any $x,y\in V$, 
    \begin{equation*}
        u\left(x,T_1\right)\leq u\left(y,T_2\right)\left(\frac{T_2}{T_1}\right)^{\frac{c_1}{\psi^{\prime}\left(1\right)}}\exp\left(\frac{c_2}{\psi^{\prime}\left(1\right)}\left(T_2-T_1\right)+\frac{\psi^{\prime}\left(1\right)H_{\psi}\mu_{\max}d^2\left(x,y\right)}{\left(1-\alpha\right)w_{\min}\left(T_2-T_1\right)} \right).
    \end{equation*}

