[Theo 5 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] Assume $W$ is defined as (\ref{statistic-mann-whitney-wilcoxon}), we have
\begin{align}
     \left|\frac{\mathbb{P}\left(W>z\right)}{1-\Phi(z)}-1\right| = O(1)(1+z^3)/(1/n_{1}+1/n_{2})^{1/2},
\end{align}
for $0\leq z \leq \min(n_{1},n_{2})^{1/6}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 12 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let~\eqref{co:6} and~\eqref{eq:integrability condition} hold for $\rho = 1$ and $N_{\infty} := \limsup_{t\uparrow\infty} N(t)$ be positive. Then each positive solution $I$ to~\eqref{eq:SIS epidemic model} satisfies the following two statements:
\begin{enumerate}[(i)]
\item If there is a continuous function $f_{\infty}\colon ]0,N_{\infty}]\cap\R_{+}\rightarrow\R$ that admits at least one zero and satisfies $\liminf_{x\downarrow 0} f_{\infty}(x) > 0$ and
\begin{equation*}
\liminf_{s\uparrow\infty} \inf_{x\in ]0,N(s)]:\,x < x_{0}}h\big(s,x,N(s),\mathcal{L}(I_{s})\big) - f_{\infty}(x) \geq 0
\end{equation*}
for the smallest zero $x_{0}$ of $f_{\infty}$, then $I$ persists above $x_{0}$.

\item If there is a continuous function $g_{\infty}\colon \R_{+}\rightarrow\R$ that has at least one zero in $[0,N_{\infty}[$ and satisfies $\limsup_{x\rightarrow N_{\infty}} g_{\infty}(x) < 0$ and
\begin{equation*}
\limsup_{s\uparrow\infty}\sup_{x\in ]0,N(s)]:\,x > y_{0}} h\big(s,x,N(s),\mathcal{L}(I_{s})\big) - g_{\infty}(x) \leq 0
\end{equation*}
for the largest zero $y_{0}$ of $g_{\infty}$ in $[0,N_{\infty}[$, then $\liminf_{t\uparrow\infty} I_{t} \leq y_{0}$ a.s.
\end{enumerate}
In particular, if the requirements of~(i) and~(ii) are met and $x_{0} = y_{0}$, then persistence~\eqref{eq:persistence around a point} around $x_{0}$ holds for $I$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:int approx of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu_n,\sigma_n$ be arbitrary (with $\sigma_n>0$) and $\ell_n,r_n\gg1$ as well as $\ell_n/\sigma_n,r_n/\sigma_n\gg1$.
    Then, we can approximate the gaussian integral with the sum from $\mu_n-\ell_n$ to $\mu_n+r_n$ as such
    \begin{align*}
        \left|\sum_{\mu_n-\ell_n<m<\mu_n+r_n}\exp\left(-\frac{(m-\mu_n)^2}{2\sigma_n^2}\right)-\sqrt{2\pi}\sigma_n\right|&\leq1+o(\sigma_n)\,.
    \end{align*}

