[Definition 5 of arXiv:2609.00702, 'On the Set-Valued Katugampola Fractional Integral: Properties and Regular Selections'] Let $F:I\rightrightarrows \mathbb{R}$ be a set-valued function and $\mathfrak{I}$ be the collection of all integrable selections of $F.$ The set-valued Katugampola fractional integral is defined as 
\begin{equation*}
    \begin{aligned}
        _a^\rho\mathfrak{D}^\nu F(t)=\bigg\{\frac{(\rho+1)^{1-\nu}}{\Gamma(\nu)}\int_a^t(t^{\rho+1}-x^{\rho+1})^{\nu-1}x^{\rho}f(x)dx:f\in\mathfrak{I}\bigg\}
    \end{aligned}
\end{equation*}
where $\nu>0$ and $\rho \neq -1$ are real numbers.

[Lemma lem:poiss-approx of arXiv:2510.18856, 'Evolution of recursive trees with limited memory'] Let $D_{j,n}$ be the degree of vertex \textcolor{black}{$j$} at time $n$.
    For any $\epsilon > 1$, there exists $j_0$ such that for all $j_0 \leqslant j \leqslant n$,  \begin{align*}
        &d_{TV}\left(D_{j,n}, \text{Poisson}(1)\right) \\
        &\leqslant \epsilon \left[1-(1+\epsilon j^{\beta-1})^{-\beta}\right] + \epsilon j^{-\beta} + \max(\epsilon-1,j^{-\beta})+ \mathds{1}\left\{N_j\geqslant n-j\right\} \abs{\frac{n-j}{j^\beta}-1}
    \end{align*}where $N_j = \abs{\left\{i\geqslant j:i-i^\beta \leqslant j\right\}}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] Let $a, b >0$ and $f(s) = \frac{a}{s} + b s,\, s\in (0,\infty).$ Let $\gamma > 0,$ and a positive
    function $g\in C_b(\R_+)$ be such that for some $\kappa\in [0,\infty),$ and $g_0, g_\infty \in (0,\infty)$ we have
    \begin{equation}
        \lim_{s\to 0^+} \frac{g(s)}{s^{\kappa}} = g_0, \quad \lim_{s \to \infty} g(s) = g_\infty.
    \end{equation}
    Then
    \begin{equation}
       \int_0^\infty s^{-\gamma}e^{-rf(s)}g\left(\frac{t^{2/\alpha}}{rs}\right)\, \dx[s]
       \sim \sqrt{\frac{\pi}{a}}\left(\frac{a}{b}\right)^{\frac34 - \frac{\gamma}{2}} \frac{e^{-2r\sqrt{ab}}}{\sqrt{r}} g\left(\frac{t^{2/\alpha}\sqrt{b}}{r\sqrt{a}}\right).
    \end{equation}
    Furthermore, the above asymptotic equality holds also for
    any positive function $g\in C_b(\R_+)$ such that $\lim_{s\to 0^+} \frac{g(s)}{s^\kappa} = g_0$ 
    (without assuming the existence of a positive limit in infinity) provided $\frac{t}{r^{\alpha/2}} <M$ for some constant $M>0.$

