body:
[Lem 108 (spatial smoothing of budget constraint) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Analogously to \eqref{e:budget.Ising.plus.eps}, with high probability we have
	\begin{align*}\nonumber
	&\tilde{C}^N(t)
	\equiv
	\int_{\R}
	\Cost_{t,2\bar{\lambda}}(\sPsi^N(t,y)) \,
		\overline{\varrho_{\vY,N,t}*\sphi}(y)\,dy\\ 
	&\qquad\le
	\frac{1}{\alpha}
	\bigg(
	\int_{\R} \swww(t,y)^{1/2} 
		\,\varsigma_{\vY,N,t}*\sphi(y)\,dy
	\bigg)^2
	+ 3\epsilon^\circ
	\equiv \frac{\tilde{W}^N(t)^2}{\alpha}+ 3\epsilon^\circ
	\end{align*}
for all $q_0\le t\le 1$. 

\begin{proof}
We continue to use the abbreviations introduced above.\smallskip

\noindent\textbf{Relation between $\tilde{C}^N(t)$ and $C^N(t)$.}
 As in Definition~\ref{d:sp.smooth}, let $\sPsi\equiv(\sB,\sV,\sU)$. The function $\Cost_{t,2\bar{\lambda}}$ is convex on the  expanded domain 
	\[\bigg\{(B,V,U)
	: \frac{V}{p(t)}
	\ge \frac{U^2}{p(t) \cdot t p'(t)} 
	-  \frac{2\bar\lambda}{p(t)}\bigg\}\,.\]
It follows from Lemma~\ref{l:sp.smooth.domain}
that $\sPsi$ lies in this expanded domain with high probability. 
Recall from Definition~\ref{d:disc.rescaled.coeffs} that we can regard $\Psi=(B,V,U)$ as functions of $(t,\vy)$ with $\vy\in\R^3$.
It then follows by Jensen's inequality that 
	\begin{align*}
	&\Cost_{t,2\bar{\lambda}}\Big(\sPsi(t,y)\Big)
	= \Cost_{t,2\bar{\lambda}}
	\Big( \sE_{t,y} \Psi(t,\xxx)\Big)
	\le \sE_{t,y}
	\bigg[ \Cost_{t,2\bar{\lambda}}
		\Big(\Psi(t,\xxx)\Big)\bigg] \\
	&\qquad
	\stackrel{\eqref{e:tilde.bP}}{=}
	\int_{H(y)}\int_{\R^3}
	\Cost_{t,2\bar{\lambda}} (\Psi(t,\vx))
	\frac{\varrho_t*\sphi(\vy)}
		{\overline{\varrho_t*\sphi}(y)}
		\cdot \frac{\sphi(\vy-\vx)\,\varrho_t(d\vx)}
			{\varrho_t*\sphi(\vy)} \,d\vy\,.
	\end{align*}
Integrating the above bound with respect to $\overline{\varrho_t * \sphi}(y)\,dy$ gives
	\begin{align*}
	\tilde{C}^N(t) &=
	\int_{\R} \Cost_{t,2\bar{\lambda}}\Big(\sPsi(t,y)\Big)
		\overline{\varrho_t * \sphi}(y)\,dy
	\le
	\int_{\R^3}
	\Cost_{t,2\bar{\lambda}} (\Psi(t,\vx)) \bigg[
	\int_{\R^3}
	\sphi(\vy-\vx) \,d\vy\bigg] \,\varrho_t(d\vx) \\
	&= \int_{\R^3}
	\Cost_{t,2\bar{\lambda}} (\Psi(t,\vx))\, \varrho_t(d\vx) = C^N(t)\,,
	\end{align*}
having used that $\sphi$ integrates to one.\smallskip

\noindent\textbf{Relation between $\tilde{W}^N(t)$ and $W^N(t)$.}
Similarly, recall from Definition~\ref{d:disc.rescaled.coeffs} that we can regard $\www^\frozen$ as a function of $(t,y^4)\in\R^2$. We can then express
$\swww(t,y) = \sE_{t,y,\Ising} \www^\frozen(t,\xxx)$ where $\sE_{t,y,\Ising}$ denotes expectation with respect to the law of $(\vy,\xxx)\sim\tilde{\bP}_{t,y,\Ising}$ defined by
	\[
	\tilde{\bP}_{t,y,\Ising}(dy\,dx)
	= \frac{\sphi(y-x)\,\varsigma_t(dx)}
			{\varsigma_t*\sphi(y)} \, dy\,.
	\]
for $x,y\in\R$.
Then, since $w\mapsto w^{1/2}$ is concave in $w\ge0$, we have
	\begin{align*}
	&\swww(t,y)^{1/2}
	=\Big( \sE_{t,y,\Ising} 
	\www^\frozen(t,\xxx) \Big)^{1/2}
	\ge\sE_{t,y,\Ising} 
	\Big[\www^\frozen(t,\xxx)^{1/2}\Big] \\
	&\qquad\stackrel{\eqref{e:tilde.bP}}{=}\int_{\R}\int_{\R}
		\www^\frozen(t,x)^{1/2}
	\frac{\sphi(y-x)\,\varsigma_t(dx)}
		{\varsigma_t*\sphi(y)} \,dy
	\,.
	\end{align*}
Integrating the above bound with respect to $\varsigma_t * \sphi(y)\,dy$ gives
	\begin{align*}
	\tilde{W}^N(t)
	&=
	\int_{\R} \swww(t,y)^{1/2} 
		\varsigma_t * \sphi(y)\,dy
	\ge
	\int_{\R} \www^\frozen(t,x)^{1/2}
	\bigg[\int_{\R}\sphi(y-x)\,dy\bigg] \, \varsigma_t(dx)\\
	&=\int_{\R} 
	\www^\frozen(t,x)^{1/2}\, \varsigma_t(d\vx)
	= W^N(t)\,.
	\end{align*}
Combining with \eqref{e:budget.Ising.plus.eps} gives
	\[
	\tilde{C}^N(t)
	\le C^N(t)
	\stackrel{\eqref{e:budget.Ising.plus.eps}}{\le}
	\frac{W^N(t)^2}{\alpha}+ 3\epsilon^\circ
	\le
	\frac{\tilde{W}^N(t)^2}{\alpha}+ 3\epsilon^\circ\,,
	\]
as claimed.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 7 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{K_n : n \ge 1\} \subseteq \cK(\cX)$ and $p \in [1, \infty)$. Assume that $\{X^n_s : s \in S_n, n \ge 1\}$ is $(\nu_n)$-$\CUI(p)$ w.r.t. $\{K_n\}$. If
	\begin{align}
		\lim_{n \rightarrow \infty} \lt\|K_n\rt\| \nu_n(S_n)=0,
	\end{align}
	then \eqref{eq:thm:decay-masses} holds true.

[Lemma lem:quasi_isometry of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] For every $\varepsilon>0$ and every distinct vertices $x,y\in V_\varepsilon$,
    \begin{equation}
        \frac{1}{4\varepsilon} \mathrm{d}_{M}(x,y)\leq \mathrm{d}_{G_\varepsilon}(x,y) \leq \frac{\Delta(\varepsilon)}{2\varepsilon} \mathrm{d}_{M}(x,y).
    \end{equation}

[Theorem 10 (Finite-time convergence of the normalized latent recursion) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumptions~\ref{assump:mdp}, \ref{assump:mix},
\ref{assump:stable_kernels}, and \ref{assump:stepsizes} hold. Moreover, choose
$\frac45\alpha_{\mrm N}(1-\gamma)=:\lambda_{\mrm N}>1$ and set
\begin{equation}
        \epsilon_n^{\mrm N}
        :=
        \sqbk{(n+n_0^{\mrm N})
        \crbk{2L_{0,\rho}+4L_{\kappa,\rho}(1+c_\wedge^{-1})}
        \log\!\crbk{\frac{5(n+n_0^{\mrm N})}{n_0^{\mrm N}}}}\inv.

\end{equation}
For $\delta\in(0,1)$, define $r_c:=       \frac{c_\wedge}{64(1\vee L_{\kappa,\rho})}$ and set the burn-in number of iterations to be
\begin{equation}
        m_0(\delta):=\ceil{
        \frac{256\tmix^2}{c_\wedge^2}
        \log\!\crbk{\frac{6\cN_\rho(r_c)}{\delta}}} 
        \vee\ceil{n_0^{\mrm N}}
        \vee\ceil{16\alpha_{\mrm N}}.

\end{equation}
Then, with probability at least $1-\delta$
\begin{equation}
\begin{aligned}
        \norm{\theta_n^{\mrm N}-\theta^*}
        &\le
        \frac{3}{1-\gamma}
        \sqbk{\frac{m_0(\delta)+n_0^{\mrm N}}
        {n+n_0^{\mrm N}}}^{\lambda_{\mrm N}} \\
        &\quad+
        \frac{370\tmix}{c_\wedge(1-\gamma)^2}
        \sqbk{
        \sqrt{\frac{
        \alpha_{\mrm N}\crbk{
        \cL_n^{\mrm N}(\delta)+\log\cN_\rho(\epsilon_n^{\mrm N})}}
        {n+n_0^{\mrm N}}}
        +
        \frac{\alpha_{\mrm N}^{2}}
        {c_\wedge(\lambda_{\mrm N}-1)(n+n_0^{\mrm N})}}
\end{aligned}

\end{equation}
simultaneously for all $ n\ge m_0(\delta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 49 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $\beta>0$. Let $G=(V,E)$ be a subgraph of $\mathbb Z^d$ with $0\in V$. Let $S\cap B=\emptyset$ be finite subsets of $V$, with $S$ containing $0$. Assume that $\partial S$ is separating $0$ and $B$ in the sense that every path from $0$ to $B$ has to visit $\partial S$. Then,
\begin{equation}
	\phi_{G, \beta}^0[0 \connect{} B] \leq \sum_{\substack{u\in S\\ v\notin S\\ u\sim v}} \phi_{S, \beta}^0[0 \connect{} u]\beta\phi_{G, \beta}^0[v \connect{} B]. 
\end{equation}

