[Lem 21 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For all $K \geq (\oC_{\mu}+\varepsilon) \log N$, $t>0$, and $\p \in [k]_0$, there exists $\delta=\delta(\mu,\varepsilon)>0$ and two sequence sets $\cS_{\p}^{\for}$ and $\cS_{\p}^{\back}$ such that the following holds.
        \begin{itemize}
            \item[\emph{(a)}] The sequence sets $\cS_{\p}^{\for}$ and $\cS_{\p}^{\back}$ are typical, i.e.
            \[
            \P(S_K \in \cS_{\p}^{\for}) \geq 1- \exp(-N^{\delta}), \quad \P(S_K \in \cS_{\p}^{\back}) \geq 1- \exp(-N^{\delta}).
            \]
            \item[\emph{(b)}] The truncated exponential moment of number of shared edges is small: both of the inequalities
            \begin{equation} 

            \begin{aligned}
                \E(e^{t|E_{\for}^\p(G,G')|}\cdot 1_{S_K,S_K' \in \cS_{\p}^{\for}}) &\leq 1+ O(N^{-\delta}),\\ \E(e^{t|E_{\back}^\p(G,G')|}\cdot 1_{S_K,S_K' \in \cS_{\p}^{\back}}) &\leq 1+ O(N^{-\delta}),
            \end{aligned}
            \end{equation}
            hold for sufficiently large $N$.
            \item[\emph{(c)}] If the sequence $S_K \in \cS^{\dagger}$, where 
            \begin{equation}
                \cS^{\dagger}=\bigcap_{\p \in [k]_0} \lt( \cS_{\p}^{\for} \cap \cS_{\p}^{\back}\rt),
            \end{equation}
            then $S_K$ is $\vartheta$-regular.
        \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor almostdone of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Let $\Lambda_N$ be an increasing sequence converging to $\mathbb{Z}^d$.
There exists a number $\upbeta_1(d)>0$, depending only on the dimension $d$, such that the following is true. If $|\upbeta|\leq \upbeta_1(d)$, then, for any string $s\in\mathcal{S}$,
\begin{equation*}
	\text{$\phi_{\Lambda_N,N,\upbeta}(s)$ converges to a limit $\phi_{\infty}(s)$ as $N\to\infty$.}
\end{equation*} 
Moreover, $\phi_{\infty}(\emptyset)=1$, $\phi_{\infty}$ is invariant under backtrack erasures, $|\phi_{\infty}(s)|\leq 1$ for all $s\in\mathcal{S}$, and $\phi_{\infty}(s)$ is the unique solution to the master loop equation (equation eq:limiting_master_loop_eq of the paper) for all non-empty $s\in \mathcal{S}$.

