[Lemma 53 of arXiv:2608.27307, '2608.27307'] Under the assumptions of Theorem~\ref{thm:rand_sc_eq}, for every fixed integer $r\geq1$,
        \begin{align}
                \partial_{i\mu}^rG =(-1)^r r!G(V^{i\mu}G)^r. 
        \end{align}
        Uniformly for deterministic vectors $\bbx,\bbw$ of bounded norm,
        \begin{align}
                \abs{\partial_{i\mu}^rG_{\bbx\bbw}}                   & \prec(1+\phi)^{r+1},                                   \\
                \sum_{\mu=M+1}^{L} \abs{\partial_{i\mu}^rG_{\bbx\mu}} & \prec(1+\phi)^r\sqrt N \sqrt{\frac{\vphi+\eta}{\eta}}. 
        \end{align}

[Lemma lem:ftpbds of arXiv:2606.02472, 'Correlated uniform attachment trees'] Let $T_n\sim\mathrm{UA}(n)$ and fix constants  $0<s<\beta\leq 1$. Then for all $k=0,1,\ldots, n$, we have
\ben{
\mathbb{P}(F_{T_n}(k) \geq \beta n)  \leq  (1-\beta +s)^k + e^{-n s^2/2}.
}
For any $0<\gamma<1$, $0<\beta<1$, and $k\leq \gamma n$, with $ \frac{\beta  + 2\gamma + 2/n}{1-\gamma} \leq 1$ we have 
\ben{
\mathbb{P}(F_{T_n}(k) \geq \beta n) \geq  \bbbclr{1- \frac{\beta  + 2\gamma + 2/n}{1-\gamma}}^k.
}

