ell_0 << N

[Lemma 7 of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $0<s<1$ and $2\le p<\infty$. Then
    \begin{equation}
        [u]_{s,p}\le C_{n,s,p}\,\norm{\flap u}_{L^p(\R^n)},
        \qquad\forall\,u\in C_{\mathrm{c}}^\infty(\R^n).
    \end{equation}

