body:
[Theorem th:near-critical-scaling of arXiv:2606.11503, 'Percolation on hierarchical lattices'] For any $\lambda \in \mathbb{R}$,
  \begin{equation}

    f_{k} \Big( p_\star + \frac{\lambda}{\zeta^k} \Big) \to h^{-1}(\lambda),
  \end{equation}
  where the diffeomorphism $h: (0, 1) \to \mathbb{R}$ is characterized as the unique linear conjugation of $f$ (that is, $h \circ f = \zeta \cdot h$) such that $h'(p_\star) = 1$.

  \nc{c:tail_h_1}
  \nc{c:tail_h_2}
  Moreover, there exist constants $\uc{c:tail_h_1}, \uc{c:tail_h_2} > 0$ such that
  \begin{equation}

    \exp \Big( -\uc{c:tail_h_1} |\lambda|^\nu \Big)
    \leq h^{-1}(\lambda)
    \leq \exp \Big( -\uc{c:tail_h_1}^{-1} |\lambda|^\nu \Big),
    \text{ as $\lambda \to -\infty$}
  \end{equation}
  and
  \begin{equation}

    1 - \exp \Big( -\uc{c:tail_h_2} \lambda^\mu \Big)
    \leq h^{-1}(\lambda)
    \leq 1 - \exp \Big( -\uc{c:tail_h_2}^{-1} \lambda^\mu \Big),
    \text{ as $\lambda \to \infty$},
  \end{equation}
  where the exponents $\mu$ and $\nu$ are the ones appearing in (th:off-critical-decay of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 25 of arXiv:2605.21638, 'Markov renewal theory for transfer operators and point processes on the line'] Let $k<n,\,f\colon \mathbb{R}^k \to \mathbb{R}$ be a bounded measurable function, then there exist $C, C' > 0$, such that
    \begin{equation*}
        \bigl|\mathbb{E}_\pi[f(Z_1, \dots, Z_k) G_\beta(Z_1) G_\beta(U_n)] - \mathbb{E}_\pi[f(Z_1, \dots, Z_k) G_\beta(Z_1)]\, \mathbb{E}_\pi[G_\beta(Z_n)] \bigr| \leq C \e^{-C'(n-k)}.
    \end{equation*}

[Proposition 30 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For every $x,\wt x\in\R$ with $x\neq\wt x$,
  \begin{align}
    \frac{\partial}{\partial x}
    \EE\bigl[
      F_{\wt x}^{\al,\be}F_{x}^{\al,\be}
    \bigr]
    =\lim_{\eps\downarrow0}
    \EE\left[
      \frac1\be\log \cZ_{\wt x}^\eps
      \frac{\partial}{\partial x}
      \frac1\be\log \cZ_x^\eps
    \right].
  \end{align}

[Theorem 72 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] For any $p\geq d_{0}+1$  
\begin{equation}

\|G_{\cA}\|_{L_{p/(p-1)}(\bR^{d+1}_{0})}\leq N(\delta,d  )\lambda^{(d+2)/(2p)-1}P(\cA)
\end{equation}
In particular, for any Borel $f\geq0$ given on $\bR^{d+1}$ (and $\lambda\geq \varkappa_{0}^{2}\rho_{b}^{-2}$) on $\{\tau<\infty\}$ we have
\begin{equation}

E_{\cF_{\tau}}\int_{0}^{\infty}e^{-\lambda t}f(t,x_{\tau+t})\,dt
\leq N(\delta,d )
\lambda^{(d+2)/(2d_{0}+2)-1}\|f\|_{L_{d_{0}+1}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:cuts_rays_paths of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] For any type path or ray $\pi=(s_0\rightarrow s_0s_1 \rightarrow s_0s_1s_2 \rightarrow \dots)$ with length $|\pi|$, and for any $1\leq i \leq |\pi|-1$, we define
    \begin{align*}
        &\pi^{(i)}:=(s_i\rightarrow s_is_{i+1}\rightarrow \dots)\textrm{ if }\pi\textrm{ is an infinite type ray; }  \\&\pi^{(i)}:=(s_i\rightarrow s_is_{i+1}\rightarrow \dots \rightarrow s_is_{i+1}\dots s_k)\textrm{ if }\pi\textrm{ is finite and }|\pi|=k.\addtocounter{equation}{1}\tag{\theequation} 
    \end{align*}
Similarly, for any $0\leq i\leq |\pi|$, we define the path $\pi_{(i)}$ as
\begin{align*}
    \pi_{(i)}:=(s_0\rightarrow s_0s_1 \rightarrow \dots \rightarrow s_0s_1\dots s_{i}).\addtocounter{equation}{1}\tag{\theequation} 
\end{align*}

[Theorem mintheorem of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Fix $\beta \in (0,\infty)$, and let $\tilde W:{\mathcal C }_\beta\to \mathbb{R}$ defined as $\tilde W(\omega)=\int_0^\beta W(\omega(s)) {\rm d} s$ for all $\omega \in {\mathcal C }_\beta$, where $W$ is a Soft-wall potential. Denote by  $\varphi:\mathbb{R} ^ d \to \mathbb{R}$ the $L^2(\mathbb{R}^d)$-normalized eigenfunction of the operator $-\Delta +W$ which corresponds to the principle eigenvalue 
        \begin{equation}
        \lambda(W)=\sup_{\varphi\in H^1(\mathbb{R}^d)\colon , \|\varphi\|_2=1}\Big(\langle W,\varphi^2\rangle-\|\nabla\varphi\|_2^2\Big).
    \end{equation}
    \noindent Then, setting
    \begin{equation}
     q^*({\rm d} x,{\rm d} y):=\varphi(x)\varphi(y)\frac{\mathbb{E}_x\left[e^{\tilde W -\beta\lambda (W)}; B_\beta \in {\rm d} y\right]}{{\rm d} y}\,{\rm d} x {\rm d} y,  
    \end{equation}
 we have that $\mu^*_{g,{\mathfrak m},W}$ defined in (equation minimizergen of the paper) with $q^*_{g,{\mathfrak m},W}$ replaced by $q^*$ in (equation pairscr of the paper) is an ergodic Markov process which corresponds to the solution to the problem
 \begin{equation}
     {\rm d} X_t=\frac{\nabla \varphi}{\varphi}{\rm d} t+{\rm d} B_t,\quad X_0 \text{ has distibution with density } \varphi^2 \text{ with respect to the Lebesgue measure}
 \end{equation}
 with invariant measure with density $\phi^2$, and it is the unique minimizer of $I_{{\mathfrak m},W,g}^{(sym)}$, when ${\mathfrak m}={\rm Leb}$ and $g\equiv p_\beta$. Moreover, $\mu^*_{g,{\mathfrak m},W}$ is a solution to the optimal transport problem:
$$\inf\{H(Q|\mathbb{P}_{\mathfrak m}): Q\circ\pi_0^{-1}=\phi^2(x){\rm d} x,Q\circ\pi_\beta^{-1}=\phi^2(x){\rm d} x\}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro:chromatic-signed of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Let $\Sigma$ be a signed graph, then 
\begin{equation}
\chi_\Sigma ^b (2t) = \phi_t\circ \Psi (\Sigma) = \zeta^{\ast t}(\Sigma).
\end{equation}

[Theorem SSS of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let Assumption (SDDRRFF of the paper) hold, and let \( \frac{1}{3} < \beta \leq \gamma \) such that \( 2\beta + \gamma > 1 \). Assume \( \xi \in \mathscr{D}_{\mathbf{X}}^{\beta}([-r,0]) \) and \( G \in C^{4}_{b}(\mathbb{R}^n \times \mathbb{R}^n, L(\mathbb{R}^d, \mathbb{R}^n)) \). Then, there exists a unique path \( y \in \mathscr{D}_{\mathbf{X}}^{\beta}([0, \infty)) \) such that for every \( 0 \leq s < t \), we have
			\begin{align*}
				(\delta y)_{s,t} &= \int_{s}^t A\left(y_\tau, \int_{-r}^{0} y_{\theta + \tau} \pi(\mathrm{d}\theta)\right) \mathrm{d}\tau \\
				&\quad + \int_{s}^{t} G \left(y_{\tau}, y_{\tau - r}\right) \mathrm{d}\mathbf{X}_{\tau}.
			\end{align*}
			Here, the last integral is defined in the sense of Theorem (DCVZVXZ of the paper). If \( A = 0 \), then the unique solution exists under weaker assumptions, specifically \( G \in C^{3}_{b} \). We denote the solution in both cases by \( {\phi}^{t}_{\mathbf{X}}(\xi) \). Also, there exists a polynomial \( Q \) (which only depends on \( \Vert A \Vert, G, \) and \( \pi \)) such that
			\begin{align}
				\left\| \phi_{\mathbf{X}}(\xi) \right\|_{\mathscr{D}_{\mathbf{X}}^{\beta}([0,r])} \leq Q \left( \left\| \xi \right\|_{\mathscr{D}_{\mathbf{X}}^{\beta}([-r,0])}, \left\| \mathbf{X} \right\|_{\gamma,[0,r]} \right),
			\end{align}
			where \( \phi_{\mathbf{X}}(\xi) = (\phi_{\mathbf{X}}^{t}(\xi))_{0 \leq t \leq r} \). Additionally, considering the map
			\begin{align}
				\begin{split}
					\phi_{\mathbf{X}}: \mathscr{D}_{\mathbf{X}}^{\beta}([-r,0]) &\rightarrow \mathscr{D}_{\mathbf{X}}^{\beta}([0,r]), \\
					\xi &\mapsto \phi_{\mathbf{X}}(\xi),
				\end{split}
			\end{align}
			we have that \( \phi_{\mathbf{X}} \) is continuous.

