body:
[Lemma 16 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $J\subseteq [n]$, $f:\cube^n\to \Rbb$, and $t > 0$,
\begin{equation}
    \Dop_J \Pop_t f(x) = \left(\upe^{2t}-1\right)^{-|J|/2} \Exp_{\ybold\sim p_{t,x}} \left[\phi_J^{t,x}(\ybold)f(\ybold)\right],
\end{equation}
where $\phi_J^{t,x}(y) := \prod_{i\in J} \frac{y_i-\upe^{-t} x_i}{\sqrt{1-\upe^{-2t}}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Nguyen--Squassina \cite{NM18}) of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $s\in(0,1)$, $sp=n$, and $R>0$. Then there exists $C_R>0$ such that
    \begin{equation}
        \norm{u\,\rho^{-s}\lg^{-1}}_{L^p(\R^n)}
        \le C_R\,[u]_{s,p},
        \qquad\forall\,u\in C_c^1(B_R^c).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: bound_integral_CGO_by_distance of arXiv:2609.00257, 'Stability estimates for the initial-to-final-state inverse problem'] Let $n\geq2$ and $V_1, V_2\in L^1((0, T); L^\infty(\mathbb{R}^n))$ with $\|V_j\|_{w_{\delta,\varepsilon} }< \infty$, for $j\in \{1, 2\}$. Let ${\bf u_1}$ and ${\bf u_2}$ be the CGO solutions (equation eq:CGO of the paper) to the Schr\"odinger equation, as constructed in subsection (sect: CGO of the paper), with potentials $V_1$ and $V_2$ respectively. Then, there holds 

\begin{equation}

\Big| \int_\Sigma (V_1-V_2) \mathbf{u}_1 \overline{\mathbf{u}_2} \Big| 
\leq  
\mathrm{dist}_{\delta, \varepsilon} (\mathcal{U}_T^1, \mathcal{U}_T^2) \| \mathbf{u}_1 \|_{L^2_{w_{\delta, \varepsilon}}(\Sigma)} \| \mathbf{u}_2 \|_{L^2_{w_{\delta, \varepsilon}}(\Sigma)}. 

\end{equation}

