    \begin{equation}

        \Big|\mathbb{P}\Big(Q(0,R_N)\subset \mathcal{I}^{g(0)(\log (R_N)^d+z_N)}\Big)-\exp(-\mathrm{e}^{-z_N})\Big| \leq c(R_N)^{-c_2}, 
    \end{equation}
    where $c_2>0$ is a constant. 
    It is elementary that
    \begin{equation}

        \big|\exp(-\mathrm{e}^{-z_N})-\mathrm{e}^{-1}\big|=\big|\exp(-\mathrm{e}^{-z_N})-\exp(-\mathrm{e}^0)\big|\leq c|z_N|.
