$k\in S_{\widehat{\mf q}}$
\begin{equation*}
\frac{1}{\omega(\mc M_{\widehat{\mf q}}(k))} \,
\pi_{\widehat{\mf q}}(k)\, \widehat{h}(\mc M_{\widehat{\mf q}}(k))^2
\sum_{j\in \mf I_k} \frac{\sigma_{\widehat{\mf q}}(j,j+1)}
{\widehat{h}(\mc M_{\widehat{\mf q}}(j))\widehat{h}(\mc M_{\widehat{\mf q}}(j+1))}
\,=\, Z_{\widehat{\mf q}}\,.
\end{equation*}

