[Theorem thm:hwi of arXiv:2510.22778, 'Free denoising diffusion models'] For every $\mu$ with finite second moment and $\Phi^{*}(\mu)<\infty$,
\begin{equation}
  \mathcal{D}(\mu\Vert\gamma)\leW_{2}(\mu,\gamma)\sqrt{I(\mu\Vert\gamma)}
  -\tfrac12W_{2}(\mu,\gamma)^{2}.
\end{equation}
In particular (equation eq:hwi of the paper) implies (equation eq:lsi of the paper) by maximising the right-hand side
over $W_{2}$.

[Theorem 3 (Information under the full likelihood) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Assume the model is identifiable and that the true parameter lies in an identifiable regular interior neighbourhood. Assume further that differentiation may be interchanged with integration, $B_{\xi\xi}$ is nonsingular, the relevant full-likelihood and completely classified likelihood maximisers are consistent for the true parameter, and the standard local regularity conditions for maximum-likelihood estimation hold. The per-observation Fisher information for $\theta$, after adjustment for the nuisance parameter $\xi$, is
\begin{equation}
 \J_{\mathrm{full}}(\theta,\xi)
 =\J_{\mathrm{CC}}(\theta)
 -\J_{\mathrm{lost}}(\theta,\xi)
 +\J_{\mathrm{miss}}^{\mathrm{adj}}(\theta,\xi).

\end{equation}
Consequently,
\begin{equation*}
 \J_{\mathrm{full}}(\theta,\xi)-\J_{\mathrm{CC}}(\theta)
 =\J_{\mathrm{miss}}^{\mathrm{adj}}(\theta,\xi)
 -\J_{\mathrm{lost}}(\theta,\xi).
\end{equation*}
If
\begin{equation}
 \J_{\mathrm{miss}}^{\mathrm{adj}}(\theta,\xi)
 -\J_{\mathrm{lost}}(\theta,\xi)>0,

\end{equation}
and both $\J_{\mathrm{full}}(\theta,\xi)$ and $\J_{\mathrm{CC}}(\theta)$ are positive definite, then the estimator based on the full likelihood has a smaller asymptotic covariance matrix than the maximum-likelihood estimator based on the completely classified sample. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 22 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1},\A{2}\leq 1$ be such that $N^{-1}\ll  \pr{\A{1}\A{2}}^{1/2}$ and let $m\geq 1$ be an order function on $\mc{T}_{\A{1},\A{2}}$. Let $p\in S(m,\A{1},\A{2})$ such that $p\geq 0$, $p+i$ is elliptic and admitting an asymptotic expansion $p\sim p_0+\Tilde{h}p_1+\dots$ in $S(m,\A{1},\A{2})$. Then, for all $\psi\in \mathscr{C}^{\infty}_c(\R)$, there exists
    \begin{equation}
        f\in S(1/m,\A{1},\A{2}) \m\m\m\m\m \text{such that}\m\m\m\m\m \psi(p_{N,\alpha_1,\A{2}})=f_{N,\alpha_1,\A{2}}

    \end{equation}
    satisfying
    \begin{equation}
        f\sim \sum_{\nu\in \N}\Tilde{h}^\nu f_\nu \m\m \text{in}\m\m S(1/m,\A{1},\A{2}) \m\m\m\m\m\text{where} \m\m\m\m\m f_\nu\in S(1/m,\A{1},\A{2}).

    \end{equation}
    In particular, we have that $f_0(x,\xi)=\psi\Bigl(p_0(x,\xi)\Bigl)$ and for all $\nu\geq 1$,
    \begin{equation}
        f_\nu(x,\xi)=\sum_{k=1}^{2\nu}g_k(x,\xi,\alpha)\psi^{(k)}\Bigl(p_0(x,\xi)\Bigl) \m\m\m\m\m\text{where} \m\m\m\m\m g_k\in S(1,\A{1},\A{2}).

    \end{equation}

[Theorem thm:hoeffding of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] Let $Z_1,\dots,Z_r$ be independent $\{0,1\}$-valued random variables satisfying $\mathbb{E} Z_i\geq 1/2$.
Then
\begin{equation}
 \mathbb{P}\!\left(\sum_{i=1}^r Z_i<\frac r3\right)
 \leq e^{-r/18}.
\end{equation}
Also,
\begin{equation}
 \mathbb{P}(Z_1=\cdots=Z_r=0)\leq 2^{-r}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:mcG of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For any initial condition ${\tt u}\in\R^{\mcb{n}}$, we define the increasing function $\mathcal{G}_{\tt u}:\R_{\geqslant0}\rightarrow\R_{\geqslant0}$ by 
\begin{equs}
    \mathcal{G}_{\tt u}:t\mapsto  \big(1+t^{36}\big){\| V 
    \|}_{C^{9}(B_0(t+|{\tt u}|))}^6\,.
\end{equs}

[Theorem thm:barbour of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Let $\Lambda \subseteq \Omega$ and $f : \Omega \to \mathbb{R}$ such that the following two conditions hold for some
positive numbers $V$ and $\Delta$, as well as some time $T \in \mathbb{N}$.
\begin{enumerate}[label=(\roman*)]
    \item

    A bound on a proxy for the variance of $f$: for all $x \in \Lambda$,
    \begin{equation}
        \sum_{x' \in \Omega} P(x,x') \sum_{t=0}^{T-1} \mleft(
            \mathbb{E}[f(X_t^x)] - \mathbb{E}[f(X_t^{x'})] \mright)^2 \leq V.
    \end{equation}
    \item

    A bound on the future expected difference, measured by $f$, between chains started at two adjacent initial states:
    for all $x \in \Lambda$, and $x' \in \Omega$ with $P(x,x') > 0$, and for all $t \geq 0$,
    \begin{equation}
        \mleft| \mathbb{E}[f(X_t^x)] - \mathbb{E}[f(X_t^{x'})] \mright| \leq \Delta.
    \end{equation}
\end{enumerate}
Then, for any $x \in \Lambda$, we have
\begin{equation}

    \mathbb{P} \mleft[
        X_t^x \in \Lambda \text{ for } 0 \leq t < T,
        \text{ and }
        |f(X_T^x) - \mathbb{E}[f(X_T^x)]| \geq \lambda
    \mright] \leq 2 \Exp{- \frac{\lambda^2}{2 V + \frac{4}{3} \Delta \lambda}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 10 of arXiv:2605.25762, 'Brownian Convergence of Planar Domains and Stability of the Planar Skorokhod Embedding Pro'] Let $p>0$. If for some $0<\delta<\tfrac{1}{2}$,
\begin{equation}
\max\left(\int^{\delta}_{0}|q_{n}-q|^{p}\,du,\int^{1}_{1-\delta}|q_{n}-q|^{p}\,du\right)\underset{n\to\infty}{\longrightarrow}0,
\end{equation}
then $\varphi_{n}\underset{n\to\infty}{\longrightarrow}\varphi$ in
$L^{p}_{2\pi}$ .

[Lemma lem:shift_X of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Assume that $\eta \in \Omega$.  For any $k, \ell \in {\mathbb{N}}$, $k > \ell$, $h \in {\mathbb{Z}}_{\ge 0}$ and $i \in {\mathbb{Z}}$, we have
                    \begin{align}
                        \xi_{\ell + h}\left(\eta, s_{k + h}\left(\eta, i\right)\right) 
                &= \xi_{\ell}\left(\Psi_{h}\left(\eta\right), s_{k}\left(\Psi_{h}\left(\eta\right), i\right) \right) \\
                &= s_{k - \ell}\left( \Psi_{\ell + h}\left(\eta\right), i \right) - s_{\infty}\left(\Psi_{\ell + h}\left(\eta\right), 0\right)  .
                    \end{align}
                In particular, if $s_{k + h}(\eta, i) = X^{(j)}_{k + h}(\eta,0)$ for some $j \in {\mathbb{Z}}$, then 
                    \begin{align}
                        s_{k - \ell}\left(\Psi_{\ell + h}\left(\eta\right), i \right) = X^{(j)}_{k-\ell}\left(\Psi_{\ell + h}\left(\eta\right),0\right) ,
                    \end{align}
                and thus
                    \begin{align}
                        \xi_{\ell + h}\left(\eta, X^{(j)}_{k + h}\left(\eta,0\right)\right) &= \xi_{\ell}\left(\Psi_{h}\left(\eta\right), X^{(j)}_{k}\left(\Psi_{h}\left(\eta\right),0\right) \right) \\
                        &= X^{(j)}_{k - \ell}\left( \Psi_{\ell+h}\left(\eta\right),0 \right) - s_{\infty}\left(\Psi_{\ell + h}\left(\eta\right), 0\right) \\
                        &= X^{(j)}_{k - \ell}\left( \Psi_{\ell+h}\left(\tilde{\eta}\right) ,0 \right) . 
                    \end{align}

