	\begin{align*}
	\forall n \in \mathbb{N}_+, \quad	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{  \frac{\Theta(n) K_n}{n \sqrt{n} } \sum_{z=1}^{L_n-1}  za(z) \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )   \Psi_{x,L_n}^{\alpha,\beta}(\eta_r^n)  \Bigg\}^{2} \Bigg] \leq \widehat{C} (t-s)^{2} f(n). 
