[Lemma lem:R3_integral-2 of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 1$, $\varepsilon \in (0,1) $, and denote
$\zeta_0 = \zeta \wedge \frac {d \wedge 2}2$.
Let $x\in{\mathbb Z^d}$ be a nonzero vector in the same direction as $\eta$,
i.e., $\eta = \abs \eta \hat x$.
If $d \le 2$, we further assume $\abs x \abs \eta \ge s_0$.
Then when $T \ge \varepsilon^{-1} \vee \varepsilon^{-(2+\zeta_0)/\zeta_0}$ and
$\abs x \ge 4dM / s_0$, we have
\begin{equation} 
\frac{ 1 }{ B(x; \eta )}
	\int_T^\infty \mathrm{d} t\, \abs{ I_{t}(x)
	- \hat g(0) \rho_t(x; \eta,\Lambda) }
\lesssim  e^{-c_1/\varepsilon}  + \frac 1 { \varepsilon^{d+1+\zeta_0} \abs x^{\zeta_0} }
	+ \frac 1 { \varepsilon^{ (d\vee4) + \zeta_0} \abs x^{\zeta_0 / 2} } ,
\end{equation}
with $c_1 = \frac 1 8 K_{\mathrm{IR}}$ and the implicit constant depending only on $d, \zeta, M, K_{\mathrm{IR}},s_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop_birth_sections of arXiv:2606.23648, '\textsc{Optimal Stopping for a Diffusion with Unobserved Bernoulli Drift}'] Under the standing assumptions of this section,
    \(
        x\in\mathcal I
    \)
    if and only if
    \begin{equation}
        \inf_{s>0}
        \left\{
            \frac12 k''(s)+G(s-x)k'(s)+c
        \right\}<0.
    \end{equation}
    Equivalently, under the assumption (ass_2 of the paper) 
    \begin{equation}
        x\in\mathcal I
        \quad\Longleftrightarrow\quad
        \exists\,s>0
        \text{ such that }
        G(s-x)<-P_k(s),
    \end{equation}
    with $P_k(\cdot)$ as in (equation Qk_def of the paper)
    Consequently, and with the convention \(\inf\emptyset=\infty\),
    \begin{equation}
        x_{birth}
        \coloneqq \inf \mathcal{I}
        =
        \inf\left\{
            x\ge0:
            \exists\,s>0
            \text{ such that }
            G(s-x)<-P_k(s)
        \right\}.
    \end{equation}

[Theorem 29 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $(\bu_0,\phi_0) \in\mathbb{H}$.
Then, for every $n \in \mathbb{N}$, there exists a unique strong global solution $\bX_n=(\bu_n,\phi_n)$ of the problem \eqref{eqn-Galerkin-Modified-stochastic-CHNSEs-n}. Moreover, for every $T>0$, 
\begin{equation}
\begin{aligned}
&\sup_{n \in \mathbb{N}} \mathbb{E}  \Bigl[\sup_{s \in [0,T ]} (\lvert \bu_n(s) \rvert_{\StokesH}^2 + \newK \vert \phi_n(s) \rvert_{\newone{H}}^2 +  \newK \Vert \psi(\phi_n(s)) \Vert_{L^1})
\\
&\hspace{1.5cm} + \delta_0 \Vert \bu_n \Vert_{L^2(0,T;\StokesV)}^2 +  \newK \Vert \cp_n \Vert_{L^2(0,T;\newone{H})}^{2}
+ \Vert \phi_n \Vert_{L^\beta(0,T;\newone{V})}^{\beta}  
+  \Vert \phi_n \Vert_{L^4(0,T;\newone{H})}^{4}\Bigr]
< \infty. 
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main result, general of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] If $\{f_{n}\}$ satisfy Assumption (assump:main assumption of the paper), then weakly as probability measures  \begin{equation}
	\llbracket A_{n,f_n}\rrbracket\Rightarrow \mu_{c,\Sigma},
\end{equation} 
where $\mu_{c,\Sigma}$ is the $\boxplus$-infinitely divisible distribution with L\'evy pair $(c,\Sigma)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

