[Lemma lem:population-saddle of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] For all sufficiently large $N$, equation (equation eq:population-saddle of the paper)
has a unique solution $w_N>2\tau_N$.  Moreover,
\begin{align}
 \frac{w_N}{A_N}
 &=1+O(A_N^{-2})+O(e^{-c\tau_N}),                      \\
 R_N
 &=2A_N+O(A_N^{-1})+O(e^{-c\tau_N}).                  
\end{align}
More precisely,
\begin{equation}
 w_N=A_N+\frac{3\sigma^2}{2A_N}+o(A_N^{-1}),
 \qquad
 R_N=2A_N+\frac{\sigma^2}{A_N}+o(A_N^{-1}).
\end{equation}
In particular, $w_N\sim A_N$ and $R_N\sim2A_N$.

[Lemma of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] \label[lemma]{lemma:cutoffsolnorm}
    The function $\tilde{U}$ satisfies 
    \[\|\tilde{U}\|_{L^2(V_N)}=O(N),\ \|\nabla \tilde{U}\|_{L^2(V_N)}=O(1),\ \|\Delta \tilde{U}\|_{L^2(V_N)}=O(N^{-\lambda/2}).\]

[Definition 5 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $K$ be a graph over $V$. An \textbf{allocation} on $K$ is a map $\theta: \vec{E}(K) \to [0, 1]$ such that, for any $(u \to v) \in \vec{E}(K)$, $\theta(u \to v) + \theta(v \to u) = 1$. Any such allocation induces a so-called \textbf{load} map
    \begin{equation}
    \begin{array}{c}
\partial \theta: 
\end{array} \hspace{5pt}
\begin{array}{rcl}
V & \longrightarrow & \R_+ \\
v & \longmapsto & \sum_{\{u, v\} \in E(K)} \theta(u \to v)
\end{array}.
\end{equation}

An allocation $\theta$ is said to be \textbf{balanced} if for any $e = \{u, v\} \in E(K)$, 
\begin{equation}
    \partial \theta(u) < \partial \theta(v) \Longrightarrow \theta(u \to v) = 0.
\end{equation}

Then, balanced allocations over $K$ exist, and they all share the same associated load function $w_K$. We call this map the \textbf{balanced load function} associated to $K$.

[Definition 1 of arXiv:2608.00449, 'First-order phase transitions in the hard-core model'] \label[definition]{def:phasetrans}
    If, for a given infinite graph $G$ and fugacity $\lambda>0$, there is only one hard-core measure on $G$ at fugacity $\lambda$, then we say $G$ has \emph{uniqueness} at $\lambda$. If there are multiple such measures, we say that $G$ has \emph{phase coexistence} at $\lambda$.
    If there exists some $\lambda^*=\lambda^*(G)$ such that $G$ has uniqueness for each $\lambda < \lambda^*$ and $G$ has phase coexistence for each $\lambda>\lambda^*$, then we say that a \emph{phase transition} occurs at $\lambda^*$, or more specifically that $\lambda^*$ is the \emph{Gibbs uniqueness threshold} for $G$.

[Prop 15 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that \ref{H0}, \ref{H0.5}, \ref{H1}, \ref{H2b} and \ref{H3} hold and let $x\in H$. Then, for every $T>0$, 
\begin{equation}
\lim_{n \to \infty}\sup_{t\in [0,T]}\mathbb{E}
\|X_{n}(t)-X(t)\|_H^2=0\,.
\end{equation}

