body:
[Theorem 19 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] Fix \(H\in(\frac{1}{2},1)\) and \(\beta<H\). Assume that \(G,H\) are Lipschitz continuous and globally bounded, \(F \) is $\gamma$-H\"older continuous \(\gamma<1\) such that \(\gamma+\beta>1\). Then, there exists a unique weak solution to the following Young-It\^o SDE
\begin{equation}
\dd Z_t = G_tZ_t \dd t+F_t Z_t \dd B^H_t + H_t\dd \hat W_t,\ \bar Z_0 = z,
\end{equation}
where the first integral is defined in the Young sense and the last one is in the It\^o sense. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 35 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exist a sequence $\{\varepsilon_n\}_{n \in \mathbb{N}} \subset (0,1)$ and a nonnegative function
$v_{\text{{\tiny $\delta$}}} \in W^{1,2}(0,T\,;L^2(\Omega)) \cap L^\infty (0,T\,;H^1(\Omega))$ such that the following convergences hold as $n \to \infty$\,:

\begin{gather}

\varepsilon_n \downarrow 0,\\

z_{\text{{\tiny $\delta,\!\varepsilon_n$}}} \longrightarrow v_{\text{{\tiny $\delta$}}} \quad \text{in} \quad C([0,T]\,;L^2(\Omega)),\\

v_{\text{{\tiny $\delta,\!\varepsilon_n$}}} \longrightarrow v_{\text{{\tiny $\delta$}}} \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),\\[0.1cm]
\text{weakly$^*$ in} \quad L^\infty (0,T\,;H^1(\Omega)).
\end{array}
\right.
\end{gather}

[Lemma cuttimes of arXiv:2411.13505, 'Capacity of loop-erased random walk'] We have
\begin{equation}
	\begin{split}
		\lim_{n\rightarrow\infty}\mathbb{E}\left[|n-\rho_{n(\log n)^{-1/3}}|\right]=\lim_{n\rightarrow\infty}\mathbb{E}\left[|(\log n)^{1/3}n-\ell_n|\right]=0.
	\end{split}
\end{equation}
Furthermore, there exists $C>0$ such that for all $n$ and all $m$ such that $|n-m|\geq (\log m)^{-6}m$,
\begin{equation}
	\mathbb{P}(\text{there are no cut times between $n$ and $m$})\leq C\frac{\log\log m}{\log m}.
\end{equation}

